def _candado_bd():
    """Un solo candado para toda la app (todas las sesiones/teléfonos comparten el mismo proceso):
    evita que dos sucursales guarden al mismo tiempo y una borre lo de la otra.
    Se guarda en sys.modules para que sobreviva a cada re-ejecución del script de Streamlit."""
    import sys
    import threading
    import types
    mod = sys.modules.get("_clubpark_candados")
    if mod is None:
        mod = types.ModuleType("_clubpark_candados")
        mod.bd = threading.RLock()
        mod = sys.modules.setdefault("_clubpark_candados", mod)
    return mod.bd



def _escribir_json_seguro(ruta, datos, compacto=False):
    """Escritura atómica con nombre temporal único (dos guardados simultáneos no chocan)."""
    import uuid as _uuid
    temporal = ruta.with_name(f".{ruta.stem}.{_uuid.uuid4().hex[:8]}.tmp")
    with temporal.open("w", encoding="utf-8") as f:
        if compacto:
            json.dump(datos, f, ensure_ascii=False, separators=(",", ":"))
        else:
            json.dump(datos, f, ensure_ascii=False, indent=2)
    os.replace(temporal, ruta)


def _rotar_a_archivo_mensual(lista, max_principal, prefijo, campo_fecha):
    """Deja en la lista principal solo los `max_principal` más recientes y manda el resto
    (agregándolos, sin reescribir todo) a archivos por mes: <prefijo>AAAA_MM.json."""
    if len(lista) <= max_principal:
        return lista
    principal, sobrantes = lista[:max_principal], lista[max_principal:]
    por_mes = {}
    for item in sobrantes:
        mes = str(item.get(campo_fecha) or "")[:7].replace("-", "_") or "sin_fecha"
        por_mes.setdefault(mes, []).append(item)
    for mes, items in por_mes.items():
        ruta_mes = DATA_DIR / f"{prefijo}{mes}.json"
        try:
            previos = json.loads(ruta_mes.read_text(encoding="utf-8")) if ruta_mes.exists() else []
            previos = previos if isinstance(previos, list) else []
        except (OSError, ValueError):
            previos = []
        _escribir_json_seguro(ruta_mes, items + previos, compacto=True)
    return principal



# ---------------------------------------------------------------------
# RESPALDO EN LA NUBE (Supabase): Streamlit Cloud borra los archivos del servidor cada vez
# que la app se reinicia (al subir cambios a GitHub o al dormirse). Con SUPABASE_URL y
# SUPABASE_KEY en los Secrets, cada archivo de datos (.json) se copia a Supabase y, cuando
# la app arranca sin datos, se recuperan solos desde ahí.
# ---------------------------------------------------------------------
def _secreto(nombre):
    try:
        valor = st.secrets.get(nombre, "")
    except Exception:
        valor = ""
    return str(valor or os.environ.get(nombre, "")).strip()


SUPA_URL = _secreto("SUPABASE_URL").rstrip("/")
SUPA_KEY = _secreto("SUPABASE_KEY")
NUBE_ACTIVA = bool(SUPA_URL and SUPA_KEY)
_NUBE_TABLA = "archivos"


def _nube_peticion(metodo, ruta_api, cuerpo=None, extra=None, timeout=30):
    import urllib.request
    cabeceras = {"apikey": SUPA_KEY, "Content-Type": "application/json"}
    if SUPA_KEY.startswith("eyJ"):  # llave clásica (service_role, JWT); las nuevas «sb_secret_…» van solo en apikey
        cabeceras["Authorization"] = f"Bearer {SUPA_KEY}"
    cabeceras.update(extra or {})
    peticion = urllib.request.Request(SUPA_URL + ruta_api, method=metodo, headers=cabeceras,
                                      data=json.dumps(cuerpo, ensure_ascii=False).encode("utf-8") if cuerpo is not None else None)
    with urllib.request.urlopen(peticion, timeout=timeout) as resp:
        texto = resp.read().decode("utf-8")
        return json.loads(texto) if texto.strip() else None


def _nube_peticion_texto(metodo, ruta_api, cuerpo_txt, extra=None, timeout=60):
    import urllib.request
    cabeceras = {"apikey": SUPA_KEY, "Content-Type": "application/json"}
    if SUPA_KEY.startswith("eyJ"):
        cabeceras["Authorization"] = f"Bearer {SUPA_KEY}"
    cabeceras.update(extra or {})
    peticion = urllib.request.Request(SUPA_URL + ruta_api, method=metodo, headers=cabeceras, data=cuerpo_txt.encode("utf-8"))
    with urllib.request.urlopen(peticion, timeout=timeout) as resp:
        resp.read()


@st.cache_resource(show_spinner=False)
def _estado_nube():
    """Estado compartido por toda la app: qué versión de cada archivo ya se subió."""
    import threading
    return {"subidos": {}, "candado": threading.Lock(), "restaurados": 0, "error": "", "ultimo_ok": ""}


@st.cache_resource(show_spinner="Recuperando datos guardados…")
def restaurar_desde_nube():
    """Se ejecuta una vez cada vez que arranca la app: baja de Supabase los archivos que falten aquí."""
    estado = _estado_nube()
    if not NUBE_ACTIVA:
        return 0
    try:
        filas = _nube_peticion("GET", f"/rest/v1/{_NUBE_TABLA}?select=nombre,contenido", timeout=60) or []
    except Exception as exc:
        estado["error"] = f"No se pudo leer el respaldo en la nube: {exc}"
        return 0
    n = 0
    for fila in filas:
        nombre = str(fila.get("nombre") or "")
        if not nombre.endswith(".json") or "/" in nombre or ".." in nombre:
            continue
        destino = DATA_DIR / nombre
        if destino.exists():
            continue  # lo local manda: solo se recupera lo que falta
        try:
            destino.write_text(json.dumps(fila.get("contenido"), ensure_ascii=False), encoding="utf-8")
            estado["subidos"][nombre] = destino.stat().st_mtime_ns
            n += 1
        except OSError:
            pass
    estado["restaurados"] = n
    return n


def sincronizar_nube():
    """Sube a Supabase los archivos de datos que cambiaron desde la última subida (en segundo plano)."""
    if not NUBE_ACTIVA:
        return
    import threading
    import time as _time
    estado = _estado_nube()
    if estado.get("en_curso"):
        return  # ya hay una subida en marcha: lo pendiente se sube en la siguiente vuelta
    envios = estado.setdefault("ultimo_envio", {})
    ahora_t = _time.time()
    cambiados = []
    for archivo in DATA_DIR.glob("*.json"):
        try:
            marca = archivo.stat().st_mtime_ns
        except OSError:
            continue
        # Con mucha operación, cada archivo se respalda como máximo cada 20 segundos (no en cada clic)
        try:
            espera = 20 if archivo.stat().st_size < 1_000_000 else 180  # archivos grandes: cada 3 minutos como máximo
        except OSError:
            continue
        if estado["subidos"].get(archivo.name) != marca and ahora_t - envios.get(archivo.name, 0) >= espera:
            cambiados.append((archivo, marca))
    if not cambiados:
        return
    estado["en_curso"] = True

    def _subir(lote):
        with estado["candado"]:
          try:
            for archivo, marca in lote:
                if estado["subidos"].get(archivo.name) == marca:
                    continue
                try:
                    # Se manda el texto tal cual (ya es JSON válido): no se vuelve a convertir, así no le quita
                    # procesador a la app mientras las sucursales trabajan
                    crudo = archivo.read_text(encoding="utf-8").strip() or "[]"
                    cuerpo_txt = ('[{"nombre":' + json.dumps(archivo.name) + ',"contenido":' + crudo
                                  + ',"actualizado":' + json.dumps(ahora_mx().isoformat()) + '}]')
                    _nube_peticion_texto("POST", f"/rest/v1/{_NUBE_TABLA}?on_conflict=nombre", cuerpo_txt,
                                         extra={"Prefer": "resolution=merge-duplicates,return=minimal"})
                    estado["subidos"][archivo.name] = marca
                    estado["ultimo_ok"] = ahora_mx().strftime("%d/%m/%Y %H:%M:%S")
                    estado["error"] = ""
                except Exception as exc:
                    estado["error"] = f"No se pudo respaldar {archivo.name}: {exc}"
                envios[archivo.name] = _time.time()
          finally:
            estado["en_curso"] = False

    threading.Thread(target=_subir, args=(cambiados,), daemon=True).start()


try:
    restaurar_desde_nube()
    sincronizar_nube()  # cambios de la ejecución anterior (por ejemplo, justo antes de un st.rerun)
except Exception:
    pass

