# ---------------------------------------------------------------------
# SESIÓN RECORDADA: si el teléfono bloquea la pantalla, cambia de app o pierde la señal,
# Streamlit abre una sesión nueva y antes pedía entrar otra vez. Ahora la sesión queda
# ligada a un código en la dirección (?s=...) que dura 24 horas o hasta «Cerrar sesión».
# ---------------------------------------------------------------------
SESIONES_FILE = DATA_DIR / "sesiones_activas.json"
HORAS_SESION = 24


def _leer_sesiones():
    try:
        datos = json.loads(SESIONES_FILE.read_text(encoding="utf-8"))
        return datos if isinstance(datos, dict) else {}
    except (OSError, ValueError):
        return {}


def _guardar_sesiones(datos):
    ahora_s = ahora_mx()
    vigentes = {k: v for k, v in datos.items() if str(v.get("vence", "")) > ahora_s.isoformat(timespec="seconds")}
    try:
        with _candado_bd():
            _escribir_json_seguro(SESIONES_FILE, vigentes, compacto=True)
    except OSError:
        pass


def crear_sesion_recordada(token_acceso, info):
    """Crea la sesión. Líder de Sucursal: solo una sesión abierta por sucursal; al entrar en un teléfono
    se cierra la que estuviera abierta en otro."""
    import secrets as _secrets
    codigo = _secrets.token_urlsafe(18)
    cerradas = 0
    with _candado_bd():
        sesiones = _leer_sesiones()
        if normalizar_rol(info.get("rol", ROL_LIDER)) == ROL_LIDER and info.get("sucursal"):
            otras = [k for k, v in sesiones.items() if v.get("sucursal") == info.get("sucursal")
                     and normalizar_rol(v.get("rol")) == ROL_LIDER]
            for k in otras:
                sesiones.pop(k, None)
            cerradas = len(otras)
        sesiones[codigo] = {"acceso": token_acceso, "nombre": info.get("nombre", "Usuario"), "sucursal": info.get("sucursal", ""),
                            "rol": info.get("rol", ROL_LIDER),
                            "vence": (ahora_mx() + timedelta(hours=HORAS_SESION)).isoformat(timespec="seconds")}
        _guardar_sesiones(sesiones)
    st.query_params["s"] = codigo
    st.session_state.codigo_sesion = codigo
    if cerradas:
        st.session_state.aviso_sesion_cerrada = cerradas
        try:
            guardar_evento_auditoria("SESIÓN ÚNICA POR SUCURSAL",
                                     f"{info.get('sucursal')} · entró {info.get('nombre')} · se cerraron {cerradas} sesión(es) en otro teléfono")
        except Exception:
            pass
    return cerradas


def cerrar_sesion_recordada():
    codigo = str(st.query_params.get("s", "") or "")
    if codigo:
        with _candado_bd():
            sesiones = _leer_sesiones()
            sesiones.pop(codigo, None)
            _guardar_sesiones(sesiones)
        try:
            del st.query_params["s"]
        except Exception:
            pass


if st.session_state.usuario_autenticado is None and st.query_params.get("s"):
    _ses = _leer_sesiones().get(str(st.query_params.get("s")))
    if (_ses and str(_ses.get("vence", "")) > ahora_mx().isoformat(timespec="seconds")
            and (_ses.get("acceso") in ACCESOS or _ses.get("acceso") == "__password__")):
        st.session_state.usuario_autenticado = _ses.get("nombre")
        st.session_state.sucursal_asignada = _ses.get("sucursal")
        st.session_state.rol = normalizar_rol(_ses.get("rol"))
        st.session_state.codigo_sesion = str(st.query_params.get("s"))
    else:
        try:
            del st.query_params["s"]
        except Exception:
            pass

# Una sola sesión por sucursal: si el Líder entró en otro teléfono, este se cierra
if st.session_state.usuario_autenticado and normalizar_rol(st.session_state.rol) == ROL_LIDER:
    _cod_ses = st.session_state.get("codigo_sesion") or str(st.query_params.get("s", "") or "")
    if _cod_ses and _cod_ses not in _leer_sesiones():
        st.session_state.aviso_sesion_otro_telefono = st.session_state.get("sucursal_asignada") or "esta sucursal"
        st.session_state.usuario_autenticado = None
        st.session_state.sucursal_asignada = None
        st.session_state.rol = None
        st.session_state.codigo_sesion = None
        try:
            del st.query_params["s"]
        except Exception:
            pass

