def _entero_seguro(valor):
    try:
        return max(0, int(float(valor or 0)))
    except (TypeError, ValueError):
        return 0


def _flotante_seguro(valor):
    try:
        return max(0.0, float(valor or 0))
    except (TypeError, ValueError):
        return 0.0


