def filas_gasto_de_ia(lectura, suc_defecto, fecha_defecto):
    filas, sin_suc = [], 0
    for g in lectura.get("gastos", []) or []:
        sitio = str(g.get("sitio", "") or "").strip()
        suc = sucursal_de_texto(sitio) if sitio else None
        if sitio and not suc:
            sin_suc += 1
        filas.append({"Fecha": fecha_de_celda(g.get("fecha"), fecha_defecto), "Sucursal": suc or suc_defecto,
                      "Categoría": categoria_gasto_de(g.get("categoria"), g.get("concepto")),
                      "Concepto": str(g.get("concepto", "")).strip() or "Gasto", "Importe": _flotante_seguro(g.get("importe"))})
    avisos = [f"{sin_suc} renglón(es) con una sucursal que no se reconoció; se puso {suc_defecto}. Revísalos."] if sin_suc else []
    return filas, avisos



def _leer_lista_json(ruta):
    if not ruta.exists():
        return []
    try:
        datos = json.loads(ruta.read_text(encoding="utf-8"))
        return datos if isinstance(datos, list) else []
    except (OSError, json.JSONDecodeError):
        return []


def _guardar_lista_json(ruta, datos):
    with _candado_bd():
        _escribir_json_seguro(ruta, datos)


def actualizar_lista_json(ruta, funcion):
    """Lee, modifica y guarda una lista dentro del candado (para cambios desde varios teléfonos a la vez)."""
    with _candado_bd():
        datos = _leer_lista_json(ruta)
        nuevos = funcion(datos)
        _escribir_json_seguro(ruta, datos if nuevos is None else nuevos)
        return datos if nuevos is None else nuevos


