def sumar_meses(fecha_base, meses):
    """Suma meses respetando fin de mes (31/01 + 1 mes = 28 o 29/02)."""
    import calendar
    mes_total = fecha_base.month - 1 + int(meses)
    anio, mes = fecha_base.year + mes_total // 12, mes_total % 12 + 1
    return date(anio, mes, min(fecha_base.day, calendar.monthrange(anio, mes)[1]))


def situacion_pension(p, hoy=None):
    """Devuelve (texto, días restantes) según la fecha 'pagado hasta'."""
    hoy = hoy or ahora_mx().date()
    if p.get("estado") == "Baja":
        return "⚫ Baja", None
    if p.get("estado") == "Suspendida":
        return "⏸️ Suspendida", None
    try:
        vence = date.fromisoformat(str(p.get("pagado_hasta")))
    except (TypeError, ValueError):
        return "🔴 Sin pago", None
    dias = (vence - hoy).days
    if dias < 0:
        return f"🔴 Vencida ({-dias} días)", dias
    if dias <= DIAS_AVISO_PENSION:
        return f"🟡 Por vencer ({dias} días)", dias
    return "🟢 Al corriente", dias


def buscar_pension_por_placa(placas, sucursal=None):
    placa_n = normalizar_placa(placas)
    if len(placa_n) < 3:
        return None
    for p in cargar_pensiones():
        if p.get("estado") != "Baja" and normalizar_placa(p.get("placas")) == placa_n \
                and (sucursal is None or p.get("sucursal") == sucursal):
            return p
    return None


def guardar_foto_pension(archivo, id_pension):
    imagen = archivo.copy() if isinstance(archivo, Image.Image) else Image.open(archivo)
    imagen = ImageOps.exif_transpose(imagen).convert("RGB")
    imagen.thumbnail((1600, 1600))
    ruta = FOTOS_PENSIONES_DIR / f"{id_pension}_{uuid.uuid4().hex[:6]}.jpg"
    imagen.save(ruta, format="JPEG", quality=80, optimize=True)
    return str(ruta)


def calcular_evento(ev):
    """Agrega ingreso de boletaje, ingreso total, gastos y utilidad al evento."""
    vehiculos = _entero_seguro(ev.get("vehiculos"))
    costo_boleto = _flotante_seguro(ev.get("costo_boleto"))
    costo_evento = _flotante_seguro(ev.get("costo_evento"))
    gastos = _flotante_seguro(ev.get("nomina")) + _flotante_seguro(ev.get("otros_gastos"))
    boletaje = vehiculos * costo_boleto
    ingreso = costo_evento + boletaje
    ev.update({"vehiculos": vehiculos, "costo_boleto": costo_boleto, "costo_evento": costo_evento,
               "ingreso_boletaje": round(boletaje, 2), "ingreso_total": round(ingreso, 2),
               "gastos_total": round(gastos, 2), "utilidad": round(ingreso - gastos, 2)})
    return ev


def cargar_eventos():
    return [calcular_evento(e) for e in _leer_lista_json(EVENTOS_FILE)]


def complementar_eventos_con_reportes(eventos):
    """Agrega a cada evento lo REAL de los reportes físicos del salón y día.
    - Reporte por evento (Evento k de n): se asigna al evento k (en orden de hora de inicio).
    - Reporte global del día: se reparte entre los eventos del día según su número de eventos.
    - Gastos: nómina y otros gastos del reporte de ingresos + reportes de gastos del salón ese día.
    Sin reporte, el evento se queda con lo programado (fuente «Programado»)."""
    reportes = _leer_lista_json(FISICOS_FILE)
    ingresos_dia, gastos_dia = {}, {}
    for r in reportes:
        dia = fecha_flexible(r.get("Fecha"))
        clave = (r.get("Sitio / Unidad"), dia)
        if r.get("tipo_reporte") == "ingresos":
            ingresos_dia.setdefault(clave, []).append(r)
            gastos_dia[clave] = gastos_dia.get(clave, 0.0) + _flotante_seguro(r.get("Nómina")) + _flotante_seguro(r.get("Otros gastos"))
        elif r.get("tipo_reporte") == "gastos":
            gastos_dia[clave] = gastos_dia.get(clave, 0.0) + _flotante_seguro(r.get("Total Gastos"))
    activos = [e for e in eventos if e.get("estado") != "Cancelado"]
    por_dia = {}
    for e in activos:
        por_dia.setdefault((e.get("sucursal"), fecha_flexible(e.get("fecha"))), []).append(e)
    salida = []
    for e in eventos:
        e = dict(e)
        e.update({"vehiculos_est": e["vehiculos"], "boletaje_est": e["ingreso_boletaje"], "ingreso_est": e["ingreso_total"],
                  "gastos_est": e["gastos_total"], "utilidad_est": e["utilidad"], "fuente": "Programado", "reportes_ids": ""})
        clave = (e.get("sucursal"), fecha_flexible(e.get("fecha")))
        reps = ingresos_dia.get(clave, [])
        if e.get("estado") == "Cancelado" or not reps:
            salida.append(e)
            continue
        hermanos = sorted(por_dia.get(clave, [e]), key=lambda x: (x.get("hora_inicio", ""), x.get("id", "")))
        # Lugares (números de evento) que le tocan a este registro: uno por cada evento que agrupa
        lugares, siguiente = {}, 1
        for h in hermanos:
            n_h = max(1, _entero_seguro(h.get("num_eventos")))
            lugares[h.get("id")] = list(range(siguiente, siguiente + n_h))
            siguiente += n_h
        total_eventos = siguiente - 1
        mis_lugares = set(lugares.get(e.get("id"), []))
        por_evento = [r for r in reps if _entero_seguro(r.get("evento_num"))]
        globales = [r for r in reps if not _entero_seguro(r.get("evento_num"))]
        if por_evento:
            mios = [r for r in por_evento if _entero_seguro(r.get("evento_num")) in mis_lugares]
            parte = len(mios) / max(1, len(por_evento))
            bol = sum(_flotante_seguro(r.get("Ingreso Bruto")) for r in mios)
            veh = sum(_entero_seguro(r.get("Boletos Cobrados")) for r in mios)
            gas = sum(_flotante_seguro(r.get("Nómina")) + _flotante_seguro(r.get("Otros gastos")) for r in mios)
            # gastos sueltos del día (reportes de gastos) se reparten por número de eventos
            gas_sueltos = gastos_dia.get(clave, 0.0) - sum(_flotante_seguro(r.get("Nómina")) + _flotante_seguro(r.get("Otros gastos")) for r in reps)
            gas += max(0.0, gas_sueltos) * len(mis_lugares) / max(1, total_eventos)
            ids = [r.get("ID") for r in mios]
            if not mios:
                salida.append(e)
                continue
        else:
            parte = len(mis_lugares) / max(1, total_eventos)
            bol = sum(_flotante_seguro(r.get("Ingreso Bruto")) for r in globales) * parte
            veh = round(sum(_entero_seguro(r.get("Boletos Cobrados")) for r in globales) * parte)
            gas = gastos_dia.get(clave, 0.0) * parte
            ids = [r.get("ID") for r in globales]
        if veh == 0 and bol > 0 and e.get("costo_boleto"):
            veh = round(bol / float(e["costo_boleto"]))  # salones con ingreso directo: vehículos estimados por el boletaje
        ingreso_real = e["costo_evento"] + bol
        e.update({"vehiculos": int(veh), "ingreso_boletaje": round(bol, 2), "ingreso_total": round(ingreso_real, 2),
                  "gastos_total": round(gas, 2), "utilidad": round(ingreso_real - gas, 2),
                  "fuente": "Reporte físico" + (" (global repartido)" if globales and not por_evento else ""),
                  "reportes_ids": ", ".join(str(i) for i in ids)})
        salida.append(e)
    return salida


_MESES_TXT = {"ENERO": 1, "FEBRERO": 2, "MARZO": 3, "ABRIL": 4, "MAYO": 5, "JUNIO": 6, "JULIO": 7, "AGOSTO": 8,
              "SEPTIEMBRE": 9, "SETIEMBRE": 9, "OCTUBRE": 10, "NOVIEMBRE": 11, "DICIEMBRE": 12}
_DIAS_TXT = {"LUNES": 0, "MARTES": 1, "MIERCOLES": 2, "JUEVES": 3, "VIERNES": 4, "SABADO": 5, "DOMINGO": 6}


def _norm_salon(texto):
    t = re.sub(r"[^A-Z0-9 ]", " ", _sin_acentos(texto))
    t = re.sub(r"\b(SALON|SALONES|JARDIN|EVENTOS?)\b", " ", t)
    return re.sub(r"\s+", " ", t).strip()


def emparejar_salon(nombre_txt, alias=None):
    """Sucursal/salón de la app que corresponde al nombre escrito en el formato (o None si no se reconoce)."""
    alias = alias if alias is not None else cargar_sucursales_config().get("alias_salones", {})
    n = _norm_salon(nombre_txt)
    if not n:
        return None
    if n in alias and alias[n] in PRECIOS_SUCURSALES:
        return alias[n]
    candidatos = list(dict.fromkeys(list(SALONES_EVENTOS) + list(SUCURSALES)))
    normal = {c: _norm_salon(c) for c in candidatos}
    for c, nc in normal.items():
        if nc == n:
            return c
    # El nombre del formato contiene al de la app o al revés (MAROMETA MARINA NACIONAL / SIPIRILY / SALÓN ROMANCE)
    # (solo entre salones de eventos: "SALÓN DURANGO" no debe confundirse con el estacionamiento SANATORIO DURANGO)
    parecidos = [c for c in SALONES_EVENTOS if normal[c] and (normal[c] in n or n in normal[c])]
    if len(parecidos) == 1:
        return parecidos[0]
    # Comparten la primera palabra y alguna otra (JUNGLA TLALPAN vs JUNGLA TLALPAN 2)
    pal = set(n.split())
    mejores = [c for c in SALONES_EVENTOS if len(pal & set(normal[c].split())) >= 2]
    return mejores[0] if len(mejores) == 1 else None


def parsear_eventos_semana(texto, hoy=None):
    """Lee el formato semanal que mandan los salones:
        SEMANA DEL 26 al 01 NOVIEMBRE
        MAROMETA SATÉLITE
        Viernes 11:00am
        Sábado 9:00am y 3:00pm
        JUNGLA EMPRESA
        Sábado
    Devuelve (lunes_de_la_semana | None, [ {salon_txt, dia, fecha, hora} ... ])."""
    hoy = hoy or ahora_mx().date()
    lineas = [l.strip() for l in str(texto or "").splitlines() if l.strip()]
    lunes = None
    filas, salon_txt = [], None
    for linea in lineas:
        t = _sin_acentos(linea)
        m = re.search(r"SEMANA\s+DEL?\s+(\d{1,2})\s*(?:DE\s+)?([A-Z]+)?\s*(?:AL|A)\s+(\d{1,2})\s*(?:DE\s+)?([A-Z]+)?", t)
        if m:
            d1, mes1, d2, mes2 = int(m.group(1)), _MESES_TXT.get(m.group(2) or ""), int(m.group(3)), _MESES_TXT.get(m.group(4) or "")
            mes2 = mes2 or mes1 or hoy.month
            mes1 = mes1 or (mes2 if d1 <= d2 else (mes2 - 2) % 12 + 1)
            anio2 = hoy.year + (1 if mes2 < hoy.month - 6 else 0) - (1 if mes2 > hoy.month + 6 else 0)
            anio1 = anio2 - 1 if mes1 > mes2 else anio2
            try:
                inicio = date(anio1, mes1, d1)
                lunes = inicio - timedelta(days=inicio.weekday())
            except ValueError:
                lunes = None
            continue
        palabra = re.split(r"[\s,.:]+", t)[0] if t else ""
        if palabra in _DIAS_TXT:
            if not salon_txt:
                continue
            horas = []
            for h, mi, ap in re.findall(r"(\d{1,2})(?::(\d{2}))?\s*(AM|PM|A\.M\.|P\.M\.|HRS?)?", t[len(palabra):]):
                hh, mm = int(h), int(mi or 0)
                if ap.startswith("P") and hh < 12:
                    hh += 12
                if ap.startswith("A") and hh == 12:
                    hh = 0
                if 0 <= hh <= 23 and 0 <= mm <= 59 and (mi or ap):
                    horas.append(f"{hh:02d}:{mm:02d}")
            for hora in (horas or [""]):
                filas.append({"salon_txt": salon_txt, "dia": palabra, "dia_idx": _DIAS_TXT[palabra], "hora": hora})
        else:
            salon_txt = linea.strip()
    if lunes is None:
        lunes = hoy - timedelta(days=hoy.weekday()) + timedelta(days=7)  # sin encabezado: la semana siguiente
    for f in filas:
        f["fecha"] = lunes + timedelta(days=f["dia_idx"])
    return lunes, filas


def guardar_eventos(eventos):
    _guardar_lista_json(EVENTOS_FILE, sorted(eventos, key=lambda e: (e.get("fecha", ""), e.get("hora_inicio", ""))))


# ---------------------------------------------------------------------
# CONTROL DE DUPLICADOS EN EL INGRESO DE VEHÍCULOS
# ---------------------------------------------------------------------
PLACAS_GENERICAS = {"SINPLACA", "SINPLACAS", "SP", "NA", "NOAPLICA", "SINPLACAS0", "PERMISO", "0"}
VENTANA_DUPLICADO_MIN = 3  # minutos: mismo vehículo registrado dos veces casi al mismo tiempo


def normalizar_placa(valor):
    return re.sub(r"[^A-Z0-9]", "", str(valor or "").upper())


def buscar_duplicado_ingreso(registros, sucursal, placas, marca="", color=""):
    """Devuelve (registro, motivo) si el vehículo ya está registrado; (None, "") si no.
    1) Placa real que ya está En Resguardo (en cualquier sucursal).
    2) Mismo vehículo en la misma sucursal registrado hace menos de VENTANA_DUPLICADO_MIN minutos
       (doble toque al botón o doble captura), incluido el caso de autos sin placa."""
    placa_n = normalizar_placa(placas)
    marca_n, color_n = normalizar_placa(marca), normalizar_placa(color)
    generica = placa_n in PLACAS_GENERICAS or len(placa_n) < 3
    ahora_d = ahora_mx()
    for r in registros:
        if not generica and r.get("estado", "En Resguardo") == "En Resguardo" and normalizar_placa(r.get("placas")) == placa_n:
            return r, "ya está en resguardo"
        if r.get("sucursal") != sucursal:
            continue
        try:
            entrada_r = datetime.fromisoformat(str(r.get("fecha_entrada_iso") or ""))
        except ValueError:
            continue
        if abs((ahora_d - entrada_r).total_seconds()) > VENTANA_DUPLICADO_MIN * 60:
            continue
        mismo = (normalizar_placa(r.get("placas")) == placa_n) if not generica else (
            normalizar_placa(r.get("marca")) == marca_n and normalizar_placa(r.get("color")) == color_n)
        if mismo:
            return r, f"se registró hace menos de {VENTANA_DUPLICADO_MIN} minutos"
    return None, ""


# ---------------------------------------------------------------------
# MERCADO PAGO: link y QR de cobro (Checkout Pro) + verificación del pago
# Requiere el secreto MP_ACCESS_TOKEN (Access Token de producción de la cuenta
# de Club Park). El folio del vehículo viaja como referencia externa.
# ---------------------------------------------------------------------
METODO_MP = "Mercado Pago"


def _mp_token():
    try:
        valor = st.secrets.get("MP_ACCESS_TOKEN", "")
    except Exception:
        valor = ""
    return str(valor or os.environ.get("MP_ACCESS_TOKEN", "")).strip()


def mp_disponible():
    return bool(_mp_token())


def _mp_api(metodo, ruta_api, datos=None):
    import urllib.error
    import urllib.request
    token = _mp_token()
    if not token:
        raise RuntimeError("Falta configurar MP_ACCESS_TOKEN en los secretos de la app.")
    peticion = urllib.request.Request(
        "https://api.mercadopago.com" + ruta_api,
        data=json.dumps(datos).encode("utf-8") if datos is not None else None,
        method=metodo,
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json",
                 "X-Idempotency-Key": uuid.uuid4().hex},
    )
    try:
        with urllib.request.urlopen(peticion, timeout=25) as resp:
            return json.loads(resp.read().decode("utf-8") or "{}")
    except urllib.error.HTTPError as exc:
        detalle = exc.read().decode("utf-8", "replace")[:250]
        raise RuntimeError(f"Mercado Pago respondió {exc.code}: {detalle}")
    except Exception as exc:
        raise RuntimeError(f"No se pudo conectar con Mercado Pago: {exc}")


def mp_crear_cobro(folio, sucursal, importe, minutos_vigencia=30):
    """Crea un link de pago por el importe exacto. Devuelve {'pref_id', 'link', 'importe', 'creado'}."""
    if float(importe) <= 0:
        raise RuntimeError("El importe debe ser mayor a $0 para cobrar con Mercado Pago.")
    ahora_p = datetime.now(_TZ_MX)
    respuesta = _mp_api("POST", "/checkout/preferences", {
        "items": [{"id": str(folio), "title": f"Estacionamiento Club Park · {sucursal} · folio {folio}",
                   "quantity": 1, "unit_price": round(float(importe), 2), "currency_id": "MXN"}],
        "external_reference": str(folio),
        "statement_descriptor": "CLUB PARK",
        "expires": True,
        "expiration_date_from": ahora_p.isoformat(timespec="milliseconds"),
        "expiration_date_to": (ahora_p + timedelta(minutes=minutos_vigencia)).isoformat(timespec="milliseconds"),
    })
    link = respuesta.get("init_point")
    if not link:
        raise RuntimeError("Mercado Pago no devolvió el link de pago.")
    return {"pref_id": respuesta.get("id"), "link": link, "importe": round(float(importe), 2),
            "creado": ahora_mx().strftime("%Y-%m-%d %H:%M:%S")}


def mp_buscar_pago(folio):
    """Busca el pago más reciente con la referencia del folio. Devuelve el aprobado si existe; si no, el último."""
    respuesta = _mp_api("GET", "/v1/payments/search?" + urllib.parse.urlencode(
        {"external_reference": str(folio), "sort": "date_created", "criteria": "desc", "limit": 20}))
    pagos_mp = respuesta.get("results") or []
    aprobado = next((p for p in pagos_mp if p.get("status") == "approved"), None)
    return aprobado or (pagos_mp[0] if pagos_mp else None)


def mp_ids_ya_usados():
    """Números de operación de Mercado Pago que ya quedaron ligados a algún folio (no se pueden reutilizar)."""
    usados = set()
    for r in cargar_bd():
        for pg in r.get("pagos") or []:
            if pg.get("mp_payment_id"):
                usados.add(str(pg["mp_payment_id"]))
    return usados


def mp_buscar_pagos_tap(importe, desde_dt):
    """Pagos aprobados de la cuenta por el importe exacto, hechos desde `desde_dt` y que no estén ligados a otro folio.
    Sirve para los cobros con Point Tap (el celular como terminal), que no traen el folio como referencia."""
    inicio = (desde_dt - timedelta(minutes=2)).astimezone(_TZ_MX)
    fin = datetime.now(_TZ_MX) + timedelta(minutes=2)
    respuesta = _mp_api("GET", "/v1/payments/search?" + urllib.parse.urlencode({
        "sort": "date_created", "criteria": "desc", "limit": 50, "status": "approved",
        "range": "date_created", "begin_date": inicio.isoformat(timespec="milliseconds"),
        "end_date": fin.isoformat(timespec="milliseconds")}))
    usados = mp_ids_ya_usados()
    candidatos = []
    for pg in respuesta.get("results") or []:
        if pg.get("status") != "approved" or str(pg.get("id")) in usados:
            continue
        if abs(float(pg.get("transaction_amount") or 0) - float(importe)) >= 0.01:
            continue
        candidatos.append({
            "id": str(pg.get("id")), "importe": float(pg.get("transaction_amount") or 0),
            "tipo": pg.get("payment_type_id", ""), "fecha": pg.get("date_approved") or pg.get("date_created") or "",
            "tarjeta": str((pg.get("card") or {}).get("last_four_digits") or ""),
            "metodo_mp": pg.get("payment_method_id", ""),
        })
    return candidatos


def mp_link_point_tap(importe, descripcion):
    """Enlace de Mercado Pago para abrir el cobro en el celular con el monto ya puesto (experimental en Point Tap)."""
    return "https://secure.mlstatic.com/org-img/point/app/index.html?" + urllib.parse.urlencode(
        {"amount": f"{float(importe):.2f}", "description": descripcion[:60]})


# Abre la app de Mercado Pago en Android (si no está instalada, abre la tienda)
MP_ABRIR_APP_ANDROID = ("intent://#Intent;package=com.mercadopago.wallet;"
                        "S.browser_fallback_url=https%3A%2F%2Fplay.google.com%2Fstore%2Fapps%2Fdetails%3Fid%3Dcom.mercadopago.wallet;end")


# ---------------------------------------------------------------------
# JORNADA OPERATIVA POR SUCURSAL
# Una jornada empieza con el primer movimiento después del último cierre diario y termina
# cuando se guarda el cierre. Todo lo de la jornada lleva su fecha operativa, aunque pase de
# medianoche (restaurantes que cierran de madrugada). No se capturan horarios.
# ---------------------------------------------------------------------
JORNADAS_FILE = DATA_DIR / "jornadas_operativas.json"


def cargar_jornadas():
    return _leer_lista_json(JORNADAS_FILE)


def _jornada_sin_movimiento(j):
    """True si en esa jornada no se registró ni cobró ningún vehículo."""
    fecha = str(j.get("fecha_operativa") or "")
    suc = j.get("sucursal")
    for r in cargar_bd_rapido():
        if r.get("sucursal") != suc:
            continue
        if str(r.get("fecha_operativa") or "") == fecha:
            return False
        if any(str(p.get("fecha_operativa") or "") == fecha for p in (r.get("pagos") or [])):
            return False
    return True


def jornada_abierta(sucursal):
    j = next((j for j in cargar_jornadas() if j.get("sucursal") == sucursal and j.get("estado") == "Abierta"), None)
    if j and str(j.get("fecha_operativa") or "") < ahora_mx().date().isoformat():
        # Un turno de días anteriores sin ningún vehículo no cuenta: el turno empieza con el primer vehículo registrado.
        try:
            if _jornada_sin_movimiento(j):
                with _candado_bd():
                    jornadas = cargar_jornadas()
                    for x in jornadas:
                        if x.get("id") == j.get("id") and x.get("estado") == "Abierta":
                            x.update({"estado": "Descartada", "cerrada_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                                      "cerrada_por": "Sistema (turno sin vehículos)"})
                    _guardar_lista_json(JORNADAS_FILE, jornadas[:5000])
                guardar_evento_auditoria("TURNO SIN MOVIMIENTO DESCARTADO",
                                         f"{sucursal} · fecha operativa {j.get('fecha_operativa')} · abierto {j.get('abierta_en', '')} sin vehículos")
                return None
        except Exception:
            pass
    return j


def jornada_actual(sucursal, crear=True):
    """Jornada abierta de la sucursal; si no hay y crear=True, abre una nueva (el siguiente vehículo inicia la jornada)."""
    j = jornada_abierta(sucursal)
    if j and crear and _jornada_vencida(j):
        _vencer_jornada(j)   # turno de hace 2 días o más sin cierre: no se le siguen sumando vehículos
        j = None
    if j or not crear or not sucursal:
        return j
    with _candado_bd():
        j = jornada_abierta(sucursal)  # otra sesión pudo abrirla mientras tanto
        if j and not _jornada_vencida(j):
            return j
        return _abrir_jornada(sucursal)


JORNADA_MAX_DIAS = 1   # un turno puede pasar de medianoche, pero no seguir abierto al segundo día


def _jornada_vencida(j):
    try:
        return (ahora_mx().date() - date.fromisoformat(str(j.get("fecha_operativa")))).days > JORNADA_MAX_DIAS
    except ValueError:
        return False


def _vencer_jornada(j):
    """Cierra un turno que se quedó abierto días: lo nuevo empieza un turno con la fecha de hoy.
    El cierre (reporte) de ese día se puede hacer después; queda pendiente en el cierre diario."""
    try:
        with _candado_bd():
            jornadas = cargar_jornadas()
            for x in jornadas:
                if x.get("id") == j.get("id") and x.get("estado") == "Abierta":
                    x.update({"estado": "Cerrada", "vencida": True, "cerrada_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                              "cerrada_por": "Sistema (turno vencido sin cierre)"})
            _guardar_lista_json(JORNADAS_FILE, jornadas[:5000])
        guardar_evento_auditoria("TURNO VENCIDO SIN CIERRE",
                                 f"{j.get('sucursal')} · fecha operativa {j.get('fecha_operativa')} · abierto {j.get('abierta_en', '')}; "
                                 "lo nuevo cuenta en un turno con la fecha de hoy. Falta guardar el cierre de ese día.")
    except Exception:
        pass


def _abrir_jornada(sucursal):
    ahora_j = ahora_mx()
    fecha_j = ahora_j.date()
    cerradas = [date.fromisoformat(x["fecha_operativa"]) for x in cargar_jornadas()
                if x.get("sucursal") == sucursal and x.get("estado") == "Cerrada" and x.get("fecha_operativa")]
    if cerradas and fecha_j <= max(cerradas):
        fecha_j = max(cerradas) + timedelta(days=1)  # ese día ya se cerró: la jornada nueva es la del día siguiente
    j = {"id": f"J_{uuid.uuid4().hex[:8].upper()}", "sucursal": sucursal, "fecha_operativa": fecha_j.isoformat(),
         "estado": "Abierta", "abierta_en": ahora_j.strftime("%Y-%m-%d %H:%M:%S"),
         "abierta_por": st.session_state.get("usuario_autenticado") or "Sistema"}
    jornadas = cargar_jornadas()
    jornadas.insert(0, j)
    _guardar_lista_json(JORNADAS_FILE, jornadas[:5000])
    guardar_evento_auditoria("JORNADA ABIERTA", f"{sucursal} · fecha operativa {fecha_j:%d/%m/%Y}")
    return j


def fecha_operativa_actual(sucursal, crear=True):
    j = jornada_actual(sucursal, crear=crear)
    return date.fromisoformat(j["fecha_operativa"]) if j else ahora_mx().date()


import functools as _functools_f


@_functools_f.lru_cache(maxsize=4096)
def _fecha_iso_rapida(valor):
    """'2026-10-31' -> date, con memoria (sin excepciones en el camino común)."""
    try:
        return date.fromisoformat(valor)
    except ValueError:
        return None


def _fecha_op_de(valor, respaldo):
    if isinstance(valor, str) and len(valor) == 10:
        d = _fecha_iso_rapida(valor)
        if d is not None:
            return d
    return fecha_flexible(respaldo)


def fecha_op_registro(r):
    """Fecha operativa del ingreso del vehículo (si no la tiene, la fecha de calendario de entrada)."""
    return _fecha_op_de(r.get("fecha_operativa"), r.get("fecha_entrada") or r.get("fecha"))


def fecha_op_pago(p):
    return _fecha_op_de(p.get("fecha_operativa"), p.get("fecha_hora"))


def fecha_op_salida(r):
    return _fecha_op_de(r.get("salida_fecha_operativa"), r.get("salida_fecha"))


def cerrar_jornada(sucursal, fecha_operativa, cierre_id):
    with _candado_bd():
        return _cerrar_jornada(sucursal, fecha_operativa, cierre_id)


def _cerrar_jornada(sucursal, fecha_operativa, cierre_id):
    jornadas = cargar_jornadas()
    cambio = False
    for j in jornadas:
        if j.get("sucursal") == sucursal and j.get("fecha_operativa") == str(fecha_operativa) and j.get("estado") == "Abierta":
            j.update({"estado": "Cerrada", "cerrada_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"), "cierre_id": cierre_id,
                      "cerrada_por": st.session_state.get("usuario_autenticado") or "Sistema"})
            cambio = True
    if not cambio:  # cierre de un día sin jornada registrada: se deja constancia como cerrada
        jornadas.insert(0, {"id": f"J_{uuid.uuid4().hex[:8].upper()}", "sucursal": sucursal, "fecha_operativa": str(fecha_operativa),
                            "estado": "Cerrada", "abierta_en": "", "cerrada_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                            "cierre_id": cierre_id, "cerrada_por": st.session_state.get("usuario_autenticado") or "Sistema"})
    _guardar_lista_json(JORNADAS_FILE, jornadas[:5000])


# ---------------------------------------------------------------------
# REPORTES FÍSICOS PENDIENTES POR SUPERVISOR
# Sucursales de servicio: se espera un reporte de ingresos por cada día que opera (según sus días del catálogo).
# Salones: se espera reporte solo los días con eventos registrados (no cancelados).
# ---------------------------------------------------------------------
_DIAS_SEMANA_IDX = {"LUNES": 0, "MARTES": 1, "MIERCOLES": 2, "JUEVES": 3, "VIERNES": 4, "SABADO": 5, "DOMINGO": 6}


def dias_que_opera(texto):
    """'LUNES A DOMINGO' -> {0..6}; 'SÁBADO Y DOMINGO' -> {5, 6}; 'VIERNES A DOMINGO' -> {4, 5, 6}."""
    t = _sin_acentos(texto or "")
    nombres = [d for d in re.findall(r"[A-Z]+", t) if d in _DIAS_SEMANA_IDX]
    if " A " in f" {t} " and len(nombres) >= 2:
        a, b = _DIAS_SEMANA_IDX[nombres[0]], _DIAS_SEMANA_IDX[nombres[1]]
        return set(range(a, b + 1)) if a <= b else set(range(a, 7)) | set(range(0, b + 1))
    return {_DIAS_SEMANA_IDX[d] for d in nombres} or set(range(7))


def entrega_de_sucursal(sucursal, cfg=None):
    """¿La sucursal entrega reporte físico y/o efectivo? (por defecto, sí a ambos)."""
    cfg = cfg or cargar_sucursales_config()
    e = cfg.get("entregas", {}).get(sucursal, {})
    return {"reporte": bool(e.get("reporte", True)), "efectivo": bool(e.get("efectivo", True))}


def reportes_pendientes(desde, hasta):
    """Lista de faltantes: [{'sucursal','fecha','supervisor','tipo','nota'}] hasta ayer como máximo."""
    hasta = min(hasta, ahora_mx().date() - timedelta(days=1))
    if hasta < desde:
        return []
    reportes = [r for r in _leer_lista_json(FISICOS_FILE) if r.get("tipo_reporte") == "ingresos"]
    fisicos = {(r.get("Sitio / Unidad"), fecha_flexible(r.get("Fecha"))) for r in reportes if r.get("origen") != "Cierre del sistema"}
    # Eventos: cada evento lleva su reporte (o un reporte global del día que los cubre todos)
    globales_dia, eventos_cubiertos = set(), {}
    for r in reportes:
        if r.get("origen") == "Cierre del sistema":
            continue
        clave_r = (r.get("Sitio / Unidad"), fecha_flexible(r.get("Fecha")))
        if _entero_seguro(r.get("evento_num")):
            eventos_cubiertos.setdefault(clave_r, set()).add(_entero_seguro(r.get("evento_num")))
        else:
            globales_dia.add(clave_r)
    cfg_ent = cargar_sucursales_config()
    solo_cierre = {(r.get("Sitio / Unidad"), fecha_flexible(r.get("Fecha"))) for r in reportes if r.get("origen") == "Cierre del sistema"}
    eventos_dia = {}
    for e in cargar_eventos():
        if e.get("estado") == "Cancelado":
            continue
        clave = (e.get("sucursal"), fecha_flexible(e.get("fecha")))
        eventos_dia.setdefault(clave, []).append(e)
    pendientes = []
    descartados = set(cargar_sucursales_config().get("pendientes_descartados", {}))
    for item in CATALOGO_OFICIAL_23:
        suc = item["sitio"]
        if suc not in PRECIOS_SUCURSALES:
            continue
        es_salon = suc in SALONES_EVENTOS
        entrega_rep = entrega_de_sucursal(suc, cfg_ent)["reporte"]
        dias_ok = dias_que_opera(item.get("dias"))
        d = desde
        while d <= hasta:
            descartado = f"{suc}|{d.isoformat()}" in descartados
            evs = eventos_dia.get((suc, d), [])
            if evs:
                # Si hay evento, hay reporte físico de ese evento (aunque la sucursal no entregue reporte diario)
                n_ev = sum(max(1, _entero_seguro(e.get("num_eventos"))) for e in evs)
                cubiertos = len(eventos_cubiertos.get((suc, d), set()))
                if (suc, d) not in globales_dia and cubiertos < n_ev and not descartado:
                    faltan = n_ev - cubiertos
                    pendientes.append({"sucursal": suc, "fecha": d, "supervisor": SUP_AMBOS, "tipo": f"Evento ({n_ev})",
                                       "nota": (f"faltan {faltan} de {n_ev} reporte(s) de evento" if cubiertos else
                                                ("solo hay cierre del sistema" if (suc, d) in solo_cierre else
                                                 (f"{n_ev} evento(s): un reporte por evento o uno global" if n_ev > 1 else "")))})
            elif not es_salon and entrega_rep and d.weekday() in dias_ok and (suc, d) not in fisicos and not descartado:
                pendientes.append({"sucursal": suc, "fecha": d, "supervisor": item.get("supervisor"), "tipo": "Servicio",
                                   "nota": "solo hay cierre del sistema" if (suc, d) in solo_cierre else ""})
            d += timedelta(days=1)
    return pendientes


def _texto_pendientes(nombre, periodo_txt, lista):
    por_suc = {}
    for p in sorted(lista, key=lambda x: (x["sucursal"], x["fecha"])):
        por_suc.setdefault(p["sucursal"], []).append(p)
    lineas = ["*CLUB PARK · REPORTES FÍSICOS PENDIENTES*", f"Supervisor: *{nombre}*", periodo_txt, ""]
    if not lista:
        lineas.append("✅ No tienes reportes pendientes en este periodo. ¡Gracias!")
    else:
        lineas.append("Te hace falta subir el reporte físico de:")
        for suc, items in por_suc.items():
            fechas = ", ".join(f"{NOMBRES_DIA[p['fecha'].weekday()][:3]} {p['fecha']:%d/%m}" + (" (evento)" if str(p["tipo"]).startswith("Evento") else "")
                               for p in items)
            lineas.append(f"• *{suc}*: {fechas}")
        lineas += ["", f"Total: {len(lista)} reporte(s). Favor de subirlos en la app (📄 Reportes físicos). Gracias."]
    return "\n".join(lineas)


def panel_whatsapp_pendientes(pendientes, periodo_txt, key, solo_supervisor=None):
    """Un recuadro por supervisor con el mensaje de lo que le falta y el botón para enviarlo por WhatsApp.
    El Contador elige qué pendientes van en el mensaje, puede editar el texto y quitar los que no aplican."""
    import hashlib
    cfg_tel = cargar_sucursales_config()
    tels = cfg_tel.get("telefonos_sup", {})
    es_cont = usuario_es_contador()
    claves = [solo_supervisor] if solo_supervisor else list(SUPERVISORES_NOMBRE)
    for clave in claves:
        mios = sorted([p for p in pendientes if p.get("supervisor") in (clave, SUP_AMBOS)], key=lambda x: (x["fecha"], x["sucursal"]))
        nombre = SUPERVISORES_NOMBRE.get(clave, clave)
        with st.expander(f"👔 {nombre} · {len(mios)} pendiente(s)", expanded=bool(mios)):
            seleccion = mios
            if mios and es_cont:
                st.caption("✏️ Marca **Enviar** en los que quieres incluir en el mensaje. Marca **No aplica** para quitar un pendiente "
                           "(por ejemplo, la sucursal no abrió ese día) y pulsa «Quitar de pendientes».")
                df_p = pd.DataFrame([{"Enviar": True, "No aplica": False, "Sucursal": p["sucursal"], "Fecha": p["fecha"].strftime("%d/%m/%Y"),
                                      "Día": NOMBRES_DIA[p["fecha"].weekday()], "Tipo": p["tipo"], "Nota": p["nota"],
                                      "_clave": f"{p['sucursal']}|{p['fecha'].isoformat()}"} for p in mios])
                firma_p = hashlib.md5("".join(df_p["_clave"]).encode("utf-8")).hexdigest()[:8]
                b1, b2 = st.columns(2)
                todos_p = b1.checkbox("Marcar todos para enviar", value=True, key=f"{key}_todos_{clave}_{firma_p}")
                if not todos_p:
                    df_p["Enviar"] = False
                editado_p = st.data_editor(
                    df_p, use_container_width=True, hide_index=True, key=f"{key}_ed_{clave}_{firma_p}_{todos_p}",
                    column_config={"Enviar": st.column_config.CheckboxColumn("Enviar"),
                                   "No aplica": st.column_config.CheckboxColumn("No aplica"),
                                   "_clave": None},
                    disabled=["Sucursal", "Fecha", "Día", "Tipo", "Nota", "_clave"],
                )
                filas_p = editado_p.to_dict("records")
                claves_env = {f["_clave"] for f in filas_p if f.get("Enviar") and not f.get("No aplica")}
                claves_quitar = [f["_clave"] for f in filas_p if f.get("No aplica")]
                seleccion = [p for p in mios if f"{p['sucursal']}|{p['fecha'].isoformat()}" in claves_env]
                if b2.button(f"🚫 Quitar de pendientes ({len(claves_quitar)})", disabled=not claves_quitar, key=f"{key}_quitar_{clave}_{firma_p}"):
                    cfg_d = cargar_sucursales_config()
                    desc = cfg_d.setdefault("pendientes_descartados", {})
                    for c_q in claves_quitar:
                        desc[c_q] = {"por": st.session_state.get("usuario_autenticado"), "en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S")}
                    guardar_sucursales_config(cfg_d)
                    guardar_evento_auditoria("PENDIENTES QUITADOS", f"{len(claves_quitar)}: " + ", ".join(claves_quitar[:20]))
                    st.rerun()
            elif mios:
                st.dataframe(pd.DataFrame([{"Sucursal": p["sucursal"], "Fecha": p["fecha"].strftime("%d/%m/%Y"),
                                            "Día": NOMBRES_DIA[p["fecha"].weekday()], "Tipo": p["tipo"], "Nota": p["nota"]}
                                           for p in mios]), use_container_width=True, hide_index=True)
            texto = _texto_pendientes(nombre, periodo_txt, seleccion)
            firma_t = hashlib.md5(texto.encode("utf-8")).hexdigest()[:8]
            texto = st.text_area("Mensaje" + (" (puedes editarlo antes de enviar)" if es_cont else ""), texto, height=200,
                                 key=f"{key}_txt_{clave}_{firma_t}", disabled=not es_cont)
            tel = re.sub(r"\D", "", str(tels.get(clave, "")))
            if es_cont:
                t1, t2 = st.columns([3, 1])
                nuevo = t1.text_input("WhatsApp del supervisor (10 dígitos)", value=tel[-10:] if tel else "", key=f"{key}_tel_{clave}")
                t2.write("")
                if t2.button("💾 Guardar", key=f"{key}_tel_btn_{clave}"):
                    dig = re.sub(r"\D", "", nuevo)
                    if dig and len(dig) != 10:
                        st.error("El número debe tener 10 dígitos.")
                    else:
                        cfg_tel.setdefault("telefonos_sup", {})[clave] = dig
                        guardar_sucursales_config(cfg_tel)
                        st.success("Número guardado.")
                        st.rerun()
            destino = f"52{tel[-10:]}" if len(tel) >= 10 else ""
            st.link_button(f"💬 Enviar por WhatsApp a {nombre}", f"https://wa.me/{destino}?text=" + urllib.parse.quote(texto),
                           use_container_width=True, disabled=bool(mios) and not seleccion and es_cont)
            if not destino:
                st.caption("Sin número guardado: WhatsApp te pedirá elegir el contacto.")
    if es_cont and not solo_supervisor:
        huerfanos = [p for p in pendientes if p.get("supervisor") not in SUPERVISORES_NOMBRE and p.get("supervisor") != SUP_AMBOS]
        if huerfanos:
            st.warning(f"⚠️ {len(huerfanos)} pendiente(s) de sucursales **sin supervisor asignado**: no le llegan a ningún supervisor. "
                       "Asigna el supervisor de esas sucursales en 💲 Tarifas.")
            st.dataframe(pd.DataFrame([{"Sucursal": p["sucursal"], "Fecha": p["fecha"].strftime("%d/%m/%Y"), "Tipo": p["tipo"]}
                                       for p in sorted(huerfanos, key=lambda x: (x["sucursal"], x["fecha"]))]),
                         use_container_width=True, hide_index=True)
    if es_cont:
        desc_v = cargar_sucursales_config().get("pendientes_descartados", {})
        if desc_v:
            with st.expander(f"♻️ Pendientes quitados ({len(desc_v)}) · restaurar"):
                restaurar = st.multiselect("Elige los que vuelven a contar como pendientes", sorted(desc_v, reverse=True),
                                           format_func=lambda c: f"{c.split('|')[0]} · {c.split('|')[1]} (quitó {desc_v[c].get('por', '')})",
                                           key=f"{key}_restaurar")
                if st.button("♻️ Restaurar", disabled=not restaurar, key=f"{key}_restaurar_btn"):
                    cfg_r = cargar_sucursales_config()
                    for c_r in restaurar:
                        cfg_r.get("pendientes_descartados", {}).pop(c_r, None)
                    guardar_sucursales_config(cfg_r)
                    guardar_evento_auditoria("PENDIENTES RESTAURADOS", ", ".join(restaurar[:20]))
                    st.rerun()


def _borrar_archivos(rutas):
    borradas = 0
    for ruta_b in rutas or []:
        try:
            p_b = Path(ruta_b)
            if not p_b.is_absolute():
                p_b = DATA_DIR / p_b
            if p_b.exists() and p_b.is_file():
                p_b.unlink()
                borradas += 1
        except (OSError, TypeError, ValueError):
            pass
    return borradas


def borrar_reporte_fisico(id_reporte):
    """Borra un reporte físico, los gastos que generó y sus fotos. Solo el Contador lo usa."""
    reportes_b = _leer_lista_json(FISICOS_FILE)
    reporte_b = next((r for r in reportes_b if r.get("ID") == id_reporte), None)
    if not reporte_b:
        return None
    _guardar_lista_json(FISICOS_FILE, [r for r in reportes_b if r.get("ID") != id_reporte])
    gastos_b = _leer_lista_json(GASTOS_FILE_RF)
    _guardar_lista_json(GASTOS_FILE_RF, [g for g in gastos_b if g.get("reporte_fisico_id") != id_reporte])
    compartidas = reporte_b.get("lote_id") and any(r.get("lote_id") == reporte_b.get("lote_id") for r in reportes_b
                                                   if r.get("ID") != id_reporte)
    if reporte_b.get("origen") != "Cierre del sistema" and not compartidas:  # las fotos del cierre siguen siendo del cierre
        _borrar_archivos(reporte_b.get("fotos"))
        _borrar_archivos(reporte_b.get("archivos"))
    return reporte_b


def calcular_boletos_block100(f_ini, f_fin):
    """Conteo inclusivo y cíclico de folios cuyo consecutivo se reinicia cada 100 (595→303 = 9 boletos)."""
    inicio, fin = int(f_ini), int(f_fin)
    if inicio < 0 or fin < 0 or (inicio == 0 and fin == 0):
        return 0
    return ((fin % 100 - inicio % 100) % 100) + 1


def evaluar_rentabilidad(margen):
    if margen >= 40.0:
        return "🟢 Alta"
    if margen >= 15.0:
        return "🟡 Moderada"
    if margen > 0.0:
        return "🟠 Baja"
    return "🔴 Pérdida"


def es_sucursal_directa(sucursal):
    """Sucursales que reportan ingreso bruto directo, sin control por folio."""
    cfg = tarifa_de(sucursal)
    return cfg.get("tipo") == "tiempo" or float(cfg.get("precio_fijo", 0) or 0) == 0 or sucursal == "E-BNI"


import functools as _functools


@_functools.lru_cache(maxsize=100000)
def _fecha_rapida_cache(texto, formato):
    try:
        return datetime.strptime(texto, formato).date()
    except (ValueError, TypeError):
        return None


def _fecha_rapida(valor, formato):
    """Igual que datetime.strptime(valor, formato).date() (lanza ValueError si no coincide), pero con memoria."""
    if not isinstance(valor, str):
        raise TypeError("fecha no es texto")
    r = _fecha_rapida_cache(valor, formato)
    if r is None:
        raise ValueError(f"{valor!r} no coincide con {formato}")
    return r


@_functools.lru_cache(maxsize=50000)
def _fecha_flexible_txt(texto):
    for formato in ("%d/%m/%Y %H:%M:%S", "%Y-%m-%d %H:%M:%S", "%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(texto, formato).date()
        except ValueError:
            continue
    return None


def fecha_flexible(valor):
    """Convierte textos de fecha a date. Con memoria: con miles de registros, las fechas se repiten mucho
    y así los reportes no recalculan lo mismo una y otra vez."""
    if isinstance(valor, datetime):
        return valor.date()
    if isinstance(valor, date):
        return valor
    return _fecha_flexible_txt(str(valor or ""))


def _prellenar_reporte_flujo(nonce, suc, lectura):
    """Pasa lo leído del formato «Reporte de flujo» a los campos del formulario."""
    ent = _entero_seguro
    f_ini, f_fin = ent(lectura.get("folio_inicial")), ent(lectura.get("folio_final"))
    canc, perd, pagados = ent(lectura.get("boletos_cancelados")), ent(lectura.get("boletos_perdidos")), ent(lectura.get("boletos_pagados"))
    st.session_state[f"rf_fini_{nonce}"] = f_ini
    st.session_state[f"rf_ffin_{nonce}"] = f_fin
    st.session_state[f"rf_canc_{nonce}"] = canc
    st.session_state[f"rf_perd_{nonce}"] = perd
    total_folios = calcular_boletos_block100(f_ini, f_fin) if (f_ini or f_fin) else ent(lectura.get("total_boletos"))
    # En la app: cobrados = total − sin cobro − cancelados. Para que cobrados = BOLETOS PAGADOS de la hoja:
    st.session_state[f"rf_sin_{nonce}"] = max(0, total_folios - pagados - canc) if pagados else 0
    costo = _flotante_seguro(lectura.get("costo_unitario"))
    if costo > 0:
        st.session_state[f"rf_costo_{nonce}_{suc}"] = costo
    st.session_state[f"rf_directo_{nonce}"] = _flotante_seguro(lectura.get("ingreso_bruto"))
    nomina = sum(_flotante_seguro(p.get("sueldo")) for p in lectura.get("personal", []) or [])
    otros = sum(_flotante_seguro(g.get("importe")) for g in lectura.get("gastos", []) or [])
    total_ng = _flotante_seguro(lectura.get("total_nomina_gastos")) or _flotante_seguro(lectura.get("gastos_generales"))
    if not (nomina or otros) and total_ng:
        otros = total_ng
    elif total_ng and abs(total_ng - nomina - otros) > 0.5 and total_ng > nomina:
        otros = total_ng - nomina   # lo que no está desglosado en sueldos va a «otros gastos»
    st.session_state[f"rf_nomina_{nonce}"] = round(nomina, 2)
    st.session_state[f"rf_otros_{nonce}"] = round(otros, 2)
    if _flotante_seguro(lectura.get("cantidad_entregar")) > 0:
        st.session_state[f"rf_efectivo_{nonce}_{suc}"] = _flotante_seguro(lectura.get("cantidad_entregar"))
    if str(lectura.get("elaboro") or "").strip():
        st.session_state[f"rf_elab_{nonce}_{suc}"] = str(lectura["elaboro"]).strip()


def _revision_reporte_flujo(lectura, costo_app, f_ini, f_fin):
    """Revisión de la hoja leída: que sus propias cuentas cuadren y que coincidan con lo que calcula la app."""
    avisos = []
    ent, flo = _entero_seguro, _flotante_seguro
    total_folios = calcular_boletos_block100(f_ini, f_fin) if (f_ini or f_fin) else 0
    if ent(lectura.get("total_boletos")) and total_folios and ent(lectura.get("total_boletos")) != total_folios:
        avisos.append(f"TOTAL DE BOLETOS dice {ent(lectura.get('total_boletos'))}, pero del folio {f_ini} al {f_fin} son {total_folios}.")
    pag, canc, perd, entr = (ent(lectura.get(k)) for k in ("boletos_pagados", "boletos_cancelados", "boletos_perdidos", "total_entregados"))
    if entr and pag and entr != pag:
        avisos.append(f"BOLETOS PAGADOS ({pag}) y TOTAL ENTREGADOS ({entr}) no son iguales: revisa cuál cobró la unidad.")
    costo_h = flo(lectura.get("costo_unitario"))
    if costo_h and costo_app and abs(costo_h - costo_app) > 0.01:
        avisos.append(f"COSTO UNITARIO de la hoja ${costo_h:,.2f} distinto a la tarifa de la app ${costo_app:,.2f}.")
    base = entr or pag
    if flo(lectura.get("ingreso_bruto")) and costo_h and base and abs(flo(lectura.get("ingreso_bruto")) - costo_h * base) > 0.5:
        avisos.append(f"INGRESO BRUTO dice ${flo(lectura.get('ingreso_bruto')):,.2f}, pero ${costo_h:,.2f} × {base} boletos = ${costo_h * base:,.2f}.")
    suma_ng = sum(flo(p.get("sueldo")) for p in lectura.get("personal", []) or []) + sum(flo(g.get("importe")) for g in lectura.get("gastos", []) or [])
    if flo(lectura.get("total_nomina_gastos")) and suma_ng and abs(flo(lectura.get("total_nomina_gastos")) - suma_ng) > 0.5:
        avisos.append(f"TOTAL DE NÓMINA Y GASTOS dice ${flo(lectura.get('total_nomina_gastos')):,.2f}, pero sueldos + gastos suman ${suma_ng:,.2f}.")
    bruto, gen, neto = flo(lectura.get("ingreso_bruto")), flo(lectura.get("gastos_generales")), flo(lectura.get("ingreso_neto"))
    if bruto and neto and abs(bruto - gen - neto) > 0.5:
        avisos.append(f"INGRESO NETO dice ${neto:,.2f}, pero ingreso bruto − gastos generales = ${bruto - gen:,.2f}.")
    entregar = flo(lectura.get("cantidad_entregar"))
    if entregar and neto and abs(entregar - neto) > 0.5:
        avisos.append(f"CANTIDAD A ENTREGAR (${entregar:,.2f}) no es igual al INGRESO NETO (${neto:,.2f}).")
    return avisos


def _lectura_automatica_rf(nonce, fotos, es_ingresos):
    """La hoja física se lee con IA en cuanto se toma o sube la foto (una sola vez por juego de fotos).
    El botón «Leer la hoja con IA» queda para volver a leer."""
    try:
        huella = hashlib.md5(b"".join(f.getvalue() for f in fotos) + (b"I" if es_ingresos else b"G")).hexdigest()
    except Exception:
        return False
    if st.session_state.get(f"rf_ia_auto_{nonce}") == huella:
        return False
    st.session_state[f"rf_ia_auto_{nonce}"] = huella
    return True


def _limpiar_formulario_rf():
    """Borra de la sesión todos los valores del formulario de reportes físicos y abre uno nuevo."""
    for k in [k for k in list(st.session_state.keys()) if str(k).startswith("rf_") and k not in ("rf_nonce", "rf_apartado",
              "rf_excel_bytes", "rf_excel_nombre", "rf_aviso_guardado", "rf_filtro_suc", "rf_ver_detalle")]:
        st.session_state.pop(k, None)
    st.session_state.rf_nonce = int(st.session_state.get("rf_nonce", 0)) + 1


def _ir_a_subir_fila_pendiente(clave_tabla, filas):
    """Al tocar un renglón de la tabla de pendientes: abre 'Subir reporte' con sucursal y fecha ya llenas."""
    fila = None
    try:
        seleccion = st.session_state[clave_tabla]["selection"]
        filas_sel = list(seleccion.get("rows") or [])
        celdas_sel = list(seleccion.get("cells") or [])
        if filas_sel:
            fila = filas_sel[0]
        elif celdas_sel:
            fila = celdas_sel[0][0]
    except Exception:
        fila = None
    if fila is not None and 0 <= int(fila) < len(filas):
        _abrir_subir_con(filas[int(fila)])


def _ir_a_subir_pendiente(opciones_pend):
    """Al elegir un reporte pendiente: abre 'Subir reporte' con la sucursal y la fecha ya llenas (callback del selector)."""
    elegido = st.session_state.get("pend_ir_subir")
    datos = opciones_pend.get(elegido) if elegido else None
    if datos:
        _abrir_subir_con(datos)
        st.session_state["pend_ir_subir"] = None


def _abrir_subir_con(datos):
    if datos.get("sucursal") not in SUCURSALES:
        return
    _limpiar_formulario_rf()
    n = st.session_state.rf_nonce
    st.session_state[f"rf_tipo_{n}"] = "📥 Reporte de ingresos"
    st.session_state[f"rf_suc_{n}"] = datos["sucursal"]
    st.session_state[f"rf_fecha_{n}"] = datos["fecha"]
    st.session_state["rf_apartado"] = "subir"
    st.session_state["rf_aviso_pendiente"] = (f"📌 Llenado desde Pendientes: **{datos['sucursal']}** · "
                                              f"{NOMBRES_DIA[datos['fecha'].weekday()]} {datos['fecha']:%d/%m/%Y}"
                                              + (f" · {datos['tipo']}" if datos.get("tipo") else "")
                                              + ". Solo toma la foto de la hoja y revisa los datos.")


def guardar_fotos_reporte(archivos, id_reporte):
    rutas = []
    for i, archivo in enumerate(archivos, start=1):
        with _semaforo_fotos():  # mismo límite de memoria que las fotos de vehículos
            imagen = archivo.copy() if isinstance(archivo, Image.Image) else Image.open(archivo)
            if not isinstance(archivo, Image.Image):
                try:
                    imagen.draft("RGB", (1600, 1600))
                except Exception:
                    pass
            imagen = ImageOps.exif_transpose(imagen).convert("RGB")
            imagen.thumbnail((1600, 1600))
            ruta = FOTOS_REPORTES_DIR / f"{id_reporte}_{i}.jpg"
            imagen.save(ruta, format="JPEG", quality=80, optimize=True)
            imagen.close()
            rutas.append(str(ruta))
    return rutas


def _fila_flujo(suc, dia, bruto=0.0, cobrados=0, costo=0.0, f_ini=0, f_fin=0, total=None, elaboro="", usuario="", rid=""):
    return {
        "ID": rid, "Fecha": dia.strftime("%d/%m/%Y"), "Sitio / Unidad": suc,
        "Costo Boleto": float(costo), "Folio Inicial": int(f_ini), "Folio Final": int(f_fin),
        "Total Boletos": int(cobrados if total is None else total), "Sin Cobro": 0, "Cancelados": 0, "Perdidos": 0,
        "Boletos Cobrados": int(cobrados), "Ingreso Bruto": float(bruto),
        "Gastos Especiales": 0.0, "Gastos Generales / Nómina": 0.0, "Total Gastos": 0.0, "Ingreso Neto": float(bruto),
        "Elaboró": elaboro, "Usuario": usuario, "Nivel Auditoría": "Conforme", "Tipo": "Operación Regular",
    }


def registros_flujo_periodo(desde, hasta, sucursales):
    """Une reportes físicos de ingresos, cobros digitales y gastos en el esquema del Excel oficial.
    Si una sucursal/fecha tiene reporte físico de ingresos, ese manda; si no, se usan los cobros digitales."""
    permitidas = set(sucursales)
    filas = {}
    for r in _leer_lista_json(FISICOS_FILE):
        if r.get("tipo_reporte") != "ingresos":
            continue
        dia = fecha_flexible(r.get("Fecha"))
        suc = r.get("Sitio / Unidad")
        if dia and suc in permitidas and desde <= dia <= hasta:
            fila = _fila_flujo(suc, dia, r.get("Ingreso Bruto", 0), r.get("Boletos Cobrados", 0), r.get("Costo Boleto", 0),
                               r.get("Folio Inicial", 0), r.get("Folio Final", 0), r.get("Total Boletos"),
                               r.get("Elaboró", ""), r.get("Usuario", ""), r.get("ID", ""))
            for k in ("Sin Cobro", "Cancelados", "Perdidos"):
                fila[k] = int(r.get(k, 0) or 0)
            previa = filas.get((suc, dia))
            if previa:  # salón con un reporte por evento: se suman en un solo renglón del día
                for k in ("Ingreso Bruto", "Ingreso Neto", "Boletos Cobrados", "Total Boletos", "Sin Cobro", "Cancelados", "Perdidos"):
                    previa[k] = (previa.get(k) or 0) + (fila.get(k) or 0)
                ini_v = [x for x in (previa.get("Folio Inicial"), fila.get("Folio Inicial")) if x]
                previa["Folio Inicial"] = min(ini_v) if ini_v else 0
                previa["Folio Final"] = max(previa.get("Folio Final") or 0, fila.get("Folio Final") or 0)
                previa["ID"] = f"{previa.get('ID', '')}+{fila.get('ID', '')}"
                previa["Tipo"] = "Eventos (suma de reportes)"
            else:
                filas[(suc, dia)] = fila
    digitales = {}
    for reg in st.session_state.get("vehiculos", []):
        for pago in reg.get("pagos", []) or []:
            if pago.get("estado") != "Pagado":
                continue
            dia = fecha_op_pago(pago)
            suc = pago.get("sucursal") or reg.get("sucursal")
            if dia and suc in permitidas and desde <= dia <= hasta:
                acum = digitales.setdefault((suc, dia), [0.0, 0])
                acum[0] += dinero(pago.get("importe"))
                acum[1] += 1
    for clave, (importe, n) in digitales.items():
        if clave not in filas:
            suc, dia = clave
            filas[clave] = _fila_flujo(suc, dia, importe, n, (importe / n) if n else 0, usuario="Cobro digital")
    for g in _leer_lista_json(GASTOS_FILE_RF):
        dia = fecha_flexible(g.get("fecha"))
        suc = g.get("sucursal")
        if not (dia and suc in permitidas and desde <= dia <= hasta):
            continue
        fila = filas.setdefault((suc, dia), _fila_flujo(suc, dia, usuario="Gastos"))
        monto = dinero(g.get("importe"))
        if g.get("categoria") == "Nómina":
            fila["Gastos Generales / Nómina"] += monto
        else:
            fila["Gastos Especiales"] += monto
    resultado = []
    for fila in filas.values():
        fila["Total Gastos"] = fila["Gastos Generales / Nómina"] + fila["Gastos Especiales"]
        fila["Ingreso Neto"] = fila["Ingreso Bruto"] - fila["Total Gastos"]
        resultado.append(fila)
    return sorted(resultado, key=lambda f: (fecha_flexible(f["Fecha"]), f["Sitio / Unidad"]))



# ---------------------------------------------------------------------
# REPORTES POR SERVICIO (SUCURSAL) Y GLOBAL: semana / quincena / mes
# ---------------------------------------------------------------------
NOMBRES_DIA = ["LUNES", "MARTES", "MIÉRCOLES", "JUEVES", "VIERNES", "SÁBADO", "DOMINGO"]
COLUMNAS_NO_MONEDA = {"Fecha", "Día", "Sucursal", "Categoría", "Concepto", "Supervisor", "Origen", "Registró", "Gastos", "Días con venta", "Días del periodo", "Margen %", "Sin información",
                      "N° de día", "Día actual", "Día anterior", "Fecha actual", "Fecha anterior"}


def rango_periodo(tipo, referencia, desde_pers=None, hasta_pers=None):
    """Devuelve (desde, hasta) para Semana (lun-dom), Quincena (1-15 / 16-fin), Mes o Personalizado."""
    if tipo == "Semana":
        lunes = referencia - timedelta(days=referencia.weekday())
        return lunes, lunes + timedelta(days=6)
    primer_dia_mes = referencia.replace(day=1)
    primer_dia_sig = (primer_dia_mes + timedelta(days=32)).replace(day=1)
    ultimo_dia_mes = primer_dia_sig - timedelta(days=1)
    if tipo == "Quincena":
        if referencia.day <= 15:
            return primer_dia_mes, referencia.replace(day=15)
        return referencia.replace(day=16), ultimo_dia_mes
    if tipo == "Mes":
        return primer_dia_mes, ultimo_dia_mes
    return desde_pers, hasta_pers


def construir_reporte(desde, hasta, sucursales):
    """Estado de resultados por sucursal: vendió, gastos, utilidad; venta diaria; promedio por día de la semana."""
    sucursales = list(sucursales)
    registros = registros_flujo_periodo(desde, hasta, sucursales)
    dias = [desde + timedelta(days=i) for i in range((hasta - desde).days + 1)]
    ventas, gastos = {}, {}
    for r in registros:
        clave = (r["Sitio / Unidad"], fecha_flexible(r["Fecha"]))
        ventas[clave] = ventas.get(clave, 0.0) + _flotante_seguro(r.get("Ingreso Bruto"))
        gastos[clave] = gastos.get(clave, 0.0) + _flotante_seguro(r.get("Total Gastos"))

    filas = []
    for suc in sucursales:
        v = sum(ventas.get((suc, d), 0.0) for d in dias)
        g = sum(gastos.get((suc, d), 0.0) for d in dias)
        dias_venta = sum(1 for d in dias if ventas.get((suc, d), 0.0) > 0)
        filas.append({
            "Sucursal": suc, "Ventas": v, "Gastos": g, "Utilidad": v - g,
            "Margen %": round((v - g) / v * 100, 1) if v else 0.0,
            "Días con venta": dias_venta,
            "Promedio por día": (v / dias_venta) if dias_venta else 0.0,
        })
    resumen = pd.DataFrame(filas, columns=["Sucursal", "Ventas", "Gastos", "Utilidad", "Margen %", "Días con venta", "Promedio por día"])
    v_tot, g_tot = float(resumen["Ventas"].sum()), float(resumen["Gastos"].sum())
    dias_con_venta_global = sum(1 for d in dias if any(ventas.get((suc, d), 0.0) > 0 for suc in sucursales))
    fila_total = {
        "Sucursal": "TOTAL", "Ventas": v_tot, "Gastos": g_tot, "Utilidad": v_tot - g_tot,
        "Margen %": round((v_tot - g_tot) / v_tot * 100, 1) if v_tot else 0.0,
        "Días con venta": dias_con_venta_global,
        "Promedio por día": (v_tot / dias_con_venta_global) if dias_con_venta_global else 0.0,
    }
    resumen_total = pd.concat([resumen, pd.DataFrame([fila_total])], ignore_index=True)

    sucursales_con_venta = [suc for suc in sucursales if any(ventas.get((suc, d), 0.0) > 0 for d in dias)] or sucursales
    filas_dia, filas_util = [], []
    acumulado = 0.0
    for d in dias:
        fila = {"Fecha": d.strftime("%d/%m/%Y"), "Día": NOMBRES_DIA[d.weekday()]}
        for suc in sucursales_con_venta:
            fila[suc] = ventas.get((suc, d), 0.0)
        v_dia = sum(ventas.get((suc, d), 0.0) for suc in sucursales)
        g_dia = sum(gastos.get((suc, d), 0.0) for suc in sucursales)
        fila["TOTAL"] = v_dia
        filas_dia.append(fila)
        acumulado += v_dia - g_dia
        filas_util.append({"Fecha": d.strftime("%d/%m/%Y"), "Día": NOMBRES_DIA[d.weekday()], "Ventas": v_dia,
                           "Gastos": g_dia, "Utilidad": v_dia - g_dia, "Utilidad acumulada": acumulado})
    diario_sucursal = pd.DataFrame(filas_dia)
    utilidad_diaria = pd.DataFrame(filas_util)

    filas_sem = []
    for idx, nombre in enumerate(NOMBRES_DIA):
        fechas_idx = [d for d in dias if d.weekday() == idx]
        total_dia = sum(fila["Ventas"] for fila, d in zip(filas_util, dias) if d.weekday() == idx)
        filas_sem.append({"Día": nombre, "Días del periodo": len(fechas_idx), "Ventas": total_dia,
                          "Promedio por día": (total_dia / len(fechas_idx)) if fechas_idx else 0.0})
    por_dia_semana = pd.DataFrame(filas_sem)

    acum_cat = {}
    for g in _leer_lista_json(GASTOS_FILE_RF):
        dia = fecha_flexible(g.get("fecha"))
        if dia and desde <= dia <= hasta and g.get("sucursal") in sucursales:
            clave = (g.get("sucursal"), g.get("categoria") or "Otros")
            acum_cat[clave] = acum_cat.get(clave, 0.0) + dinero(g.get("importe"))
    gastos_categoria = pd.DataFrame(
        [{"Sucursal": k[0], "Categoría": k[1], "Importe": v} for k, v in sorted(acum_cat.items())],
        columns=["Sucursal", "Categoría", "Importe"],
    )
    return {"resumen": resumen, "resumen_total": resumen_total, "diario_sucursal": diario_sucursal,
            "utilidad_diaria": utilidad_diaria, "por_dia_semana": por_dia_semana, "gastos_categoria": gastos_categoria,
            "ventas_total": v_tot, "gastos_total": g_tot, "sucursales_con_venta": sucursales_con_venta}


def rango_anterior(tipo, desde, hasta):
    """Periodo inmediato anterior: semana-7 días, quincena anterior, mes anterior o igual duración."""
    if tipo == "Semana":
        return desde - timedelta(days=7), hasta - timedelta(days=7)
    if tipo == "Quincena":
        if desde.day == 1:
            fin_prev = desde - timedelta(days=1)
            return fin_prev.replace(day=16), fin_prev
        return desde.replace(day=1), desde.replace(day=15)
    if tipo == "Mes":
        fin_prev = desde - timedelta(days=1)
        return fin_prev.replace(day=1), fin_prev
    dias = (hasta - desde).days + 1
    fin_prev = desde - timedelta(days=1)
    return fin_prev - timedelta(days=dias - 1), fin_prev


def _variacion_pct(actual, anterior):
    return round((actual - anterior) / anterior * 100, 1) if anterior else None


def construir_comparativo(rep_act, rep_ant):
    """Compara dos reportes (actual vs anterior): por sucursal y día a día."""
    a = rep_act["resumen_total"].set_index("Sucursal")
    b = rep_ant["resumen_total"].set_index("Sucursal")
    # Sucursales duplicadas harían que .loc devuelva una serie y float() falle;
    # nos quedamos con la primera aparición de cada una.
    a = a[~a.index.duplicated(keep="first")]
    b = b[~b.index.duplicated(keep="first")]
    filas = []
    for suc in a.index:
        va, ga, ua = float(a.loc[suc, "Ventas"]), float(a.loc[suc, "Gastos"]), float(a.loc[suc, "Utilidad"])
        vb = float(b.loc[suc, "Ventas"]) if suc in b.index else 0.0
        gb = float(b.loc[suc, "Gastos"]) if suc in b.index else 0.0
        ub = float(b.loc[suc, "Utilidad"]) if suc in b.index else 0.0
        filas.append({
            "Sucursal": suc, "Ventas actual": va, "Ventas anterior": vb, "Var. ventas $": va - vb,
            "Var. ventas %": _variacion_pct(va, vb), "Gastos actual": ga, "Gastos anterior": gb,
            "Utilidad actual": ua, "Utilidad anterior": ub, "Var. utilidad $": ua - ub,
            "Var. utilidad %": _variacion_pct(ua, ub),
        })
    resumen = pd.DataFrame(filas)
    da, db = rep_act["utilidad_diaria"], rep_ant["utilidad_diaria"]
    filas_d = []
    for i in range(max(len(da), len(db))):
        fa = da.iloc[i] if i < len(da) else None
        fb = db.iloc[i] if i < len(db) else None
        va = float(fa["Ventas"]) if fa is not None else 0.0
        vb = float(fb["Ventas"]) if fb is not None else 0.0
        filas_d.append({
            "N° de día": i + 1,
            "Día actual": fa["Día"] if fa is not None else "", "Fecha actual": fa["Fecha"] if fa is not None else "",
            "Ventas actual": va,
            "Día anterior": fb["Día"] if fb is not None else "", "Fecha anterior": fb["Fecha"] if fb is not None else "",
            "Ventas anterior": vb, "Variación $": va - vb,
        })
    return {"resumen": resumen, "diario": pd.DataFrame(filas_d)}


def generar_excel_reporte(rep, titulo, periodo_txt, comparativo=None):
    """Excel con Resumen, Venta diaria, Utilidad diaria, Por día de la semana y Gastos por categoría."""
    hojas = [("Resumen", rep["resumen_total"])]
    if len(rep["sucursales_con_venta"]) > 1:
        hojas.append(("Venta diaria por sucursal", rep["diario_sucursal"]))
    hojas += [("Utilidad diaria", rep["utilidad_diaria"]), ("Por día de la semana", rep["por_dia_semana"]),
              ("Gastos por categoría", rep["gastos_categoria"])]
    if comparativo:
        hojas += [("Comparativo", comparativo["resumen"]), ("Comparativo diario", comparativo["diario"])]
    salida = io.BytesIO()
    verde = PatternFill(start_color="0B3B24", end_color="0B3B24", fill_type="solid")
    with pd.ExcelWriter(salida, engine="openpyxl") as writer:
        for nombre, df in hojas:
            if df.empty:
                df = pd.DataFrame({"Sin información": ["No hay datos en el periodo"]})
            df.to_excel(writer, sheet_name=nombre, index=False, startrow=3)
            ws = writer.sheets[nombre]
            ws["A1"] = titulo
            ws["A1"].font = Font(size=14, bold=True, color="0B3B24")
            ws["A2"] = periodo_txt
            ws["A2"].font = Font(size=10, italic=True)
            for celda in ws[4]:
                celda.fill = verde
                celda.font = Font(bold=True, color="FFFFFF")
                celda.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            for i, col in enumerate(df.columns, start=1):
                letra = get_column_letter(i)
                ancho = max([len(str(col))] + [len(str(v)) for v in df[col].head(300)]) + 3
                ws.column_dimensions[letra].width = min(max(ancho, 12), 40)
                for celda in list(ws[letra])[4:]:
                    if isinstance(celda.value, (int, float)) and str(col).endswith("%"):
                        celda.number_format = '0.0"%"'
                    elif isinstance(celda.value, (int, float)) and col not in COLUMNAS_NO_MONEDA:
                        celda.number_format = '"$"#,##0.00'
            for fila in ws.iter_rows(min_row=5):
                if str(fila[0].value) == "TOTAL":
                    for celda in fila:
                        celda.font = Font(bold=True)
            ws.freeze_panes = "A5"
    return salida.getvalue()


def formato_columnas_df(df):
    config = {}
    for col in df.columns:
        if str(col).endswith("%"):
            config[col] = st.column_config.NumberColumn(col, format="%.1f%%")
        elif col not in COLUMNAS_NO_MONEDA:
            config[col] = st.column_config.NumberColumn(col, format="$%.2f")
    return config


