        if ia_disponible():
            st.checkbox("🤖 Llenar placas, marca y color solos con las fotos de **frente** y **trasera**", value=True,
                        key=f"ing_auto_ia_{_ing_n}", help="Al tomar esas fotos (paso 3), la IA llena los campos que estén vacíos.")
            aviso_auto = st.session_state.get(f"ing_ia_msg_{_ing_n}")
