# Sin fragmento: las cámaras y la subida de fotos fallan dentro de fragmentos de Streamlit
@_registrar_fallas
def _num_folio_reg(r):
    try:
        return int(r.get("folio_numero") or str(r.get("id", "")).rsplit("-", 1)[-1])
    except (TypeError, ValueError):
        return None


def datos_avance_sucursal(registros, sucursal, fecha_op):
    """Cómo va la sucursal en su jornada: folios, custodia, entregados, cobros por forma de pago, gastos y utilidad."""
    de_suc = [r for r in registros if r.get("sucursal") == sucursal]
    ingresos = [r for r in de_suc if fecha_op_registro(r) == fecha_op]
    nums = sorted(n for n in (_num_folio_reg(r) for r in ingresos) if n is not None)
    custodia = [r for r in de_suc if r.get("estado") == "En Resguardo"]
    entregados = [r for r in de_suc if r.get("estado") == "Entregado" and fecha_op_salida(r) == fecha_op]
    por_metodo, sellados, total = {}, 0, 0.0
    for r in de_suc:
        for pg in r.get("pagos") or []:
            if pg.get("estado") == "Pagado" and fecha_op_pago(pg) == fecha_op:
                metodo = pg.get("metodo") or "Efectivo"
                d = por_metodo.setdefault(metodo, {"n": 0, "importe": 0.0})
                d["n"] += 1
                d["importe"] += dinero(pg.get("importe"))
                total += dinero(pg.get("importe"))
                sellados += 1 if (pg.get("sellado") or metodo == METODO_SELLADO) else 0
    gastos = 0.0
    try:
        for g in _leer_lista_json(DATA_DIR / "gastos_operativos.json"):
            if g.get("sucursal") == sucursal and g.get("origen") != "Cierre diario" and fecha_flexible(g.get("fecha")) == fecha_op:
                gastos += dinero(g.get("importe"))
    except Exception:
        pass
    sin_conexion = sum(1 for r in ingresos if r.get("origen") == "Sin conexión")
    folios_esperados = (nums[-1] - nums[0] + 1) if nums else 0
    return {
        "sucursal": sucursal, "fecha_op": fecha_op, "momento": ahora_mx(),
        "folio_inicial": nums[0] if nums else None, "folio_actual": nums[-1] if nums else None,
        "ingresos": len(ingresos), "custodia": len(custodia), "entregados": len(entregados),
        "por_metodo": por_metodo, "total": total, "sellados": sellados,
        "efectivo": por_metodo.get("Efectivo", {}).get("importe", 0.0),
        "gastos": gastos, "utilidad": total - gastos, "sin_conexion": sin_conexion,
        "folios_saltados": max(0, folios_esperados - len(nums)),
        "codigo": codigo_sucursal(sucursal),
    }


def texto_reporte_avance(d, quien=""):
    """Reporte de avance para la mini impresora térmica (mismo ancho que el boleto)."""
    ancho = cargar_ticket_cfg()["ancho"]
    eq, gu = "=" * ancho, "-" * ancho
    fol = lambda n: f"CP-{d['codigo']}-{n:06d}" if n is not None else "—"
    def renglon(etq, valor):
        etq, valor = str(etq), str(valor)
        espacio = ancho - len(etq) - len(valor)
        return etq + " " * espacio + valor if espacio >= 1 else f"{etq}\n{valor.rjust(ancho)}"
    lineas = [eq, "CLUB PARK VALET".center(ancho), "REPORTE DE AVANCE".center(ancho), eq,
              _envolver_ticket(f"SUC: {d['sucursal']}"), f"JORNADA: {d['fecha_op']:%d/%m/%Y}",
              f"CORTE: {d['momento']:%d/%m/%y %H:%M}", gu,
              "FOLIO INICIAL:", fol(d["folio_inicial"]), "FOLIO ACTUAL:", fol(d["folio_actual"]), gu,
              renglon("INGRESOS", d["ingresos"]), renglon("EN CUSTODIA", d["custodia"]),
              renglon("ENTREGADOS", d["entregados"])]
    if d["sellados"]:
        lineas.append(renglon("SELLADOS", d["sellados"]))
    if d["folios_saltados"]:
        lineas.append(renglon("FOLIOS SALTADOS", d["folios_saltados"]))
    lineas.append(gu)
    lineas.append("COBROS POR FORMA DE PAGO"[:cargar_ticket_cfg()["ancho"]])
    for metodo, v in sorted(d["por_metodo"].items()):
        lineas.append(renglon(f"{metodo[:10]} ({v['n']})", f"${v['importe']:,.2f}"))
    if not d["por_metodo"]:
        lineas.append("SIN COBROS AUN")
    lineas += [gu, renglon("TOTAL COBRADO", f"${d['total']:,.2f}"), renglon("EFECTIVO", f"${d['efectivo']:,.2f}")]
    if d["gastos"]:
        lineas += [renglon("GASTOS", f"${d['gastos']:,.2f}"), renglon("UTILIDAD", f"${d['utilidad']:,.2f}")]
    lineas += [gu, _envolver_ticket(f"SOLICITO: {quien}") if quien else "", "FIRMA: ______________", eq]
    return "\n".join(l for l in lineas if l != "") + "\n"


def vista_reporte_avance(sucursal, fecha_op, clave="avance"):
    """Tarjeta en pantalla + impresión térmica del reporte de avance de la sucursal."""
    d = datos_avance_sucursal(cargar_bd_rapido(), sucursal, fecha_op)
    st.markdown(
        f'<div style="background:#0B3B24;color:#FFFFFF;border-radius:14px;padding:14px 16px;margin:14px 0 8px;'
        f'box-shadow:0 2px 8px rgba(11,59,36,.3);display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap">'
        f'<span style="font-weight:800;font-size:20px;letter-spacing:.5px;color:#FFFFFF">🧾 REPORTE DE AVANCE · {html.escape(sucursal)}</span>'
        f'<span style="background:#2E9E5B;color:#FFFFFF;border-radius:999px;padding:4px 14px;font-weight:700;font-size:14px;white-space:nowrap">'
        f'Cómo van ahora · {d["momento"]:%H:%M}</span></div>', unsafe_allow_html=True)
    try:
        _caja_avance = st.container(border=True)
    except TypeError:
        _caja_avance = st.container()
    with _caja_avance:
        st.caption(f"Jornada del {fecha_op:%d/%m/%Y} · actualizado {d['momento']:%H:%M}. Útil cuando el supervisor pregunta cómo van; "
                   "no cierra la jornada.")
        fol = lambda n: f"CP-{d['codigo']}-{n:06d}" if n is not None else "—"
        c1, c2 = st.columns(2)
        c1.metric("Folio inicial", fol(d["folio_inicial"]))
        c2.metric("Folio actual", fol(d["folio_actual"]))
        c3, c4, c5 = st.columns(3)
        c3.metric("Ingresos", d["ingresos"])
        c4.metric("En custodia", d["custodia"])
        c5.metric("Entregados", d["entregados"])
        c6, c7, c8 = st.columns(3)
        c6.metric("Total cobrado", f"${d['total']:,.2f}")
        c7.metric("Efectivo", f"${d['efectivo']:,.2f}")
        c8.metric("Utilidad" if d["gastos"] else "Gastos", f"${d['utilidad']:,.2f}" if d["gastos"] else "$0.00")
        if d["por_metodo"]:
            st.dataframe(pd.DataFrame([{"Forma de pago": m, "Cobros": v["n"], "Importe": f"${v['importe']:,.2f}"}
                                       for m, v in sorted(d["por_metodo"].items())]), use_container_width=True, hide_index=True)
        if d["folios_saltados"]:
            st.warning(f"Hay {d['folios_saltados']} folio(s) sin registro entre el inicial y el actual (pueden ser folios reservados del modo sin conexión).")
        if d["sin_conexion"]:
            st.caption(f"📴 Incluye {d['sin_conexion']} ingreso(s) registrados sin señal.")
        texto = texto_reporte_avance(d, st.session_state.get("usuario_autenticado", ""))
        st.code(texto, language="text")
        imprimir_bluetooth(texto, f"{clave}_{d['codigo']}", contexto={"folio": "AVANCE", "tipo_documento": "REPORTE DE AVANCE"})
        st.download_button("⬇️ Descargar reporte (texto)", texto.encode("utf-8"),
                           file_name=f"avance_{d['codigo']}_{d['momento']:%Y%m%d_%H%M}.txt", mime="text/plain",
                           key=f"dl_{clave}_{d['codigo']}")


ACCION_SE_QUEDA = "🅿️ Se queda · pasa al siguiente reporte"
ACCIONES_CIERRE = [ACCION_SE_QUEDA, "🔒 Cobrar y cerrar (ya no está)"]

MOTIVOS_CIERRE_AUTO = [
    "Salida no registrada en la app (el auto ya se entregó)",
    "Cliente se retiró sin pasar a caja",
    "Boleto perdido",
    "Vehículo entregado sin escanear el boleto",
    "Otro (escribir detalle)",
]


def vista_cierre_automatico(sucursal):
    """Al cierre del día: cobra y da salida en bloque a los boletos que siguen abiertos, con el motivo de cada uno."""
    import hashlib
    abiertos = [r for r in cargar_bd_rapido() if r.get("sucursal") == sucursal and r.get("estado") == "En Resguardo"]
    st.markdown(
        f'<div style="background:#0B3B24;color:#FFFFFF;border-radius:14px;padding:14px 16px;margin:18px 0 8px;'
        f'box-shadow:0 2px 8px rgba(11,59,36,.3);display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap">'
        f'<span style="font-weight:800;font-size:20px;letter-spacing:.5px;color:#FFFFFF">🔒 CERRAR BOLETOS ABIERTOS · {html.escape(sucursal)}</span>'
        f'<span style="background:{"#C62828" if abiertos else "#2E9E5B"};color:#FFFFFF;border-radius:999px;padding:4px 14px;font-weight:700;'
        f'font-size:14px;white-space:nowrap">{len(abiertos)} abierto(s)</span></div>', unsafe_allow_html=True)
    if not abiertos:
        st.success("✅ No hay boletos abiertos: todos los vehículos de esta sucursal ya tienen salida. Puedes hacer el cierre.")
        return
    st.caption("Estos vehículos siguen «En Resguardo». **No hace falta esperarlos para cerrar el reporte**: los que siguen "
               "en el estacionamiento (clientes de más de 24 horas) se marcan como «Se queda» y **pasan al reporte del día siguiente**; "
               "se cobran el día que salgan y ese cobro cuenta en el reporte de ese día. Solo los que ya no están (salida no "
               "registrada, boleto perdido…) se marcan como «Cobrar y cerrar». Todo queda en auditoría.")
    cfg = tarifa_de(sucursal)
    ahora = ahora_mx()
    metodos = ["Efectivo", "Tarjeta"]
    filas = []
    for r in sorted(abiertos, key=lambda x: str(x.get("fecha_entrada_iso") or "")):
        minutos = minutos_estancia(r, ahora)
        modalidad = r.get("modalidad_tarifa") or modalidades_disponibles(cfg)[0]
        precio = float(r.get("tarifa") or 0)
        importe = calcular_cobro(cfg, modalidad, minutos, precio if modalidad == "fija" else None)
        filas.append({"Folio": r.get("id"), "Placas": r.get("placas"), "Vehículo": f"{r.get('marca', '')} {r.get('color', '')}".strip(),
                      "Entrada": r.get("fecha_entrada") or r.get("fecha"), "Estancia": texto_duracion(minutos),
                      "Importe": round(float(importe), 2), "Acción": ACCION_SE_QUEDA, "Forma de pago": "Efectivo",
                      "Motivo": MOTIVOS_CIERRE_AUTO[0], "Detalle": ""})
    accion_todos = st.selectbox("¿Qué pasa con estos vehículos? (puedes cambiarlo en cada renglón)", ACCIONES_CIERRE,
                                key=f"ca_accion_{sucursal}")
    c1, c2 = st.columns(2)
    motivo_todos = c1.selectbox("Motivo para los que se cobran y cierran", MOTIVOS_CIERRE_AUTO, key=f"ca_motivo_{sucursal}")
    metodo_todos = c2.selectbox("Forma de pago para todos", metodos, key=f"ca_metodo_{sucursal}")
    for f in filas:
        f["Motivo"], f["Forma de pago"], f["Acción"] = motivo_todos, metodo_todos, accion_todos
    firma = hashlib.md5(("|".join(f["Folio"] for f in filas) + motivo_todos + metodo_todos + accion_todos).encode("utf-8")).hexdigest()[:8]
    editado = st.data_editor(
        pd.DataFrame(filas), use_container_width=True, hide_index=True, key=f"ca_tabla_{sucursal}_{firma}",
        column_config={
            "Importe": st.column_config.NumberColumn("Importe $", format="$%.2f"),
            "Acción": st.column_config.SelectboxColumn("¿Qué pasa?", options=ACCIONES_CIERRE, required=True),
            "Forma de pago": st.column_config.SelectboxColumn("Forma de pago", options=metodos, required=True),
            "Motivo": st.column_config.SelectboxColumn("Motivo", options=MOTIVOS_CIERRE_AUTO, required=True),
            "Detalle": st.column_config.TextColumn("Detalle (obligatorio si es «Otro»)"),
        },
        disabled=["Folio", "Placas", "Vehículo", "Entrada", "Estancia", "Importe"],
    )
    todos_ca = editado.to_dict("records")
    sel = [f for f in todos_ca if f.get("Acción") != ACCION_SE_QUEDA]
    se_quedan = [f for f in todos_ca if f.get("Acción") == ACCION_SE_QUEDA]
    total = sum(float(f.get("Importe") or 0) for f in sel)
    if se_quedan:
        st.success(f"🅿️ **{len(se_quedan)} se quedan** en el estacionamiento y pasan al reporte del día siguiente "
                   f"(a la hora actual llevarían ${sum(float(f.get("Importe") or 0) for f in se_quedan):,.2f}; se cobra lo que corresponda cuando salgan). "
                   "Ya puedes guardar el cierre abajo.")
    if not sel:
        return
    st.info(f"Se cobrarán y cerrarán **{len(sel)}** boleto(s) · total **${total:,.2f}** (tarifa de la sucursal con la hora actual).")
    confirmo = st.checkbox("Confirmo que estos vehículos ya no están en la sucursal y que el importe y el motivo son correctos.",
                           key=f"ca_confirmo_{sucursal}_{firma}")
    if st.button(f"🔒 Cobrar y cerrar ({len(sel)} boleto(s))", type="primary", use_container_width=True,
                 disabled=not (sel and confirmo), key=f"ca_boton_{sucursal}_{firma}"):
        faltan = [f["Folio"] for f in sel if not f.get("Motivo") or (str(f.get("Motivo")).startswith("Otro") and not str(f.get("Detalle") or "").strip())]
        if faltan:
            st.error("Escribe el detalle del motivo «Otro» en: " + ", ".join(faltan))
            return
        momento = ahora_mx()
        bd = {r.get("id"): r for r in cargar_bd()}
        upserts, pagos, ya_cerrados = [], [], []
        usuario = st.session_state.get("usuario_autenticado")
        for f in sel:
            reg = bd.get(f["Folio"])
            if not reg or reg.get("estado") != "En Resguardo":
                ya_cerrados.append(f["Folio"])
                continue
            metodo = f.get("Forma de pago") if f.get("Forma de pago") in metodos else "Efectivo"
            minutos = minutos_estancia(reg, momento)
            modalidad = reg.get("modalidad_tarifa") or modalidades_disponibles(cfg)[0]
            calculado = calcular_cobro(cfg, modalidad, minutos, float(reg.get("tarifa") or 0) if modalidad == "fija" else None)
            importe = round(float(calculado), 2)  # siempre la tarifa de la sucursal: sin descuentos ni cortesías
            motivo = str(f.get("Motivo") or "")
            detalle = str(f.get("Detalle") or "").strip()
            pago = {
                "id_pago": str(uuid.uuid4()), "fecha_hora": momento.strftime("%Y-%m-%d %H:%M:%S"),
                "fecha_hora_iso": momento.isoformat(timespec="seconds"), "sucursal": sucursal, "folio": reg.get("id"),
                "importe": importe, "metodo": metodo, "estado": "Pagado", "referencia": "CIERRE AUTOMÁTICO",
                "observaciones": f"{motivo}" + (f" · {detalle}" if detalle else ""), "usuario": usuario,
                "confirmacion_manual": metodo == "Tarjeta", "modalidad_tarifa": modalidad, "tipo_cliente": reg.get("tipo_cliente", ""),
                "sellado": False, "fecha_operativa": fecha_operativa_actual(sucursal).isoformat(),
                "minutos_estancia": minutos, "importe_calculado": calculado, "ajuste_manual": False, "motivo_ajuste": "",
                "cierre_automatico": True, "motivo_cierre": motivo, "detalle_cierre": detalle,
            }
            reg.setdefault("pagos", []).append(pago)
            reg.update({
                "pago_estado": "Pagado", "metodo_pago": metodo, "importe_cobrado": importe,
                "salida_fecha": pago["fecha_hora"], "fecha_salida": momento.strftime("%d/%m/%Y"),
                "hora_salida": momento.strftime("%H:%M:%S"), "salida_fecha_hora_iso": pago["fecha_hora_iso"],
                "salida_fecha_operativa": pago["fecha_operativa"], "entregado_por": usuario, "estado": "Entregado",
                "cierre_automatico": True, "motivo_cierre": motivo, "detalle_cierre": detalle,
            })
            reg["ticket_texto"] = crear_ticket(reg)
            upserts.append(reg)
            pagos.append(pago)
        if upserts and guardar_cambios_bd(upserts=upserts):
            for pago, reg in zip(pagos, upserts):
                try:
                    guardar_pago_respaldo(pago, reg)
                except Exception as exc_p:
                    registrar_falla("cierre_automatico", exc_p)
                guardar_evento_auditoria("CIERRE AUTOMÁTICO DE BOLETO",
                                         f"Folio {reg.get('id')} · {sucursal} · placas {reg.get('placas')} · ${pago['importe']:,.2f} {pago['metodo']} "
                                         f"(calculado ${pago['importe_calculado']:,.2f}) · motivo: {pago['observaciones']} · por {usuario}")
            st.session_state[f"ca_aviso_{sucursal}"] = (f"✅ Se cerraron {len(upserts)} boleto(s) por ${sum(p['importe'] for p in pagos):,.2f}. "
                                                         + (f"Ya estaban cerrados: {', '.join(ya_cerrados)}." if ya_cerrados else ""))
            st.session_state.vehiculos = cargar_bd()
            st.rerun()
        elif ya_cerrados and not upserts:
            st.warning("Esos boletos ya estaban cerrados desde otro teléfono.")
        else:
            st.error("No se pudo guardar. Intenta de nuevo.")


def _cobro_actual_resguardo(r, momento=None):
    """Lo que se cobraría si el vehículo saliera ahora (estancia completa desde que entró)."""
    try:
        cfg = tarifa_de(r.get("sucursal"))
        modalidad = r.get("modalidad_tarifa") or modalidades_disponibles(cfg)[0]
        return round(float(calcular_cobro(cfg, modalidad, minutos_estancia(r, momento),
                                          float(r.get("tarifa") or 0) if modalidad == "fija" else None)), 2)
    except Exception:
        return None


def desglose_cobros_cierre(sucursal, fecha, regs_con_cobro, ids_del_dia):
    """Cobros del turno agrupados por tipo de tarifa y precio (cuántos vehículos y de a cómo)."""
    nombres = {"tiempo": "Normal por tiempo", "promocion": "Promoción", "fija": "Tarifa fija"}
    grupos = {}
    for r in regs_con_cobro:
        pagos = [p for p in (r.get("pagos") or []) if p.get("estado") == "Pagado" and fecha_op_pago(p) == fecha]
        if not pagos:
            continue
        importe = round(sum(dinero(p.get("importe")) for p in pagos), 2)
        p0 = pagos[-1]
        metodo = str(p0.get("metodo") or "")
        modalidad = p0.get("modalidad_tarifa") or r.get("modalidad_tarifa") or ""
        tipo = p0.get("tipo_cliente") or r.get("tipo_cliente") or ""
        if p0.get("sellado") or metodo == METODO_SELLADO:
            concepto = "Sellado"
        elif metodo == METODO_CORTESIA:
            concepto = "Cortesía" + (f" · {tipo}" if tipo else "")
        elif buscar_pension_por_placa(r.get("placas"), sucursal):
            concepto = "Pensión (entrada sin boleto)"
        else:
            concepto = nombres.get(modalidad, modalidad or "Tarifa de la sucursal") + (f" · {tipo}" if tipo else "")
        if p0.get("cierre_automatico"):
            concepto += " · cierre automático"
        if r.get("id") not in ids_del_dia:
            concepto += " · día anterior"
        clave = (concepto, importe)
        g = grupos.setdefault(clave, {"Tarifa / tipo": concepto, "Cobro por vehículo": importe, "Vehículos": 0, "Total": 0.0, "Forma de pago": set()})
        g["Vehículos"] += 1
        g["Total"] += importe
        g["Forma de pago"].add(metodo or "Efectivo")
    filas = sorted(grupos.values(), key=lambda g: (g["Tarifa / tipo"], g["Cobro por vehículo"]))
    for g in filas:
        g["Total"] = round(g["Total"], 2)
        g["Forma de pago"] = ", ".join(sorted(g["Forma de pago"]))
    pensiones = []
    for pen in cargar_pensiones():
        if pen.get("sucursal") != sucursal:
            continue
        for pp in pen.get("pagos") or []:
            if str(pp.get("fecha_hora") or "")[:10] == fecha.isoformat():
                pensiones.append({"Titular": pen.get("titular"), "Placas": pen.get("placas"), "Mensualidad pagada": dinero(pp.get("importe")),
                                  "Meses": pp.get("meses"), "Forma de pago": pp.get("metodo"), "Pagado hasta": pp.get("periodo_hasta")})
    return filas, pensiones


def _seccion_cierre_diario():
    global col, exc, pago, reg, writer, ws
    globals()["_CONTADOR_LLAVES"] = 1000  # llaves estables entre recargas completas y de sección
    with tab_cierre_diario:
        encabezado_institucional("REPORTE DIARIO DE CIERRE POR SUCURSAL", "CIERRE OPERATIVO", "Balance formal del día: ingresos, gastos y resultado por sucursal")
        st.caption(
            "Captura y entrega el balance diario de boletos, cobros y gastos. "
            "Cada sucursal puede guardar un cierre por fecha; el contador puede consultar todas."
        )

        CIERRES_DIARIOS_FILE = DATA_DIR / "cierres_diarios_sucursal.json"
        GASTOS_CIERRE_FILE = DATA_DIR / "gastos_operativos.json"

        def cargar_cierres_diarios():
            if not CIERRES_DIARIOS_FILE.exists():
                return []
            try:
                contenido = json.loads(CIERRES_DIARIOS_FILE.read_text(encoding="utf-8"))
                return contenido if isinstance(contenido, list) else []
            except (OSError, json.JSONDecodeError):
                return []

        def guardar_cierres_diarios(contenido):
            with _candado_bd():
                _escribir_json_seguro(CIERRES_DIARIOS_FILE, contenido)

        def fecha_a_date(valor):
            for formato in ("%d/%m/%Y %H:%M:%S", "%Y-%m-%d %H:%M:%S", "%d/%m/%Y", "%Y-%m-%d"):
                try:
                    return datetime.strptime(str(valor or ""), formato).date()
                except (ValueError, TypeError):
                    continue
            return None

        def numero_folio(valor):
            try:
                return int(str(valor or "").strip().rsplit("-", 1)[-1])
            except (ValueError, TypeError):
                return None

        sucursales_cierre = SUCURSALES if es_global else [st.session_state.sucursal_asignada]
        sucursal_cierre = st.selectbox("Sucursal del reporte", sucursales_cierre, key="sucursal_reporte_cierre_diario")
        j_cierre = jornada_abierta(sucursal_cierre)
        _fechas_mov_cierre = sorted({fecha_op_registro(r) for r in st.session_state.vehiculos
                                     if r.get("sucursal") == sucursal_cierre and fecha_op_registro(r)}, reverse=True)
        _fechas_con_cierre = {str(c.get("fecha")) for c in cargar_cierres_diarios() if c.get("sucursal") == sucursal_cierre}
        if j_cierre:
            fecha_def_cierre = date.fromisoformat(j_cierre["fecha_operativa"])
        else:
            # Sin jornada abierta: se propone el último día con vehículos que todavía no tiene cierre (p. ej. pasada la medianoche)
            _hoy_c = ahora_mx().date()
            fecha_def_cierre = next((f for f in _fechas_mov_cierre if (_hoy_c - f).days <= 3 and f.isoformat() not in _fechas_con_cierre),
                                    _hoy_c)
        _hoy_pend = ahora_mx().date()
        _pendientes_cierre = [f for f in _fechas_mov_cierre if f.isoformat() not in _fechas_con_cierre
                              and 0 <= (_hoy_pend - f).days <= 15 and (not j_cierre or f.isoformat() != j_cierre.get("fecha_operativa"))]
        if _pendientes_cierre:
            st.warning("📌 Días con vehículos que **todavía no tienen cierre**: "
                       + ", ".join(f"{f:%d/%m/%Y}" for f in sorted(_pendientes_cierre))
                       + ". Elige cada fecha abajo y guarda su cierre para que cuadre con el reporte físico de ese día.")
        fecha_cierre = st.date_input("Fecha operativa del cierre", value=fecha_def_cierre,
                                     key=f"fecha_reporte_cierre_diario_{sucursal_cierre}_{fecha_def_cierre}",
                                     disabled=bool(j_cierre) and not es_global and not _pendientes_cierre,   # el Líder cierra su turno abierto
                                     help="El turno empieza con el primer vehículo registrado y termina al guardar este cierre.")
        if j_cierre:
            _primeros_j = sorted((r for r in st.session_state.vehiculos if r.get("sucursal") == sucursal_cierre
                                  and fecha_op_registro(r) == fecha_def_cierre and r.get("fecha_entrada_iso")),
                                 key=lambda r: str(r.get("fecha_entrada_iso")))
            _inicio_txt = (f"{_primeros_j[0].get('fecha_entrada') or _primeros_j[0].get('fecha_entrada_iso')} "
                           f"(primer vehículo: folio {_primeros_j[0].get('id')})") if _primeros_j else str(j_cierre.get("abierta_en", ""))
            _dias_abierto = (ahora_mx().date() - fecha_def_cierre).days
            if _dias_abierto >= 2:
                st.error(f"⚠️ Este turno lleva **{_dias_abierto} días abierto** (desde el {fecha_def_cierre:%d/%m/%Y}): todo lo registrado "
                         "desde entonces está contando en ese mismo reporte. Haz el cierre para que el siguiente vehículo empiece un turno nuevo.")
            st.info(f"🟢 **Turno abierto de {sucursal_cierre}** · fecha operativa **{fecha_def_cierre:%d/%m/%Y}** · "
                    f"empezó: {_inicio_txt} · termina al guardar este cierre. Todo lo que se registre y cobre en el turno cuenta "
                    "en este reporte, aunque pase de medianoche. Después del cierre, el siguiente vehículo registrado inicia el turno nuevo.")
            if fecha_cierre != fecha_def_cierre:
                st.warning(f"Elegiste {fecha_cierre:%d/%m/%Y}, pero la jornada abierta es del {fecha_def_cierre:%d/%m/%Y}.")
        else:
            st.caption("No hay jornada abierta en esta sucursal: el primer vehículo que entre la iniciará.")
        try:
            vista_reporte_avance(sucursal_cierre, fecha_cierre, clave="avance_cierre")
        except Exception as exc_av:
            registrar_falla("reporte_avance", exc_av)
        if st.session_state.get(f"ca_aviso_{sucursal_cierre}"):
            st.success(st.session_state.pop(f"ca_aviso_{sucursal_cierre}"))
        try:
            vista_cierre_automatico(sucursal_cierre)
        except Exception as exc_ca:
            registrar_falla("cierre_automatico", exc_ca)

        registros_cierre = [
            r for r in st.session_state.vehiculos
            if r.get("sucursal") == sucursal_cierre and fecha_op_registro(r) == fecha_cierre
        ]
        gastos_cierre = []
        if GASTOS_CIERRE_FILE.exists():
            try:
                datos_gastos = json.loads(GASTOS_CIERRE_FILE.read_text(encoding="utf-8"))
                if isinstance(datos_gastos, list):
                    gastos_cierre = [
                        g for g in datos_gastos
                        if g.get("sucursal") == sucursal_cierre and fecha_a_date(g.get("fecha")) == fecha_cierre
                        and g.get("origen") != "Cierre diario"
                    ]
            except (OSError, json.JSONDecodeError):
                gastos_cierre = []

        total_gastos_registrados = sum(dinero(g.get("importe")) for g in gastos_cierre)
        pagos_confirmados_cierre = []
        folios_pagados = set()
        ingresos_confirmados_cierre = 0.0
        ids_reg_cierre = {r.get("id") for r in registros_cierre}
        regs_con_cobro_cierre = [r for r in st.session_state.vehiculos if r.get("sucursal") == sucursal_cierre
                                 and (r.get("id") in ids_reg_cierre or any(p.get("estado") == "Pagado" and fecha_op_pago(p) == fecha_cierre
                                                                     for p in (r.get("pagos") or [])))]
        for reg in regs_con_cobro_cierre:
            pagos_reg = [pago for pago in reg.get("pagos", []) if pago.get("estado") == "Pagado" and fecha_op_pago(pago) == fecha_cierre]
            if pagos_reg:
                for pago in pagos_reg:
                    pagos_confirmados_cierre.append(pago)
                    ingresos_confirmados_cierre += dinero(pago.get("importe"))
                folios_pagados.add(reg.get("id"))
            elif reg.get("pago_estado") == "Pagado" and not reg.get("pagos") and reg.get("id") in ids_reg_cierre:
                folios_pagados.add(reg.get("id"))
                ingresos_confirmados_cierre += dinero(reg.get("importe_cobrado", reg.get("tarifa", 0)))

        cancelados_auto = sum(1 for r in registros_cierre if str(r.get("estado", "")).lower() in ("cancelado", "cancelada"))
        perdidos_auto = sum(1 for r in registros_cierre if str(r.get("estado", "")).lower() in ("perdido", "perdida", "extraviado", "extraviada"))
        pares_folios = [(numero_folio(r.get("id")), str(r.get("id", ""))) for r in registros_cierre]
        pares_folios = [(n, folio) for n, folio in pares_folios if n is not None]
        folio_inicial_default = min(pares_folios, key=lambda x: x[0])[1] if pares_folios else ""
        folio_final_default = max(pares_folios, key=lambda x: x[0])[1] if pares_folios else ""
        # La firma de los datos va en la llave: si entran o se cobran más vehículos, el formulario se vuelve a llenar solo
        _firma_cierre = f"{len(registros_cierre)}_{len(folios_pagados)}_{cancelados_auto}_{perdidos_auto}_{int(ingresos_confirmados_cierre)}"
        clave_widget_cierre = f"{sucursal_cierre}_{fecha_cierre:%Y%m%d}_{_firma_cierre}".replace(" ", "_")
        if registros_cierre or folios_pagados:
            st.success(f"🧾 **Llenado automático con lo que registró la app el {fecha_cierre:%d/%m/%Y}:** "
                       f"{len(registros_cierre)} vehículo(s) ingresado(s) · {len(folios_pagados)} cobrado(s) · "
                       f"${ingresos_confirmados_cierre:,.2f} cobrado"
                       + (f" · folios {folio_inicial_default} a {folio_final_default}" if folio_inicial_default else "")
                       + (f" · {cancelados_auto} cancelado(s)" if cancelados_auto else "")
                       + (f" · {perdidos_auto} perdido(s)" if perdidos_auto else "") + ".")
            try:
                _desglose_c, _pension_c = desglose_cobros_cierre(sucursal_cierre, fecha_cierre, regs_con_cobro_cierre, ids_reg_cierre)
                with st.expander("💲 Cobros por tarifa: cuántos vehículos y de a cómo", expanded=True):
                    if _desglose_c:
                        _df_des = pd.DataFrame(_desglose_c)
                        st.dataframe(_df_des, use_container_width=True, hide_index=True,
                                     column_config={"Cobro por vehículo": st.column_config.NumberColumn(format="$%.2f"),
                                                    "Total": st.column_config.NumberColumn(format="$%.2f")})
                        st.caption(f"Total: {int(_df_des['Vehículos'].sum())} vehículo(s) · ${_df_des['Total'].sum():,.2f}. "
                                   "«Día anterior» = autos que entraron otro día y se cobraron en este turno.")
                    else:
                        st.caption("Sin cobros en este turno.")
                    if _pension_c:
                        st.markdown("**🅿️ Pensiones**")
                        st.dataframe(pd.DataFrame(_pension_c), use_container_width=True, hide_index=True)
            except Exception as exc_des:
                registrar_falla("desglose_cierre", exc_des)
            with st.expander(f"🎫 Folios utilizados en el turno ({len(registros_cierre)})"):
                _pag_por_folio = {}
                for _r in regs_con_cobro_cierre:
                    _imp = sum(dinero(p.get("importe")) for p in (_r.get("pagos") or [])
                               if p.get("estado") == "Pagado" and fecha_op_pago(p) == fecha_cierre)
                    _met = ", ".join(sorted({str(p.get("metodo") or "") for p in (_r.get("pagos") or [])
                                             if p.get("estado") == "Pagado" and fecha_op_pago(p) == fecha_cierre}))
                    _pag_por_folio[_r.get("id")] = (_imp, _met)
                _filas_f = sorted(registros_cierre, key=lambda r: (numero_folio(r.get("id")) or 0))
                st.dataframe(pd.DataFrame([{
                    "Folio": r.get("id"), "Placas": r.get("placas"), "Vehículo": f"{r.get('marca', '')} {r.get('color', '')}".strip(),
                    "Entrada": r.get("fecha_entrada") or r.get("fecha"), "Estado": r.get("estado"),
                    "Cobrado": _pag_por_folio.get(r.get("id"), (0, ""))[0], "Forma de pago": _pag_por_folio.get(r.get("id"), (0, ""))[1],
                } for r in _filas_f]), use_container_width=True, hide_index=True,
                    column_config={"Cobrado": st.column_config.NumberColumn(format="$%.2f")})
                _nums_f = sorted(n for n, _ in pares_folios)
                if _nums_f:
                    _faltan_f = sorted(set(range(_nums_f[0], _nums_f[-1] + 1)) - set(_nums_f))
                    if _faltan_f:
                        st.warning(f"Números de folio que no aparecen en la app dentro del rango ({len(_faltan_f)}): "
                                   + ", ".join(str(n) for n in _faltan_f[:60]) + (" …" if len(_faltan_f) > 60 else "")
                                   + ". Pueden ser boletos de otro día, reservados para el modo sin conexión o boletos físicos sin capturar.")
                    else:
                        st.caption("✅ Folios consecutivos, sin huecos.")
        else:
            _otras_c = [f for f in _fechas_mov_cierre if f != fecha_cierre][:3]
            st.warning(f"La app no tiene vehículos de {sucursal_cierre} con fecha operativa {fecha_cierre:%d/%m/%Y}, por eso los conteos salen en 0."
                       + (" Último día con movimiento: " + ", ".join(f"{f:%d/%m/%Y}" + (" (ya tiene cierre)" if f.isoformat() in _fechas_con_cierre else "")
                                                                   for f in _otras_c) + ". Cambia la «Fecha operativa del cierre» arriba." if _otras_c else ""))

        st.markdown("#### Datos del turno y control de boletos")
        st.caption("Los conteos se precargan desde los registros del sistema. Puedes corregirlos si hubo boletos físicos no capturados digitalmente.")
        c1, c2, c3 = st.columns(3)
        with c1:
            fecha_precio = st.number_input(
                "Costo unitario del boleto ($)", min_value=0.0,
                value=float(PRECIOS_SUCURSALES.get(sucursal_cierre, 0)), step=5.0,
                key=llave_unica(f"cierre_precio_{clave_widget_cierre}")
            )
            folio_inicial = st.text_input(
                "Folio inicial de la sesión", value=folio_inicial_default,
                key=llave_unica(f"cierre_folio_ini_{clave_widget_cierre}")
            )
        with c2:
            folio_final = st.text_input(
                "Folio final de la sesión", value=folio_final_default,
                key=llave_unica(f"cierre_folio_fin_{clave_widget_cierre}")
            )
            total_boletos_auto = len(registros_cierre)
            ni = numero_folio(folio_inicial)
            nf = numero_folio(folio_final)
            if ni is not None and nf is not None and nf >= ni:
                total_boletos_auto = nf - ni + 1
            total_boletos = st.number_input(
                "Total de boletos utilizados", min_value=0, value=int(total_boletos_auto), step=1,
                key=llave_unica(f"cierre_total_{clave_widget_cierre}")
            )
        with c3:
            boletos_pagados = st.number_input(
                "Boletos pagados", min_value=0, value=int(len(folios_pagados & ids_reg_cierre)), step=1,
                key=llave_unica(f"cierre_pagados_{clave_widget_cierre}")
            )
            boletos_cancelados = st.number_input(
                "Boletos cancelados", min_value=0, value=int(cancelados_auto), step=1,
                key=llave_unica(f"cierre_cancelados_{clave_widget_cierre}")
            )
            boletos_perdidos = st.number_input(
                "Boletos perdidos", min_value=0, value=int(perdidos_auto), step=1,
                key=llave_unica(f"cierre_perdidos_{clave_widget_cierre}")
            )

        st.markdown("#### Gastos generales y balance")
        st.write(f"**Gastos operativos ya registrados en el sistema:** ${total_gastos_registrados:,.2f} MXN")
        st.caption("Si agregas un gasto adicional aquí, quedará en este cierre diario y no se duplicará en el catálogo de gastos operativos.")
        _clave_lider_c = f"{sucursal_cierre}_{fecha_cierre:%Y%m%d}".replace(" ", "_")   # no cambia aunque entren más autos
        st.markdown("**🧾 Gastos generales del turno** · los captura el Líder (uno por renglón: concepto e importe)")
        _tabla_gastos_c = st.data_editor(
            pd.DataFrame([{"Concepto": "", "Importe": 0.0}]), num_rows="dynamic", use_container_width=True, hide_index=True,
            column_config={"Concepto": st.column_config.TextColumn("Concepto (ej. gasolina, lavado, insumos)"),
                           "Importe": st.column_config.NumberColumn("Importe ($)", min_value=0.0, step=10.0, format="$%.2f")},
            key=f"cierre_gastos_tabla_{_clave_lider_c}")

        def _renglones_c(df, campos):
            filas = []
            for _, fila in (df if df is not None else pd.DataFrame()).iterrows():
                try:
                    imp = float(fila.get("Importe") or 0)
                except (TypeError, ValueError):
                    imp = 0.0
                if imp > 0:
                    filas.append(dict({c: str(fila.get(c) or "").strip() for c in campos}, Importe=round(imp, 2)))
            return filas

        gastos_lider_c = _renglones_c(_tabla_gastos_c, ["Concepto"])
        gasto_adicional = sum(g["Importe"] for g in gastos_lider_c)
        detalle_gasto_adicional = "; ".join(f"{g['Concepto'] or 'Gasto'} ${g['Importe']:,.2f}" for g in gastos_lider_c)

        total_gastos_cierre = total_gastos_registrados + float(gasto_adicional)
        balance_cierre = ingresos_confirmados_cierre - total_gastos_cierre
        efectivo_cierre = sum(dinero(p.get("importe")) for p in pagos_confirmados_cierre if str(p.get("metodo") or "Efectivo") == "Efectivo")
        otros_cobros_cierre = ingresos_confirmados_cierre - efectivo_cierre
        entregar_cierre = efectivo_cierre - total_gastos_cierre
        m1, m2, m3, m4 = st.columns(4)
        m1.metric("Vehículos registrados ese día", len(registros_cierre))
        m2.metric("Ingresos confirmados", f"${ingresos_confirmados_cierre:,.2f}")
        m3.metric("Gastos totales", f"${total_gastos_cierre:,.2f}")
        m4.metric("Balance del día", f"${balance_cierre:,.2f}")
        e1, e2 = st.columns(2)
        e1.metric("💵 Cobrado en efectivo", f"${efectivo_cierre:,.2f}")
        e2.metric("📦 Efectivo a entregar", f"${entregar_cierre:,.2f}")
        st.caption("Balance = cobros confirmados − gastos. Efectivo a entregar = cobrado en efectivo − gastos"
                   + (f" (los ${otros_cobros_cierre:,.2f} cobrados con tarjeta, Mercado Pago o sellado no están en la caja)." if otros_cobros_cierre else ".")
                   )

        st.markdown("#### 📷 Evidencia fotográfica del cierre")
        st.caption("Sube fotos de la hoja de cierre, boletos y efectivo. Quedan guardadas con este cierre y las puede consultar el Contador.")
        fotos_cierre_archivos = st.file_uploader(
            "Subir fotos desde la galería", type=["png", "jpg", "jpeg"], accept_multiple_files=True,
            key=llave_unica(f"cierre_fotos_{clave_widget_cierre}"),
        )
        foto_cierre_camara = None
        llave_cam_cierre = llave_unica(f"cierre_camara_{clave_widget_cierre}")  # misma cantidad de llaves en cada ejecución
        if st.checkbox("📸 Tomar foto con la cámara", key=f"cierre_cam_on_{clave_widget_cierre}"):
            foto_cierre_camara = st.camera_input("Cámara", key=llave_cam_cierre)
        nuevas_fotos_cierre = list(fotos_cierre_archivos or []) + ([foto_cierre_camara] if foto_cierre_camara else [])
        if nuevas_fotos_cierre:
            cols_prev = st.columns(3)
            for i_prev, f_prev in enumerate(nuevas_fotos_cierre):
                cols_prev[i_prev % 3].image(f_prev, use_container_width=True)
        else:
            st.warning("Aún no has adjuntado evidencia fotográfica de este cierre.")

        fecha_cierre_txt = fecha_cierre.strftime("%d/%m/%Y")
        fisico_cierre = next((r for r in _leer_lista_json(FISICOS_FILE) if r.get("tipo_reporte") == "ingresos"
                              and r.get("Sitio / Unidad") == sucursal_cierre and r.get("Fecha") == fecha_cierre_txt
                              and r.get("origen") != "Cierre del sistema"), None)
        if fisico_cierre:
            st.info(f"Esta sucursal ya tiene reporte físico de ingresos del {fecha_cierre_txt} ({fisico_cierre.get('ID')}). El cierre se guarda como respaldo; en auditoría y Excel manda el reporte físico.")
        else:
            st.info("No hay reporte físico de ingresos de esta sucursal y fecha: al guardar, el cierre se sube automáticamente a Reportes físicos para auditarlo.")

        cierres_guardados = cargar_cierres_diarios()
        cierre_existente = next((c for c in cierres_guardados if c.get("fecha") == str(fecha_cierre) and c.get("sucursal") == sucursal_cierre), None)
        if es_contador and cierre_existente and not jornada_abierta(sucursal_cierre):
            with st.expander("🔓 Reabrir esta jornada (solo Contador Auditor)"):
                st.caption("Vuelve a abrir la jornada para que los nuevos movimientos cuenten en esta fecha. Después hay que reemplazar el cierre.")
                if st.button("🔓 Reabrir jornada", key=f"reabrir_jornada_{clave_widget_cierre}"):
                    jornadas_r = cargar_jornadas()
                    for j in jornadas_r:
                        if j.get("sucursal") == sucursal_cierre and j.get("fecha_operativa") == str(fecha_cierre):
                            j.update({"estado": "Abierta", "reabierta_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                                      "reabierta_por": st.session_state.usuario_autenticado})
                            break
                    _guardar_lista_json(JORNADAS_FILE, jornadas_r)
                    guardar_evento_auditoria("JORNADA REABIERTA", f"{sucursal_cierre} · {fecha_cierre:%d/%m/%Y}")
                    st.success("Jornada reabierta.")
                    st.rerun()
        if cierre_existente and es_contador:
            st.warning(f"Ya existe un cierre para {sucursal_cierre} el {fecha_cierre}. Marca la casilla para reemplazarlo con los datos actuales.")
        elif cierre_existente:
            st.error(f"Ya existe un cierre para {sucursal_cierre} el {fecha_cierre}. No se puede subir dos veces: solo el Contador Auditor puede reemplazarlo o borrarlo.")
        reemplazar_cierre = st.checkbox(
            "Confirmo que deseo reemplazar el cierre existente de esta sucursal y fecha",
            value=False, key=llave_unica(f"cierre_reemplazar_{clave_widget_cierre}"), disabled=not (cierre_existente and es_contador)
        )
        en_custodia_cierre = [r for r in st.session_state.vehiculos
                              if r.get("sucursal") == sucursal_cierre and r.get("estado", "En Resguardo") == "En Resguardo"]
        ok_custodia_cierre = True
        if en_custodia_cierre:
            st.warning(f"🅿️ Quedan **{len(en_custodia_cierre)} vehículo(s) en el estacionamiento**. No hace falta esperarlos: "
                       "pasan al reporte del día siguiente y se cobran el día que salgan (ese cobro cuenta en el reporte de ese día).")
            _ahora_cu = ahora_mx().replace(tzinfo=None)
            _filas_cu = []
            for r in sorted(en_custodia_cierre, key=lambda x: str(x.get("fecha_entrada_iso") or "")):
                try:
                    _ent = datetime.fromisoformat(str(r.get("fecha_entrada_iso") or "")).replace(tzinfo=None)
                    _hrs = (_ahora_cu - _ent).total_seconds() / 3600
                except ValueError:
                    _hrs = None
                _filas_cu.append({"Folio": r.get("id"), "Placas": r.get("placas"),
                                  "Vehículo": f"{r.get('marca', '')} {r.get('color', '')}".strip(),
                                  "Entró": r.get("fecha_entrada") or r.get("fecha"),
                                  "Tiempo adentro": (f"{int(_hrs // 24)} día(s) {int(_hrs % 24)} h" if _hrs and _hrs >= 24 else
                                                     (f"{int(_hrs)} h" if _hrs is not None else "—")),
                                  "Lleva a la hora actual": _cobro_actual_resguardo(r, _ahora_cu),
                                  "Pensión": "Sí" if buscar_pension_por_placa(r.get("placas"), sucursal_cierre) else ""})
            st.dataframe(pd.DataFrame(_filas_cu), use_container_width=True, hide_index=True,
                         column_config={"Lleva a la hora actual": st.column_config.NumberColumn(format="$%.2f")})
            st.caption("El tiempo **sigue corriendo desde la hora en que entró**, aunque cambie el reporte: al salir se cobra la estancia "
                       "completa con la tarifa de la sucursal (por ejemplo $100 las primeras 10 h y $75 cada 10 h más). "
                       "No afecta este cierre: el cobro entra completo en el reporte del día en que sale.")
            ok_custodia_cierre = st.checkbox("Confirmo que estos vehículos siguen en custodia y pasan a la siguiente jornada",
                                             key=f"cierre_ok_custodia_{clave_widget_cierre}")
        if st.button("💾 Guardar cierre diario", type="primary", key=llave_unica(f"guardar_cierre_diario_{clave_widget_cierre}"),
                     disabled=not ok_custodia_cierre):
            if int(total_boletos) > 0 and (not folio_inicial.strip() or not folio_final.strip()):
                st.error("Captura el folio inicial y el folio final de la sesión (o deja el total de boletos en 0 si no hubo movimiento).")
            elif int(boletos_pagados) + int(boletos_cancelados) + int(boletos_perdidos) > int(total_boletos):
                st.error("La suma de boletos pagados, cancelados y perdidos no puede superar el total de boletos utilizados.")
            elif cierre_existente and not es_contador:
                st.error("El cierre ya existe. Solo el Contador Auditor puede reemplazarlo.")
            elif cierre_existente and not reemplazar_cierre:
                st.error("El cierre ya existe. Marca la casilla de reemplazo si realmente necesitas corregirlo.")
            else:
                cierre = {
                    "id": cierre_existente.get("id") if cierre_existente else uuid.uuid4().hex[:12].upper(),
                    "fecha": str(fecha_cierre),
                    "sucursal": sucursal_cierre,
                    "costo_unitario_boleto": float(fecha_precio),
                    "folio_inicial": folio_inicial.strip(),
                    "folio_final": folio_final.strip(),
                    "total_boletos": int(total_boletos),
                    "boletos_pagados": int(boletos_pagados),
                    "boletos_cancelados": int(boletos_cancelados),
                    "boletos_perdidos": int(boletos_perdidos),
                    "ingresos_confirmados": round(ingresos_confirmados_cierre, 2),
                    "gastos_operativos_registrados": round(total_gastos_registrados, 2),
                    "gastos_generales_adicionales": round(float(gasto_adicional), 2),
                    "concepto_gastos_adicionales": detalle_gasto_adicional.strip(),
                    "gastos_totales": round(total_gastos_cierre, 2),
                    "balance_neto": round(balance_cierre, 2),
                    "gastos_lider": gastos_lider_c,
                    "efectivo_cobrado": round(efectivo_cierre, 2), "efectivo_a_entregar": round(entregar_cierre, 2),
                    "usuario": st.session_state.usuario_autenticado,
                    "rol": st.session_state.rol,
                    "guardado_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                }
                if cierre_existente:
                    cierres_guardados = [cierre if c.get("id") == cierre_existente.get("id") else c for c in cierres_guardados]
                else:
                    cierres_guardados.insert(0, cierre)
                try:
                    rutas_evidencia = list((cierre_existente or {}).get("fotos_evidencia", []))
                    if nuevas_fotos_cierre:
                        rutas_evidencia = []
                        base_foto = re.sub(r"[^A-Za-z0-9_-]+", "_", f"CIERRE_{sucursal_cierre}_{fecha_cierre:%Y%m%d}")
                        for i_ev, f_ev in enumerate(nuevas_fotos_cierre, start=1):
                            rutas_evidencia.append(guardar_foto(f_ev, base_foto, f"evidencia_{i_ev}"))
                    cierre["fotos_evidencia"] = rutas_evidencia
                    _candado_bd().acquire()
                    try:
                        _frescos_c = [c for c in cargar_cierres_diarios()
                                      if c.get("id") != cierre["id"] and not (c.get("sucursal") == sucursal_cierre and c.get("fecha") == str(fecha_cierre))]
                        guardar_cierres_diarios([cierre] + _frescos_c)
                    finally:
                        _candado_bd().release()
                    cerrar_jornada(sucursal_cierre, fecha_cierre, cierre["id"])
                    # Gasto adicional del cierre: pasa al libro de gastos (sin duplicar al reemplazar)
                    gastos_cierre_nuevos = []
                    for g_l in gastos_lider_c:   # cada gasto del Líder pasa al libro de gastos (sin duplicar al reemplazar)
                        gastos_cierre_nuevos.append({
                            "id": uuid.uuid4().hex[:12].upper(), "fecha": str(fecha_cierre), "sucursal": sucursal_cierre,
                            "categoria": categoria_gasto_de("", g_l["Concepto"]) if g_l["Concepto"] else "Otros",
                            "concepto": g_l["Concepto"] or "Gasto del cierre",
                            "importe": float(g_l["Importe"]), "registrado_por": st.session_state.usuario_autenticado,
                            "registrado_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                            "origen": "Cierre diario", "cierre_id": cierre["id"],
                        })
                    actualizar_lista_json(GASTOS_FILE_RF, lambda lista: gastos_cierre_nuevos + [g for g in lista if g.get("cierre_id") != cierre["id"]])
                    # Si no hay reporte físico de ingresos, el cierre se sube como reporte para auditar
                    reportes_libro = _leer_lista_json(FISICOS_FILE)
                    hay_fisico = any(r.get("tipo_reporte") == "ingresos" and r.get("Sitio / Unidad") == sucursal_cierre
                                     and r.get("Fecha") == fecha_cierre_txt and r.get("origen") != "Cierre del sistema" for r in reportes_libro)
                    if not hay_fisico:
                        reportes_libro = [r for r in reportes_libro if not (r.get("origen") == "Cierre del sistema"
                                          and r.get("Sitio / Unidad") == sucursal_cierre and r.get("Fecha") == fecha_cierre_txt)]
                        rid_auto = f"CIE_{cierre['id'][:8]}"
                        reporte_auto = _fila_flujo(
                            sucursal_cierre, fecha_cierre, ingresos_confirmados_cierre, int(boletos_pagados), float(fecha_precio),
                            numero_folio(folio_inicial) or 0, numero_folio(folio_final) or 0, int(total_boletos),
                            st.session_state.usuario_autenticado, st.session_state.usuario_autenticado, rid_auto)
                        reporte_auto.update({
                            "Cancelados": int(boletos_cancelados), "Perdidos": int(boletos_perdidos),
                            "tipo_reporte": "ingresos", "origen": "Cierre del sistema", "cierre_id": cierre["id"],
                            "Gastos (hoja)": "; ".join(f"{g['Concepto']}: ${g['Importe']:,.2f}" for g in gastos_lider_c),
                            "Cantidad a entregar": round(entregar_cierre, 2),
                            "fotos": rutas_evidencia, "Nivel Auditoría": "Sin reporte físico (cierre del sistema)",
                            "Timestamp": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                        })
                        actualizar_lista_json(FISICOS_FILE, lambda lista: [reporte_auto] + [
                            r for r in lista if not (r.get("origen") == "Cierre del sistema" and r.get("Sitio / Unidad") == sucursal_cierre
                                                     and r.get("Fecha") == fecha_cierre_txt)])
                        guardar_evento_auditoria("CIERRE SUBIDO PARA AUDITORÍA", f"{sucursal_cierre} · {fecha_cierre_txt} · {rid_auto} · sin reporte físico")
                    guardar_evento_auditoria("CIERRE DIARIO POR SUCURSAL", f"{sucursal_cierre} · {fecha_cierre} · ingresos ${ingresos_confirmados_cierre:.2f} · gastos ${total_gastos_cierre:.2f} · balance ${balance_cierre:.2f}")
                    st.success("Cierre diario guardado. Ya puedes descargar la hoja de cálculo para entregar el balance.")
                    st.rerun()
                except Exception as exc:
                    st.error(f"No se pudo guardar el cierre diario: {exc}")

        st.divider()
        st.markdown("#### Historial y entrega de hoja de cálculo")
        cierres_guardados = cargar_cierres_diarios()
        cierres_visibles = cierres_guardados if es_global else [c for c in cierres_guardados if c.get("sucursal") == st.session_state.sucursal_asignada]

        def _borrar_cierre(c_b, reabrir=False):
            """Borra un cierre con su gasto adicional, su reporte automático y sus fotos; opcionalmente reabre la jornada."""
            id_c = c_b.get("id")
            with _candado_bd():
                guardar_cierres_diarios([c for c in cargar_cierres_diarios() if c.get("id") != id_c])
                actualizar_lista_json(GASTOS_FILE_RF, lambda l: [g for g in l if g.get("cierre_id") != id_c])
                actualizar_lista_json(FISICOS_FILE, lambda l: [r for r in l if not (r.get("origen") == "Cierre del sistema" and r.get("cierre_id") == id_c)])
                if reabrir and not jornada_abierta(c_b.get("sucursal")):
                    def _reabrir(lista):
                        for j in lista:
                            if j.get("sucursal") == c_b.get("sucursal") and j.get("fecha_operativa") == str(c_b.get("fecha")):
                                j.update({"estado": "Abierta", "reabierta_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                                          "reabierta_por": st.session_state.usuario_autenticado})
                                break
                        return lista
                    actualizar_lista_json(JORNADAS_FILE, _reabrir)
            _borrar_archivos(c_b.get("fotos_evidencia"))
            guardar_evento_auditoria("CIERRE DIARIO BORRADO", f"{c_b.get('sucursal')} · {c_b.get('fecha')} · {id_c}" + (" · jornada reabierta" if reabrir else ""))

        if es_global and cierres_visibles:
            fh1, fh2, fh3 = st.columns(3)
            suc_hist = fh1.selectbox("Sucursal", ["Todas"] + sorted({c.get("sucursal", "") for c in cierres_visibles}), key="hist_cierre_suc")
            desde_hist = fh2.date_input("Desde", value=ahora_mx().date() - timedelta(days=30), key="hist_cierre_desde")
            hasta_hist = fh3.date_input("Hasta", value=ahora_mx().date(), key="hist_cierre_hasta")
            cierres_visibles = [c for c in cierres_visibles if (suc_hist == "Todas" or c.get("sucursal") == suc_hist)
                                and (lambda f: f is not None and desde_hist <= f <= hasta_hist)(fecha_flexible(c.get("fecha")))]
            st.caption(f"{len(cierres_visibles)} cierre(s) en el filtro.")
            if es_contador and cierres_visibles:
                with st.expander("🗑️ Borrar varios cierres a la vez (solo Contador Auditor)"):
                    st.caption("Se borra cada cierre con su gasto adicional, el reporte automático que generó y sus fotos.")
                    nonce_bc = st.session_state.get("bc_nonce", 0)
                    todos_bc = st.checkbox(f"Marcar todos ({len(cierres_visibles)})", key=f"bc_todos_{nonce_bc}")
                    df_bc = pd.DataFrame([{"Borrar": bool(todos_bc), "Fecha": c.get("fecha"), "Sucursal": c.get("sucursal"),
                                           "Balance": dinero(c.get("balance_neto")), "Guardó": c.get("usuario"), "ID": c.get("id")}
                                          for c in cierres_visibles])
                    tabla_bc = st.data_editor(df_bc, use_container_width=True, hide_index=True,
                                              key=f"bc_tabla_{nonce_bc}_{suc_hist}_{todos_bc}",
                                              column_config={"Borrar": st.column_config.CheckboxColumn("Borrar"),
                                                             "Balance": st.column_config.NumberColumn("Balance", format="$%.2f")},
                                              disabled=["Fecha", "Sucursal", "Balance", "Guardó", "ID"])
                    ids_bc = [f["ID"] for f in tabla_bc.to_dict("records") if f.get("Borrar")]
                    reabrir_bc = st.checkbox("Reabrir la jornada de esos días (para volver a hacer el cierre)", key=f"bc_reabrir_{nonce_bc}")
                    ok_bc = st.checkbox(f"Confirmo borrar {len(ids_bc)} cierre(s)", key=f"bc_ok_{nonce_bc}", disabled=not ids_bc)
                    if st.button(f"🗑️ Borrar {len(ids_bc)} cierre(s)", type="primary", disabled=not (ids_bc and ok_bc), key=f"bc_btn_{nonce_bc}"):
                        for c_b in [c for c in cierres_visibles if c.get("id") in set(ids_bc)]:
                            _borrar_cierre(c_b, reabrir_bc)
                        st.session_state.bc_nonce = nonce_bc + 1
                        st.success(f"Se borraron {len(ids_bc)} cierre(s).")
                        st.rerun()
        if cierres_visibles:
            df_cierres = pd.DataFrame(cierres_visibles)
            columnas_mostrar_cierres = [
                "fecha", "sucursal", "costo_unitario_boleto", "folio_inicial", "folio_final",
                "total_boletos", "boletos_pagados", "boletos_cancelados", "boletos_perdidos",
                "ingresos_confirmados", "gastos_totales", "balance_neto", "usuario", "guardado_en"
            ]
            st.dataframe(df_cierres.reindex(columns=columnas_mostrar_cierres), use_container_width=True, hide_index=True)
            opciones_cierre = {
                f"{c.get('fecha')} · {c.get('sucursal')} · Balance ${dinero(c.get('balance_neto')):,.2f}": c
                for c in cierres_visibles
            }
            etiqueta_cierre = st.selectbox("Selecciona el cierre que vas a entregar", list(opciones_cierre.keys()), key="seleccionar_cierre_descarga")
            cierre_descarga = opciones_cierre[etiqueta_cierre]
            if es_contador:
                with st.expander("🗑️ Borrar este cierre (solo Contador Auditor)"):
                    st.caption("Se borra el cierre, su gasto adicional, el reporte automático que generó para auditoría y sus fotos de evidencia.")
                    reabrir_1 = st.checkbox("Reabrir la jornada de ese día (para volver a hacer el cierre)",
                                            key=f"borrar_cierre_reabrir_{cierre_descarga.get('id')}")
                    ok_borrar_cierre = st.checkbox("Confirmo que quiero borrar este cierre", key=f"borrar_cierre_ok_{cierre_descarga.get('id')}")
                    if st.button("🗑️ Borrar cierre", disabled=not ok_borrar_cierre, key=f"borrar_cierre_btn_{cierre_descarga.get('id')}"):
                        _borrar_cierre(cierre_descarga, reabrir_1)
                        st.success("Cierre borrado.")
                        st.rerun()
            fotos_ev = cierre_descarga.get("fotos_evidencia") or []
            if fotos_ev:
                st.markdown("**📷 Evidencia fotográfica del cierre**")
                cols_ev = st.columns(3)
                for i_ev, ruta_ev in enumerate(fotos_ev):
                    p_ev = Path(ruta_ev)
                    if not p_ev.is_absolute():
                        p_ev = DATA_DIR / p_ev
                    if p_ev.exists():
                        cols_ev[i_ev % 3].image(str(p_ev), use_container_width=True)
            else:
                st.caption("Este cierre no tiene evidencia fotográfica.")
            fecha_exportacion = fecha_a_date(cierre_descarga.get("fecha"))
            registros_excel_cierre = [
                r for r in st.session_state.vehiculos
                if r.get("sucursal") == cierre_descarga.get("sucursal")
                and fecha_a_date(r.get("fecha")) == fecha_exportacion
            ]
            gastos_excel_cierre = []
            if GASTOS_CIERRE_FILE.exists():
                try:
                    gastos_archivo_excel = json.loads(GASTOS_CIERRE_FILE.read_text(encoding="utf-8"))
                    if isinstance(gastos_archivo_excel, list):
                        gastos_excel_cierre = [
                            g for g in gastos_archivo_excel
                            if g.get("sucursal") == cierre_descarga.get("sucursal")
                            and fecha_a_date(g.get("fecha")) == fecha_exportacion
                            and g.get("origen") != "Cierre diario"
                        ]
                except (OSError, json.JSONDecodeError):
                    gastos_excel_cierre = []
            salida_excel = io.BytesIO()
            df_resumen_cierre = pd.DataFrame([{
                "Fecha": cierre_descarga.get("fecha"),
                "Sucursal": cierre_descarga.get("sucursal"),
                "Costo unitario boleto ($)": cierre_descarga.get("costo_unitario_boleto"),
                "Folio inicial": cierre_descarga.get("folio_inicial"),
                "Folio final": cierre_descarga.get("folio_final"),
                "Total boletos": cierre_descarga.get("total_boletos"),
                "Boletos pagados": cierre_descarga.get("boletos_pagados"),
                "Boletos cancelados": cierre_descarga.get("boletos_cancelados"),
                "Boletos perdidos": cierre_descarga.get("boletos_perdidos"),
                "Ingresos confirmados ($)": cierre_descarga.get("ingresos_confirmados"),
                "Gastos operativos registrados ($)": cierre_descarga.get("gastos_operativos_registrados"),
                "Gastos generales adicionales ($)": cierre_descarga.get("gastos_generales_adicionales"),
                "Concepto gastos adicionales": cierre_descarga.get("concepto_gastos_adicionales"),
                "Gastos totales ($)": cierre_descarga.get("gastos_totales"),
                "Balance neto ($)": cierre_descarga.get("balance_neto"),
                "Elaboró": cierre_descarga.get("usuario"),
                "Rol": cierre_descarga.get("rol"),
                "Fecha/hora de elaboración": cierre_descarga.get("guardado_en"),
            }])
            try:
                with pd.ExcelWriter(salida_excel, engine="openpyxl") as writer:
                    df_resumen_cierre.to_excel(writer, sheet_name="Cierre diario", index=False, startrow=2)
                    ws = writer.sheets["Cierre diario"]
                    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(df_resumen_cierre.columns))
                    ws.cell(row=1, column=1, value="CLUB PARK VALET Y ESTACIONAMIENTOS S.A. DE C.V. — CIERRE DIARIO")
                    ws.cell(row=1, column=1).font = openpyxl.styles.Font(bold=True, size=14, color="FFFFFF")
                    ws.cell(row=1, column=1).fill = openpyxl.styles.PatternFill("solid", fgColor="1F4E78")
                    ws.freeze_panes = "A4"
                    ws.auto_filter.ref = f"A3:{openpyxl.utils.get_column_letter(len(df_resumen_cierre.columns))}4"
                    for col_cells in ws.columns:
                        max_len = max(len(str(cell.value or "")) for cell in col_cells)
                        ws.column_dimensions[openpyxl.utils.get_column_letter(col_cells[0].column)].width = min(max(max_len + 2, 14), 36)
                    ws.append([])
                    ws.append(["Detalle de gastos operativos registrados en la sucursal y fecha"])
                    ws.append(["Categoría", "Concepto", "Importe ($)", "Registrado por"])
                    for gasto in gastos_excel_cierre:
                        ws.append([gasto.get("categoria", ""), gasto.get("concepto", ""), dinero(gasto.get("importe")), gasto.get("registrado_por", "")])
                    ws2 = writer.book.create_sheet("Boletos del día")
                    ws2.append(["Folio", "Fecha de entrada", "Sucursal", "Tarifa ($)", "Estado", "Pagado ($)"])
                    for reg in registros_excel_cierre:
                        pagado_reg = sum(dinero(p.get("importe")) for p in reg.get("pagos", []) if p.get("estado") == "Pagado")
                        if not reg.get("pagos") and reg.get("pago_estado") == "Pagado":
                            pagado_reg = dinero(reg.get("importe_cobrado", reg.get("tarifa", 0)))
                        ws2.append([reg.get("id", ""), reg.get("fecha", ""), reg.get("sucursal", ""), dinero(reg.get("tarifa")), reg.get("estado", ""), pagado_reg])
                    ws2.freeze_panes = "A2"
                    ws2.auto_filter.ref = f"A1:F{max(ws2.max_row, 1)}"
                    for col in ws2.columns:
                        max_len = max(len(str(cell.value or "")) for cell in col)
                        ws2.column_dimensions[openpyxl.utils.get_column_letter(col[0].column)].width = min(max(max_len + 2, 14), 34)
                st.download_button(
                    "📥 Descargar cierre diario en Excel (.xlsx)",
                    data=salida_excel.getvalue(),
                    file_name=f"ClubPark_Cierre_{cierre_descarga.get('sucursal','Sucursal').replace(' ','_')}_{cierre_descarga.get('fecha','')}.xlsx",
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    use_container_width=True,
                    key="descargar_excel_cierre_diario",
                )
                st.download_button(
                    "📄 Descargar cierre diario en CSV",
                    data=df_resumen_cierre.to_csv(index=False).encode("utf-8-sig"),
                    file_name=f"ClubPark_Cierre_{cierre_descarga.get('fecha','')}.csv",
                    mime="text/csv",
                    key="descargar_csv_cierre_diario",
                )
            except Exception as exc:
                st.error(f"No se pudo preparar el Excel del cierre diario: {exc}")
                st.info("Confirma que openpyxl esté instalado en requirements.txt.")
        else:
            st.info("Todavía no hay cierres diarios guardados para esta sucursal.")

if _SECCION == "cierre_diario":
    _seccion_cierre_diario()


