@_fragmento
def aprendizaje_operativo(registros, reportes_fisicos, hoy, semanas=8):
    """Aprende de la operación real de las últimas `semanas`: patrones por sucursal, días/horas fuertes,
    anomalías (último día cerrado contra el promedio del mismo día de la semana) y señales de control."""
    from collections import defaultdict
    from statistics import mean, median
    desde = hoy - timedelta(weeks=semanas)
    ayer = hoy - timedelta(days=1)
    autos = defaultdict(lambda: defaultdict(int))      # suc -> fecha -> vehículos
    cobro = defaultdict(lambda: defaultdict(float))    # suc -> fecha -> importe cobrado en app
    horas = defaultdict(lambda: defaultdict(int))      # suc -> hora -> entradas
    estancias, tickets = defaultdict(list), defaultdict(list)
    sin_pago, ajustes, pagos_tot, metodo_cnt = defaultdict(int), defaultdict(int), defaultdict(int), defaultdict(lambda: defaultdict(int))
    for r in registros:
        suc = r.get("sucursal")
        f = fecha_op_registro(r)
        if not suc or not f or f < desde or f > hoy:
            continue
        autos[suc][f] += 1
        try:
            horas[suc][datetime.fromisoformat(str(r.get("fecha_entrada_iso"))).hour] += 1
        except (TypeError, ValueError):
            pass
        pagos_r = [pg for pg in (r.get("pagos") or []) if pg.get("estado", "Pagado") == "Pagado"]
        if r.get("estado") == "Entregado" and not pagos_r and float(r.get("tarifa") or 0) > 0:
            sin_pago[suc] += 1
        for pg in pagos_r:
            fp = fecha_op_pago(pg) or f
            imp = _flotante_seguro(pg.get("importe"))
            cobro[suc][fp] += imp
            tickets[suc].append(imp)
            pagos_tot[suc] += 1
            metodo_cnt[suc][str(pg.get("metodo") or "Otro")] += 1
            if pg.get("ajuste_manual"):
                ajustes[suc] += 1
            if pg.get("minutos_estancia"):
                estancias[suc].append(_flotante_seguro(pg.get("minutos_estancia")))
    fisico = defaultdict(lambda: defaultdict(float))   # suc -> fecha -> ingreso bruto del reporte físico
    for rf in reportes_fisicos:
        if rf.get("tipo_reporte") != "ingresos":
            continue
        f = fecha_flexible(rf.get("Fecha"))
        if f and desde <= f <= hoy:
            fisico[rf.get("Sitio / Unidad")][f] += _flotante_seguro(rf.get("Ingreso Bruto"))

    def _comparar(serie, etiqueta, unidad):
        """Último día cerrado vs promedio del mismo día de la semana en semanas anteriores."""
        salida = []
        for suc, dias in serie.items():
            previos = [dias.get(ayer - timedelta(weeks=k), 0) for k in range(1, semanas)]
            previos = [v for v in previos if v > 0]
            if len(previos) < 3:
                continue  # aún no hay suficiente historia para comparar
            prom = mean(previos)
            actual = dias.get(ayer, 0)
            if prom <= 0:
                continue
            cambio = (actual - prom) / prom * 100
            if cambio <= -40 or cambio >= 50:
                salida.append({
                    "Sucursal": suc, "Indicador": etiqueta, "Fecha": f"{NOMBRES_DIA[ayer.weekday()]} {ayer:%d/%m}",
                    "Valor": f"{unidad}{actual:,.0f}", f"Promedio {NOMBRES_DIA[ayer.weekday()].lower()}s": f"{unidad}{prom:,.0f}",
                    "Cambio": f"{cambio:+.0f}%",
                    "Lectura": ("🔻 Muy por debajo de lo normal: revisar si faltó reporte, cierre o hubo fuga de cobro"
                                if cambio < 0 else "🔺 Muy por encima de lo normal: confirmar evento especial o error de captura"),
                })
        return salida

    anomalias = (_comparar(autos, "Vehículos registrados", "") + _comparar(cobro, "Cobrado en la app", "$")
                 + _comparar(fisico, "Ingreso del reporte físico", "$"))

    patrones = []
    for suc in sorted(set(autos) | set(fisico)):
        por_dia = defaultdict(list)
        base = fisico[suc] if fisico[suc] else cobro[suc]
        for f_d, v in base.items():
            por_dia[f_d.weekday()].append(v)
        prom_dia = {d: median(v) for d, v in por_dia.items() if v}  # mediana: un día raro no cambia el patrón
        hora_pico = max(horas[suc].items(), key=lambda x: x[1])[0] if horas[suc] else None
        patrones.append({
            "Sucursal": suc,
            "Día más fuerte": NOMBRES_DIA[max(prom_dia, key=prom_dia.get)] if prom_dia else "—",
            "Día más flojo": NOMBRES_DIA[min(prom_dia, key=prom_dia.get)] if len(prom_dia) > 1 else "—",
            "Hora pico de llegadas": f"{hora_pico:02d}:00–{(hora_pico + 1) % 24:02d}:00" if hora_pico is not None else "—",
            "Vehículos por día (prom.)": round(mean(autos[suc].values()), 1) if autos[suc] else 0,
            "Ticket promedio ($)": round(mean(tickets[suc]), 2) if tickets[suc] else 0.0,
            "Estancia promedio": texto_duracion(int(round(mean(estancias[suc])))) if estancias[suc] else "—",
            "Ingreso diario prom. ($)": round(mean(base.values()), 2) if base else 0.0,
        })

    control = []
    for suc in sorted(pagos_tot.keys() | sin_pago.keys()):
        total = pagos_tot[suc]
        if sin_pago[suc]:
            control.append({"Sucursal": suc, "Señal": "Entregados sin cobro registrado", "Cantidad": sin_pago[suc],
                            "Qué hacer": "Revisar folios: posible fuga de cobro o cortesía sin autorizar"})
        if total >= 10 and ajustes[suc] / total >= 0.10:
            control.append({"Sucursal": suc, "Señal": "Muchos cambios manuales de importe", "Cantidad": ajustes[suc],
                            "Qué hacer": f"{ajustes[suc] / total:.0%} de los cobros tuvieron ajuste: revisar motivos"})
        efectivo = metodo_cnt[suc].get("Efectivo", 0)
        if total >= 20 and efectivo / total >= 0.97:
            control.append({"Sucursal": suc, "Señal": "Casi todo se cobra en efectivo", "Cantidad": efectivo,
                            "Qué hacer": "Promover pago con tarjeta / Point Tap: deja rastro y reduce riesgo de faltantes"})

    sugerencias = []
    for pt in patrones:
        if pt["Día más flojo"] != "—" and pt["Día más fuerte"] != "—":
            sugerencias.append(f"**{pt['Sucursal']}**: el día más fuerte es {pt['Día más fuerte'].lower()} y el más flojo "
                               f"{pt['Día más flojo'].lower()}; ajusta personal y nómina de acuerdo a eso.")
        if pt["Hora pico de llegadas"] != "—":
            sugerencias.append(f"**{pt['Sucursal']}**: la mayoría de los autos llega entre {pt['Hora pico de llegadas']}; "
                               "asegura personal completo en ese horario.")
    return {"anomalias": anomalias, "patrones": patrones, "control": control, "sugerencias": sugerencias,
            "periodo": f"{desde:%d/%m/%Y} al {hoy:%d/%m/%Y}"}


# ---------------------------------------------------------------------
# PRONÓSTICO DE AUTOS POR SUCURSAL
# Aprende de los vehículos registrados (y de los boletos de los reportes físicos) cuántos autos llegan
# cada día de la semana y a qué hora. Se calcula una sola vez cada vez que cambian los datos (memoria
# compartida), así que no hace más lenta la app: solo se consulta en 🧠 Inteligencia Operativa.
# ---------------------------------------------------------------------
SEMANAS_PRONOSTICO = 8


def _firma_datos_pronostico():
    partes = []
    for ruta in [DB_FILE, FISICOS_FILE, EVENTOS_FILE] + list(_archivos_mes()):
        try:
            est_r = ruta.stat()
            partes.append((ruta.name, est_r.st_mtime_ns // 60_000_000_000))  # cambia como máximo una vez por minuto
        except OSError:
            continue
    return tuple(partes)


def _estimar_dia(historia, dia, semanas=SEMANAS_PRONOSTICO):
    """Promedio ponderado del mismo día de la semana en las semanas anteriores (las recientes pesan más)."""
    valores, pesos = [], []
    for k in range(1, semanas + 1):
        v = historia.get(dia - timedelta(weeks=k))
        if v is not None:
            valores.append(v)
            pesos.append(semanas + 1 - k)
    if len(valores) < 2:
        return None, None
    prom = sum(v * w for v, w in zip(valores, pesos)) / sum(pesos)
    var = sum(w * (v - prom) ** 2 for v, w in zip(valores, pesos)) / sum(pesos)
    return prom, var ** 0.5


@st.cache_resource(show_spinner="Aprendiendo de la operación…", max_entries=3)
def calcular_pronostico(firma, hoy_txt):
    """Pronóstico de los próximos 7 días por sucursal + precisión de los últimos 7 días."""
    from collections import defaultdict
    hoy_p = date.fromisoformat(hoy_txt)
    desde = hoy_p - timedelta(weeks=SEMANAS_PRONOSTICO + 2)
    autos = defaultdict(lambda: defaultdict(int))
    horas = defaultdict(lambda: defaultdict(lambda: defaultdict(int)))  # suc -> día semana -> hora -> autos
    for r in cargar_bd(historico=True):
        suc, f = r.get("sucursal"), fecha_op_registro(r)
        if not suc or f is None or not (desde <= f < hoy_p) or r.get("estado") == "Cancelado":
            continue
        autos[suc][f] += 1
        try:
            horas[suc][f.weekday()][datetime.fromisoformat(str(r.get("fecha_entrada_iso"))).hour] += 1
        except (TypeError, ValueError):
            pass
    # Los boletos de los reportes físicos cuentan cuando la app registró menos (sucursal que aún no usa tickets)
    for rf in _leer_lista_json(FISICOS_FILE):
        if rf.get("tipo_reporte") != "ingresos":
            continue
        f = fecha_flexible(rf.get("Fecha"))
        suc = rf.get("Sitio / Unidad")
        if suc and f and desde <= f < hoy_p:
            autos[suc][f] = max(autos[suc][f], _entero_seguro(rf.get("Boletos Cobrados") or rf.get("Total Boletos")))
    eventos_dia = defaultdict(int)
    for e in _leer_lista_json(EVENTOS_FILE):
        if e.get("estado") != "Cancelado":
            fe = fecha_flexible(e.get("fecha"))
            if fe:
                eventos_dia[(e.get("sucursal"), fe)] += _entero_seguro(e.get("vehiculos"))
    dias_cat = {i["sitio"]: dias_que_opera(i.get("dias")) for i in CATALOGO_OFICIAL_23}
    filas, precision = [], []
    for suc in sorted(set(autos) | {s_ for s_, _ in eventos_dia}):
        if suc not in PRECIOS_SUCURSALES:
            continue
        es_salon = suc in SALONES_EVENTOS
        opera = dias_cat.get(suc, set(range(7)))
        # historia completa: días que opera sin registro cuentan como 0 (solo si la sucursal ya tenía movimiento)
        inicio_suc = min(autos[suc]) if autos[suc] else hoy_p
        hist = {}
        d = inicio_suc
        while d < hoy_p:
            if es_salon:
                if autos[suc].get(d) or eventos_dia.get((suc, d)):
                    hist[d] = autos[suc].get(d, 0)
            elif d.weekday() in opera:
                hist[d] = autos[suc].get(d, 0)
            d += timedelta(days=1)
        # tendencia: últimas 4 semanas contra las 4 anteriores (suavizada)
        rec = [v for d_, v in hist.items() if d_ >= hoy_p - timedelta(days=28)]
        ant = [v for d_, v in hist.items() if hoy_p - timedelta(days=56) <= d_ < hoy_p - timedelta(days=28)]
        tendencia = 1.0
        if rec and ant and sum(ant) > 0:
            tendencia = max(0.85, min(1.2, ((sum(rec) / len(rec)) / (sum(ant) / len(ant))) ** 0.5))
        for k in range(0, 7):
            dia = hoy_p + timedelta(days=k)
            programados = eventos_dia.get((suc, dia), 0)
            if es_salon:
                est, desv = (float(programados), 0.0) if programados else (None, None)
            elif dia.weekday() not in opera:
                est, desv = 0.0, 0.0
            else:
                est, desv = _estimar_dia(hist, dia)
                est = est * tendencia if est is not None else None
            reparto = horas[suc][dia.weekday()]
            pico, autos_pico = None, None
            if reparto and est:
                tot_h = sum(reparto.values())
                h_pico = max(range(24), key=lambda h: reparto.get(h, 0) + reparto.get((h + 1) % 24, 0))
                pico = f"{h_pico:02d}:00–{(h_pico + 2) % 24:02d}:00"
                autos_pico = round(est * (reparto.get(h_pico, 0) + reparto.get((h_pico + 1) % 24, 0)) / tot_h)
            filas.append({"sucursal": suc, "fecha": dia, "estimado": None if est is None else round(est),
                          "minimo": None if est is None else max(0, round(est - (desv or 0))),
                          "maximo": None if est is None else round(est + (desv or 0)),
                          "pico": pico, "autos_pico": autos_pico, "salon": es_salon,
                          "semana_pasada": hist.get(dia - timedelta(weeks=1))})
        # precisión: lo que se habría pronosticado los últimos 7 días contra lo que pasó
        if not es_salon:
            for k in range(1, 8):
                dia = hoy_p - timedelta(days=k)
                if dia not in hist:
                    continue
                previo = {d_: v for d_, v in hist.items() if d_ < dia}
                est, _ = _estimar_dia(previo, dia)
                if est is not None and (hist[dia] or est):
                    precision.append((suc, dia, est, hist[dia]))
    return {"filas": filas, "precision": precision}


def _vista_pronostico():
    hoy_p = ahora_mx().date()
    datos_p = calcular_pronostico(_firma_datos_pronostico(), hoy_p.isoformat())
    filas = datos_p["filas"]
    st.caption("La app aprende de las últimas semanas cuántos autos llegan a cada sucursal según el día y la hora "
               "(las semanas recientes pesan más, y considera si la operación va subiendo o bajando). "
               "Salones: usa los vehículos programados de sus eventos. Se actualiza solo con cada día registrado.")
    if not filas:
        st.info("Aún no hay suficiente historia. Con 2 a 3 semanas de registros el pronóstico empieza a funcionar.")
        return
    errores_p = [abs(est - real) / max(real, 1) for _, _, est, real in datos_p["precision"]]
    if errores_p:
        acierto = max(0.0, 100 - 100 * sum(errores_p) / len(errores_p))
        st.metric("Precisión del pronóstico (últimos 7 días)", f"{acierto:.0f}%",
                  help="Qué tan cerca estuvo lo que la app habría pronosticado de lo que realmente llegó. Mejora con más semanas registradas.")
    dias7 = [hoy_p + timedelta(days=k) for k in range(7)]
    etiqueta = lambda d: f"{NOMBRES_DIA[d.weekday()][:3]} {d:%d/%m}"
    tabla = {}
    for f in filas:
        fila_t = tabla.setdefault(f["sucursal"], {"Sucursal": f["sucursal"]})
        fila_t[etiqueta(f["fecha"])] = f["estimado"]
    df_p = pd.DataFrame(list(tabla.values()))
    for d in dias7:
        if etiqueta(d) not in df_p.columns:
            df_p[etiqueta(d)] = None
    df_p = df_p[["Sucursal"] + [etiqueta(d) for d in dias7]]
    total = {"Sucursal": "TOTAL"}
    for d in dias7:
        total[etiqueta(d)] = int(pd.to_numeric(df_p[etiqueta(d)], errors="coerce").fillna(0).sum())
    df_p = pd.concat([df_p, pd.DataFrame([total])], ignore_index=True)
    st.markdown("#### 📈 Autos esperados los próximos 7 días")
    st.dataframe(df_p, use_container_width=True, hide_index=True)
    st.caption("Vacío = sin historia suficiente o salón sin evento programado · 0 = la sucursal no opera ese día.")
    sucs_p = sorted({f["sucursal"] for f in filas})
    suc_sel = st.selectbox("Ver detalle de la sucursal", sucs_p, key="pron_suc")
    det = [f for f in filas if f["sucursal"] == suc_sel]
    st.dataframe(pd.DataFrame([{
        "Día": etiqueta(f["fecha"]), "Autos esperados": f["estimado"],
        "Rango probable": (f"{f['minimo']}–{f['maximo']}" if f["estimado"] is not None else "—"),
        "Hora pico": f["pico"] or "—", "Autos en la hora pico": f["autos_pico"] if f["autos_pico"] is not None else "—",
        "Mismo día semana pasada": f["semana_pasada"] if f["semana_pasada"] is not None else "—",
    } for f in det]), use_container_width=True, hide_index=True)
    pico_max = max((f for f in det if f["autos_pico"]), key=lambda f: f["autos_pico"], default=None)
    if pico_max:
        st.info(f"💡 El momento de más trabajo en {suc_sel} será el {etiqueta(pico_max['fecha'])} entre {pico_max['pico']} "
                f"(~{pico_max['autos_pico']} autos). Asegura personal completo en ese horario.")


# ---------------------------------------------------------------------
# 2) EVENTOS QUE APRENDEN DE LO REAL: programado contra reporte físico, por salón y día de la semana
# ---------------------------------------------------------------------
@st.cache_resource(show_spinner="Comparando eventos programados contra lo real…", max_entries=3)
def aprendizaje_eventos(firma):
    from statistics import mean
    evs = [e for e in complementar_eventos_con_reportes(cargar_eventos())
           if e.get("estado") != "Cancelado" and str(e.get("fuente", "")).startswith("Reporte")]
    por_salon = {}
    for e in evs:
        por_salon.setdefault(e.get("sucursal"), []).append(e)
    resumen, aprendido = [], {}
    for salon, lista in sorted(por_salon.items()):
        reales = [_entero_seguro(e.get("vehiculos")) for e in lista]
        prog = [_entero_seguro(e.get("vehiculos_est")) for e in lista if _entero_seguro(e.get("vehiculos_est"))]
        util = [_flotante_seguro(e.get("utilidad")) if e.get("utilidad", 0) >= 0 else e.get("utilidad", 0) for e in lista]
        prom_real = mean(reales) if reales else 0
        prom_prog = mean(prog) if prog else None
        por_dia = {}
        for e in lista:
            f = fecha_flexible(e.get("fecha"))
            if f:
                por_dia.setdefault(f.weekday(), []).append(_entero_seguro(e.get("vehiculos")))
        aprendido[salon] = {"general": round(prom_real), "por_dia": {d: round(mean(v)) for d, v in por_dia.items() if len(v) >= 2},
                            "n": len(lista)}
        dif = (prom_real - prom_prog) / prom_prog * 100 if prom_prog else None
        resumen.append({
            "Salón": salon, "Eventos con reporte": len(lista),
            "Autos programados (prom.)": round(prom_prog) if prom_prog else None,
            "Autos reales (prom.)": round(prom_real),
            "Diferencia": f"{dif:+.0f}%" if dif is not None else "—",
            "Ingreso real (prom.)": round(mean(_flotante_seguro(e.get("ingreso_total")) for e in lista), 2),
            "Utilidad real (prom.)": round(mean(float(e.get("utilidad") or 0) for e in lista), 2),
            "Mejor día": (NOMBRES_DIA[max(por_dia, key=lambda d: mean(por_dia[d]))].title() if por_dia else "—"),
        })
    resumen.sort(key=lambda r: -r["Utilidad real (prom.)"])
    return {"resumen": resumen, "aprendido": aprendido}


def autos_aprendidos_salon(salon, fecha_ev):
    """Autos que de verdad suelen llegar a ese salón (ese día de la semana si hay historia; si no, su promedio)."""
    try:
        ap = aprendizaje_eventos(_firma_datos_pronostico())["aprendido"].get(salon)
    except Exception:
        return None
    if not ap or ap.get("n", 0) < 2:
        return None
    return ap["por_dia"].get(fecha_ev.weekday(), ap["general"]) if fecha_ev else ap["general"]


def _vista_eventos_aprendizaje():
    datos_e = aprendizaje_eventos(_firma_datos_pronostico())
    st.caption("Compara lo programado de cada evento contra su reporte físico (lo que realmente llegó y dejó). "
               "Lo aprendido se usa solo al cargar la semana: la columna «Vehículos prog.» propone los autos que de verdad suelen llegar.")
    if not datos_e["resumen"]:
        st.info("Aún no hay eventos con reporte físico. Cuando los supervisores suban los reportes de los eventos, aquí verás lo aprendido.")
        return
    df_e = pd.DataFrame(datos_e["resumen"])
    st.markdown("#### 🎉 Salones: programado contra real (ordenados por utilidad)")
    st.dataframe(df_e, use_container_width=True, hide_index=True, column_config=formato_columnas_df(df_e))
    for r in datos_e["resumen"]:
        if r["Autos programados (prom.)"] and r["Eventos con reporte"] >= 2:
            dif = (r["Autos reales (prom.)"] - r["Autos programados (prom.)"]) / max(1, r["Autos programados (prom.)"]) * 100
            if abs(dif) >= 15:
                st.warning(f"**{r['Salón']}**: se programan ~{r['Autos programados (prom.)']} autos pero llegan ~{r['Autos reales (prom.)']} "
                           f"({dif:+.0f}%). Ajusta lo programado y el personal.")
    perdida = [r for r in datos_e["resumen"] if r["Utilidad real (prom.)"] < 0]
    if perdida:
        st.error("🚨 Salones que en promedio dejan pérdida: " + ", ".join(r["Salón"] for r in perdida) + ". Revisa costo del evento o nómina.")


# ---------------------------------------------------------------------
# 3) ALERTAS POR PERSONA: cada quien contra el resto de su sucursal (o de toda la operación)
# ---------------------------------------------------------------------
@st.cache_resource(show_spinner="Revisando el comportamiento de cada persona…", max_entries=3)
def alertas_por_persona(firma, hoy_txt, dias=28):
    from collections import defaultdict
    hoy_a = date.fromisoformat(hoy_txt)
    desde = hoy_a - timedelta(days=dias)
    pers = defaultdict(lambda: {"sucursales": set(), "cobros": 0, "efectivo": 0, "ajustes": 0, "importe": 0.0, "calculado": 0.0,
                                "sin_cobro": 0, "cancelados": 0, "registros": 0})
    suc_tot = defaultdict(lambda: {"cobros": 0, "efectivo": 0, "ajustes": 0, "importe": 0.0})
    for r in cargar_bd(historico=True):
        f = fecha_op_registro(r)
        if f is None or f < desde:
            continue
        suc = r.get("sucursal")
        if r.get("registrado_por"):
            p_ = pers[r["registrado_por"]]
            p_["registros"] += 1
            p_["sucursales"].add(suc)
        if r.get("estado") == "Cancelado" and (r.get("actualizado_por") or r.get("registrado_por")):
            pers[r.get("actualizado_por") or r.get("registrado_por")]["cancelados"] += 1
        pagados = [pg for pg in (r.get("pagos") or []) if pg.get("estado", "Pagado") == "Pagado"]
        if r.get("estado") == "Entregado" and not pagados and float(r.get("tarifa") or 0) > 0 and r.get("entregado_por"):
            pers[r["entregado_por"]]["sin_cobro"] += 1
        for pg in pagados:
            quien = pg.get("usuario") or r.get("entregado_por")
            if not quien:
                continue
            p_ = pers[quien]
            p_["sucursales"].add(suc)
            p_["cobros"] += 1
            p_["efectivo"] += 1 if pg.get("metodo") == "Efectivo" else 0
            p_["ajustes"] += 1 if pg.get("ajuste_manual") else 0
            p_["importe"] += _flotante_seguro(pg.get("importe"))
            p_["calculado"] += _flotante_seguro(pg.get("importe_calculado") or pg.get("importe"))
            t_ = suc_tot[suc]
            t_["cobros"] += 1
            t_["efectivo"] += 1 if pg.get("metodo") == "Efectivo" else 0
            t_["ajustes"] += 1 if pg.get("ajuste_manual") else 0
            t_["importe"] += _flotante_seguro(pg.get("importe"))
    alertas, tabla = [], []
    for quien, p_ in pers.items():
        sucs = sorted(x for x in p_["sucursales"] if x)
        # referencia: lo normal en sus sucursales sin contarlo a él/ella
        ref = {"cobros": 0, "efectivo": 0, "ajustes": 0, "importe": 0.0}
        for s_ in sucs:
            for k in ref:
                ref[k] += suc_tot[s_][k]
        for k in ("cobros", "efectivo", "ajustes", "importe"):
            ref[k] -= p_[k]
        pct_ef = p_["efectivo"] / p_["cobros"] * 100 if p_["cobros"] else 0
        pct_aj = p_["ajustes"] / p_["cobros"] * 100 if p_["cobros"] else 0
        ticket = p_["importe"] / p_["cobros"] if p_["cobros"] else 0
        ref_ef = ref["efectivo"] / ref["cobros"] * 100 if ref["cobros"] else None
        ref_aj = ref["ajustes"] / ref["cobros"] * 100 if ref["cobros"] else None
        ref_ticket = ref["importe"] / ref["cobros"] if ref["cobros"] else None
        rebajado = p_["calculado"] - p_["importe"]
        tabla.append({"Persona": quien, "Sucursal(es)": ", ".join(sucs), "Autos registrados": p_["registros"], "Cobros": p_["cobros"],
                      "% efectivo": round(pct_ef), "% ajustes": round(pct_aj), "Ticket prom.": round(ticket, 2),
                      "Ticket prom. de sus compañeros": round(ref_ticket, 2) if ref_ticket else None,
                      "Rebajado en ajustes": round(max(0.0, rebajado), 2), "Entregas sin cobro": p_["sin_cobro"], "Cancelados": p_["cancelados"]})
        def alerta(nivel, que, detalle, revisar):
            alertas.append({"Nivel": nivel, "Persona": quien, "Sucursal(es)": ", ".join(sucs), "Señal": que, "Detalle": detalle, "Qué revisar": revisar})
        if p_["sin_cobro"]:
            alerta("🔴 Alta", "Entregó autos sin cobro", f"{p_['sin_cobro']} entrega(s) sin cobro registrado",
                   "Folios entregados sin pago en 📋 Vehículos registrados (cuadre de caja)")
        if p_["cobros"] >= 10 and p_["ajustes"] >= 3 and (ref_aj is None or pct_aj > max(2 * ref_aj, 10)):
            alerta("🔴 Alta" if rebajado > 0 else "🟠 Media", "Muchos cambios manuales de importe",
                   f"{pct_aj:.0f}% de sus cobros con ajuste (compañeros: {ref_aj or 0:.0f}%) · rebajado ${max(0.0, rebajado):,.2f}",
                   "Motivos de los ajustes en la bitácora de auditoría")
        if p_["cobros"] >= 15 and ref_ticket and ticket < 0.8 * ref_ticket:
            alerta("🟠 Media", "Cobra menos que sus compañeros", f"Ticket promedio ${ticket:,.2f} contra ${ref_ticket:,.2f}",
                   "Tarifas aplicadas, modalidad (fija/tiempo/promoción) y tiempos de estancia")
        if p_["cobros"] >= 20 and ref_ef is not None and pct_ef >= 95 and pct_ef - ref_ef >= 25:
            alerta("🟡 Baja", "Casi todo en efectivo", f"{pct_ef:.0f}% en efectivo (compañeros: {ref_ef:.0f}%)",
                   "Cuadre de caja diario: el efectivo es donde ocurren los faltantes")
        if p_["cancelados"] >= 3 and p_["cancelados"] >= 0.05 * max(1, p_["registros"]):
            alerta("🟠 Media", "Muchos registros cancelados", f"{p_['cancelados']} cancelados de {p_['registros']} registrados",
                   "Motivo de cada cancelación (un auto cancelado puede ser un cobro que no entró)")
    orden = {"🔴 Alta": 0, "🟠 Media": 1, "🟡 Baja": 2}
    alertas.sort(key=lambda a: orden.get(a["Nivel"], 9))
    tabla.sort(key=lambda t: -t["Cobros"])
    return {"alertas": alertas, "tabla": tabla, "dias": dias}


def _vista_alertas_persona():
    hoy_a = ahora_mx().date()
    dias_a = st.radio("Periodo", [7, 14, 28], index=2, horizontal=True, format_func=lambda d: f"Últimos {d} días", key="alertas_dias")
    datos_a = alertas_por_persona(_firma_datos_pronostico(), hoy_a.isoformat(), int(dias_a))
    st.caption("Cada persona se compara contra sus compañeros de la misma sucursal. Una alerta no es una acusación: "
               "es una señal para revisar los folios con el supervisor.")
    if datos_a["alertas"]:
        st.markdown(f"#### 🚨 {len(datos_a['alertas'])} alerta(s)")
        st.dataframe(pd.DataFrame(datos_a["alertas"]), use_container_width=True, hide_index=True)
        if st.button("📤 Registrar estas alertas en la bitácora de auditoría", key="alertas_bitacora"):
            for a in datos_a["alertas"]:
                guardar_evento_auditoria("ALERTA POR PERSONA", f"{a['Nivel']} · {a['Persona']} · {a['Señal']} · {a['Detalle']}")
            st.success("Alertas registradas.")
    else:
        st.success("✅ Sin alertas: nadie se sale de lo normal en el periodo.")
    if datos_a["tabla"]:
        with st.expander("👤 Indicadores de cada persona"):
            df_t = pd.DataFrame(datos_a["tabla"])
            st.dataframe(df_t, use_container_width=True, hide_index=True, column_config=formato_columnas_df(df_t))


@_registrar_fallas
def _seccion_intel():
    global alertas, clave, col, e, kpis, recomendaciones, resumen, titulo, valor
    globals()["_CONTADOR_LLAVES"] = 1000  # llaves estables entre recargas completas y de sección
    with tab_intel:
        encabezado_institucional("INTELIGENCIA OPERATIVA", "ANÁLISIS CONTINUO", "El sistema se observa a sí mismo: indicadores, alertas, recomendaciones y evolución")
        vista_intel = st.radio("Vista", ["📈 Pronóstico de autos", "🎉 Eventos: programado vs real", "👤 Alertas por persona",
                                         "🧠 Análisis y alertas"], horizontal=True, key="intel_vista", label_visibility="collapsed")
        if vista_intel.startswith("📈"):
            _vista_pronostico()
            return
        if vista_intel.startswith("🎉"):
            _vista_eventos_aprendizaje()
            return
        if vista_intel.startswith("👤"):
            _vista_alertas_persona()
            return
        st.caption(
            "Panel ejecutivo que se actualiza automáticamente con cada operación registrada: "
            "indicadores, alertas tempranas, resumen del día y recomendaciones generadas a partir "
            "de la información real del sistema."
        )
        registros_intel = vehiculos_visibles(st.session_state.vehiculos)
        if not registros_intel:
            st.info("El análisis se activará automáticamente al registrar los primeros vehículos.")
        else:
            kpis, alertas, resumen, recomendaciones = analisis_inteligente(registros_intel)
            col_k1, col_k2, col_k3, col_k4 = st.columns(4)
            for col, (titulo, valor) in zip((col_k1, col_k2, col_k3, col_k4), kpis):
                col.metric(titulo, valor)
            st.markdown("**Resumen ejecutivo del día**")
            st.info(resumen)
            st.markdown("**Alertas automáticas**")
            if alertas:
                st.dataframe(pd.DataFrame(alertas), use_container_width=True, hide_index=True)
                if st.button("📤 Registrar alertas en la bitácora de auditoría", key="btn_intel_bitacora", use_container_width=True):
                    for alerta in alertas:
                        guardar_evento_auditoria("Inteligencia Operativa", f"{alerta['tipo']}: {alerta['detalle']}")
                    st.success("Alertas registradas en la bitácora de auditoría.")
            else:
                st.success("Sin alertas: no hay estancias críticas, placas duplicadas ni cobros pendientes detectados.")
            st.markdown("**Recomendaciones automáticas**")
            for recomendacion in recomendaciones:
                st.markdown(f"- {recomendacion}")

            st.markdown("**Evolución del sistema (aprendizaje continuo)**")
            notas_evolucion = evolucion_aprendizaje(registros_intel)
            if notas_evolucion:
                for nota in notas_evolucion[:5]:
                    st.markdown(f"- **{nota['fecha']}** · {nota['vehiculos_totales']} vehículos: {nota['observaciones']}")
            else:
                st.caption("Cada 25 vehículos registrados, el sistema documentará aquí lo que ha aprendido de la operación.")

        st.divider()
        st.markdown("### 📚 Aprendizaje de la operación")
        semanas_ap = st.radio("Historia a analizar", [4, 8, 12], index=1, format_func=lambda w: f"{w} semanas",
                              horizontal=True, key="ap_semanas")
        reportes_ap = _leer_lista_json(FISICOS_FILE)
        if not es_global:
            reportes_ap = [r for r in reportes_ap if r.get("Sitio / Unidad") == st.session_state.sucursal_asignada]
        ap = aprendizaje_operativo(vehiculos_visibles(st.session_state.vehiculos), reportes_ap, ahora_mx().date(), semanas_ap)
        st.caption(f"La app compara la operación real ({ap['periodo']}) consigo misma: aprende qué es normal en cada sucursal "
                   "y avisa cuando algo se sale de lo normal. Entre más días registrados, más precisa.")
        st.markdown("**🚨 Fuera de lo normal (último día cerrado)**")
        if ap["anomalias"]:
            st.dataframe(pd.DataFrame(ap["anomalias"]), use_container_width=True, hide_index=True)
        else:
            st.success("Nada fuera de lo normal en el último día cerrado (o aún no hay 3 semanas de historia para comparar).")
        st.markdown("**🛡️ Señales de control**")
        if ap["control"]:
            st.dataframe(pd.DataFrame(ap["control"]), use_container_width=True, hide_index=True)
        else:
            st.success("Sin señales de riesgo: no hay entregas sin cobro, exceso de ajustes ni dependencia total del efectivo.")
        st.markdown("**📈 Lo que la app aprendió de cada sucursal**")
        if ap["patrones"]:
            df_ap = pd.DataFrame(ap["patrones"])
            st.dataframe(df_ap, use_container_width=True, hide_index=True, column_config=formato_columnas_df(df_ap))
        else:
            st.caption("Aún no hay suficiente información registrada.")
        if ap["sugerencias"]:
            with st.expander("💡 Sugerencias para operar mejor"):
                for sug in ap["sugerencias"][:30]:
                    st.markdown(f"- {sug}")
        if ap["anomalias"] or ap["control"]:
            if st.button("📤 Registrar estos avisos en la bitácora de auditoría", key="ap_bitacora"):
                for a in ap["anomalias"]:
                    guardar_evento_auditoria("APRENDIZAJE · FUERA DE LO NORMAL", f"{a['Sucursal']} · {a['Indicador']} · {a['Fecha']} · {a['Cambio']}")
                for c in ap["control"]:
                    guardar_evento_auditoria("APRENDIZAJE · SEÑAL DE CONTROL", f"{c['Sucursal']} · {c['Señal']} · {c['Cantidad']}")
                st.success("Avisos registrados en la bitácora.")
        st.divider()

        st.markdown("**Salud de la impresión térmica (RawBT)**")
        eventos_imp = cargar_registro_impresion()
        fallos_imp = [e for e in eventos_imp if e.get("resultado") == "FALLO"]
        col_i1, col_i2, col_i3 = st.columns(3)
        col_i1.metric("Intentos registrados", len(eventos_imp))
        col_i2.metric("Fallos registrados", len(fallos_imp))
        col_i3.metric("Último evento", eventos_imp[0]["fecha_hora"] if eventos_imp else "—")
        if fallos_imp:
            por_etapa = {}
            for e in fallos_imp:
                clave = e.get("etapa", "OTRO")
                por_etapa[clave] = por_etapa.get(clave, 0) + 1
            detalle_etapas = " · ".join(
                f"{ETAPAS_IMPRESION.get(k, k)}: {v}" for k, v in por_etapa.items()
            )
            st.warning("Fallos de impresión detectados → " + detalle_etapas)
            st.dataframe(pd.DataFrame(fallos_imp[:10]), use_container_width=True, hide_index=True)
        elif eventos_imp:
            st.success("La impresión térmica opera sin fallos registrados.")
        else:
            st.caption("Aún no hay eventos de impresión: ejecuta la prueba de impresión en 🧪 Pruebas Operativas o en 🖨️ Re-Impresión Térmica.")

if _SECCION == "intel" and "intel" in _TABS:
    _seccion_intel()


