HOJAS_SUP_ESTADO_FILE = DATA_DIR / "hojas_supervisores_estado.json"
SUCURSAL_GENERAL_SUP = "GENERAL DE SUPERVISIÓN"
MINUTOS_SINCRONIZAR_HOJAS = 30


def id_hoja_google(texto):
    m = re.search(r"/spreadsheets/d/([A-Za-z0-9_-]{20,})", str(texto or ""))
    if m:
        return m.group(1)
    t = str(texto or "").strip()
    return t if re.fullmatch(r"[A-Za-z0-9_-]{30,}", t) else ""


def config_hojas_supervisores():
    return dict(cargar_sucursales_config().get("hojas_supervisores", {}) or {})


def guardar_config_hoja_supervisor(clave, url, sucursal_defecto=""):
    cfg = cargar_sucursales_config()
    hojas = dict(cfg.get("hojas_supervisores", {}) or {})
    if url:
        hojas[clave] = {"url": str(url).strip(), "sucursal": sucursal_defecto or ""}
    else:
        hojas.pop(clave, None)
    cfg["hojas_supervisores"] = hojas
    guardar_sucursales_config(cfg)


def _estado_hojas():
    try:
        datos = json.loads(HOJAS_SUP_ESTADO_FILE.read_text(encoding="utf-8")) if HOJAS_SUP_ESTADO_FILE.exists() else {}
        return datos if isinstance(datos, dict) else {}
    except (OSError, ValueError):
        return {}


def descargar_hoja_google(id_hoja):
    """Descarga la hoja como Excel. Con la cuenta de servicio de Google (GOOGLE_SERVICE_ACCOUNT_JSON) la hoja puede
    seguir privada (se comparte solo con ese correo); sin ella, debe estar como «Cualquier persona con el enlace»."""
    if _info_cuenta_servicio():
        resp = _google_api("GET", f"https://www.googleapis.com/drive/v3/files/{id_hoja}/export",
                           params={"mimeType": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"})
        if resp.content.startswith(b"PK"):
            return resp.content
    import urllib.request
    import urllib.error
    url = f"https://docs.google.com/spreadsheets/d/{id_hoja}/export?format=xlsx"
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (ClubPark)"})
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            datos = resp.read(25 * 1024 * 1024)
    except urllib.error.HTTPError as exc:
        if exc.code in (401, 403, 404):
            raise RuntimeError("Google no dejó leer la hoja: compártela como «Cualquier persona con el enlace · Lector».")
        raise RuntimeError(f"Google respondió con error {exc.code}.")
    except Exception as exc:
        raise RuntimeError(f"No se pudo conectar con Google: {exc}")
    if not datos.startswith(b"PK"):
        raise RuntimeError("La hoja es privada: en Google Sheets toca Compartir › Acceso general › «Cualquier persona con el enlace» › Lector.")
    return datos


def sincronizar_hoja_supervisor(clave, forzar=False):
    """Lee la hoja de Google del supervisor y reemplaza los gastos que venían de ella (así los cambios y borrados
    en la hoja también se reflejan). La fecha de cada gasto: la de su renglón, la del título del bloque o,
    si no trae, el día en que la app lo vio por primera vez (y se conserva en las siguientes lecturas)."""
    cfg = config_hojas_supervisores().get(clave) or {}
    id_hoja = id_hoja_google(cfg.get("url"))
    estado_todo = _estado_hojas()
    estado = dict(estado_todo.get(clave) or {})
    if not id_hoja:
        return estado
    ahora = ahora_mx()
    ultima = estado.get("ultima_lectura")
    if not forzar and ultima and estado.get("id_hoja") == id_hoja:
        try:
            if (ahora.replace(tzinfo=None) - datetime.fromisoformat(ultima).replace(tzinfo=None)) < timedelta(minutes=MINUTOS_SINCRONIZAR_HOJAS):
                return estado
        except ValueError:
            pass
    estado.update({"ultima_lectura": ahora.isoformat(timespec="seconds"), "id_hoja": id_hoja})
    try:
        datos = descargar_hoja_google(id_hoja)
        libro = pd.read_excel(io.BytesIO(datos), sheet_name=None, header=None)
        tablas = [(n, df) for n, df in libro.items() if df is not None and not df.dropna(how="all").empty]
        # Formato semanal: cada pestaña puede ser una semana distinta (se guarda cada una)
        semanales = [(n, leer_hoja_semanal_supervisor([(n, df)], cfg.get("alias"))) for n, df in tablas]
        semanales = [(n, sm) for n, sm in semanales if sm]
        if semanales:
            filas, avisos, etiquetas_sem = [], [], []
            conflicto = False
            for n_tab, semanal in semanales:
                res_g = _guardar_semana_hoja(clave, semanal)
                tit = f"{semanal['semana_ini']:%d/%m} al {semanal['semana_fin']:%d/%m/%Y}" if semanal.get("semana_ini") else ""
                if res_g == "conflicto":
                    conflicto = True
                    avisos.append(f"🔴 Pestaña «{n_tab}»: tiene números nuevos pero el título sigue diciendo la semana del {tit}, "
                                  "que ya estaba guardada. NO se guardó para no encimar semanas: actualiza el título «SEMANA DEL … AL …».")
                    continue
                if res_g == "titulo_viejo":
                    avisos.append(f"⚠️ Pestaña «{n_tab}»: el título dice la semana del {tit}, que ya pasó. Si la hoja trae otra semana, "
                                  "actualiza el título «SEMANA DEL … AL …».")
                fin_sem = semanal.get("semana_fin")
                filas += [{"Fecha": s_g.get("fecha") or fin_sem, "Sucursal": sucursal_en_concepto(s_g["concepto"]),
                           "Categoría": categoria_gasto_de("", s_g["concepto"]), "Concepto": s_g["concepto"], "Importe": s_g["importe"],
                           "_hoja": n_tab, "_bloque": str(semanal.get("semana_ini") or "")} for s_g in semanal["supervision"]]
                avisos += list(semanal.get("revision") or [])
                if semanal.get("sin_reconocer"):
                    avisos.append("Unidades sin reconocer: " + ", ".join(semanal["sin_reconocer"]))
                if semanal.get("semana_ini"):
                    etiquetas_sem.append(f"{semanal['semana_ini']:%d/%m/%Y} al {semanal['semana_fin']:%d/%m/%Y}")
            estado["semana"] = ", ".join(etiquetas_sem)
            if conflicto:
                raise RuntimeError(" ".join(a for a in avisos if a.startswith("🔴")))
        else:
            filas, avisos, _ = leer_gastos_de_tabla(None, None, None, tablas=tablas, solo_bloques_gasto=True)
        vistas = dict(estado.get("primera_vez") or {})
        hoy_iso = ahora.date().isoformat()
        repetidas, nuevos = {}, []
        suc_def = cfg.get("sucursal") or ""
        for f in filas:
            base = f"{f.get('_hoja', '')}|{f.get('_bloque', '')}|{_sin_acentos(f['Concepto'])}|{f['Importe']:.2f}"
            repetidas[base] = repetidas.get(base, 0) + 1
            huella = hashlib.md5(f"{base}|{repetidas[base]}".encode("utf-8")).hexdigest()[:16]
            vistas.setdefault(huella, hoy_iso)
            fecha_g = f.get("Fecha") or fecha_de_celda(vistas[huella])
            suc_g = f.get("Sucursal") or (suc_def if suc_def in PRECIOS_SUCURSALES else "") or SUCURSAL_GENERAL_SUP
            nuevos.append({
                "id": f"GS{huella.upper()}", "fecha": str(fecha_g), "sucursal": suc_g, "supervisor": clave,
                "categoria": f["Categoría"], "concepto": f["Concepto"], "importe": float(f["Importe"]),
                "registrado_por": f"Hoja de {SUPERVISORES_NOMBRE.get(clave, clave)}", "registrado_en": ahora.strftime("%Y-%m-%d %H:%M:%S"),
                "origen": "Hoja de Google", "fuente_id": id_hoja, "huella": huella,
                "pestana": f.get("_hoja", ""), "bloque": f.get("_bloque", ""),
            })
        vigentes = {g["huella"] for g in nuevos}
        estado["primera_vez"] = {h: d for h, d in vistas.items() if h in vigentes}
        actualizar_lista_json(GASTOS_FILE_RF, lambda lista: nuevos + [
            g for g in lista if not (g.get("origen") == "Hoja de Google" and g.get("supervisor") == clave)])
        estado.update({"error": "", "gastos": len(nuevos), "total": round(sum(g["importe"] for g in nuevos), 2),
                       "avisos": avisos[:5], "ultima_exitosa": ahora.isoformat(timespec="seconds")})
    except Exception as exc:
        estado["error"] = str(exc)
    estado_todo = _estado_hojas()
    estado_todo[clave] = estado
    try:
        _escribir_json_seguro(HOJAS_SUP_ESTADO_FILE, estado_todo)
    except OSError:
        pass
    return estado


def sincronizar_hojas_supervisores(forzar=False, claves=None):
    resultados = {}
    for clave in (claves or list(config_hojas_supervisores())):
        if clave in SUPERVISORES_NOMBRE:
            resultados[clave] = sincronizar_hoja_supervisor(clave, forzar=forzar)
    return resultados


