HOJAS_SUP_DATOS_FILE = DATA_DIR / "hojas_supervisores_datos.json"
_DIAS_HOJA = {"LUNES": 0, "MARTES": 1, "MIERCOLES": 2, "JUEVES": 3, "VIERNES": 4, "SABADO": 5, "DOMINGO": 6}
# Cómo se escriben las unidades en las hojas de los supervisores → sucursal del catálogo
ALIAS_UNIDADES_HOJA = {
    "PAMPAS": "PAMPAS INSURGENTES", "SUSHI ITTO": "SUSHITTO", "SUSHIITTO": "SUSHITTO", "CARAJILLO": "CARAJILLO POLANCO",
    "BENINGANS": "BENINGAN´S", "ROMAS": "ROMANCE PALACE", "ROMANCE": "ROMANCE PALACE",
    "J TLALPAN": "JUNGLA TLALPAN", "J DIVISION": "JUNGLA DIVISIÓN", "J PICACHO": "JUNGLA PICACHO", "J EMPRESA": "JUNGLA EMPRESA",
    "SIPILY": "SIPIRILY COAPA", "SIPIRYLI": "SIPIRILY COAPA", "SIPIRILY": "SIPIRILY COAPA",
    "M SATELITE": "MAROMETA SATÉLITE", "M MARINA": "MAROMETA MARINA", "MARINA": "MAROMETA MARINA", "SATELITE": "MAROMETA SATÉLITE",
    "CLINICA": "CLÍNICA AZURA", "DURANGO": "SANATORIO DURANGO", "S AZURA": "CLÍNICA AZURA", "SAZURA": "CLÍNICA AZURA", "AZURA": "CLÍNICA AZURA", "SUMO STA": "SUMO STA. MONICA", "CHEGARAY": "SUMO ECHEGARAY", "ECHEGARAY": "SUMO ECHEGARAY",
    "E BNI": "E-BNI", "EBNI": "E-BNI", "CHURRASCA": "CHURRASQUERIA", "CHURRAS": "CHURRASQUERIA", "SANATORIO": "SANATORIO DURANGO",
}


def sucursal_de_unidad_hoja(texto, alias_extra=None):
    clave = clave_nombre_sucursal(texto)
    if not clave:
        return None
    for k, v in (alias_extra or {}).items():
        if clave_nombre_sucursal(k) == clave and v in PRECIOS_SUCURSALES:
            return v
    destino = ALIAS_UNIDADES_HOJA.get(clave) or ALIAS_UNIDADES_HOJA.get(clave.replace(" ", ""))
    if destino:
        return sucursal_igual(destino) or (destino if destino in PRECIOS_SUCURSALES else None)
    return sucursal_de_texto(texto)


def semana_de_titulo(texto, hoy=None, con_texto=False):
    """«SEMANA DEL 19 DE octubre AL 25de octubre» o «19 de octubre al 25 de octubre» → (lunes, domingo).
    Si la hoja trae varios títulos (p. ej. uno viejo que no se borró), se queda con la semana más reciente."""
    hoy = hoy or ahora_mx().date()
    t = _sin_acentos(texto)
    meses = dict(_MESES_ABREV_GASTO)
    meses.update({k: v for k, v in _MESES_TXT.items()})
    mes_de = lambda txt: meses.get(txt or "") or meses.get((txt or "")[:3])
    candidatos = []
    patrones = [r"SEMANA\s+DEL?\s+(\d{1,2})\s*(?:DE\s*)?([A-Z]+)?\s*(?:AL|A)\s*(\d{1,2})\s*(?:DE\s*)?([A-Z]+)?",
                r"\b(\d{1,2})\s*DE\s+([A-Z]{3,})\s+AL\s*(\d{1,2})\s*(?:DE\s*)?([A-Z]+)?"]
    for patron in patrones:
        for m in re.finditer(patron, t):
            d1, d2 = int(m.group(1)), int(m.group(3))
            mes2 = mes_de(m.group(4)) or mes_de(m.group(2)) or hoy.month
            mes1 = mes_de(m.group(2)) or (mes2 if d1 <= d2 else (mes2 - 2) % 12 + 1)
            anio2 = hoy.year - (1 if mes2 > hoy.month + 1 else 0)
            anio1 = anio2 - 1 if mes1 > mes2 else anio2
            try:
                inicio = date(anio1, mes1, d1)
            except ValueError:
                continue
            if inicio <= hoy + timedelta(days=7):
                candidatos.append((inicio, m.group(0).strip()))
    if not candidatos:
        return None
    inicio, texto_m = max(candidatos)
    lunes = inicio - timedelta(days=inicio.weekday())
    return (lunes, lunes + timedelta(days=6), texto_m) if con_texto else (lunes, lunes + timedelta(days=6))


def _numero_con_signo(v):
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return 0.0 if (isinstance(v, float) and math.isnan(v)) else float(v)
    t = str(v or "").strip().replace("\\", "")
    negativo = t.startswith("-") or (t.startswith("(") and t.endswith(")"))
    return -importe_de_celda(t) if negativo else importe_de_celda(t)


def leer_hoja_semanal_supervisor(tablas, alias_extra=None):
    """Lee el formato semanal del supervisor. Devuelve dict o None si la hoja no tiene ese formato."""
    datos = {"autos": [], "gastos_dia": [], "resumen": [], "supervision": [], "totales": {}, "sin_reconocer": [], "grupos": {},
             "revision": [], "semana_ini": None, "semana_fin": None, "titulo_semana": ""}
    encontrado = False
    for nombre_hoja, df in tablas:
        df = df.dropna(how="all").reset_index(drop=True)
        renglones = [["" if (v is None or (isinstance(v, float) and math.isnan(v))) else v for v in r]
                     for r in df.itertuples(index=False)]
        texto_todo = " ".join(str(v) for r in renglones for v in r if isinstance(v, str))
        semana = semana_de_titulo(texto_todo, con_texto=True)
        if semana and not datos["semana_ini"]:
            datos["semana_ini"], datos["semana_fin"], datos["titulo_semana"] = semana
        cols_dia, modo, cols_res, grupo, por_etiqueta = {}, None, {}, 1, None
        for r in renglones:
            norm = [_sin_acentos(v).strip() if isinstance(v, str) else "" for v in r]
            dias_fila = {i: _DIAS_HOJA[n] for i, n in enumerate(norm) if n in _DIAS_HOJA}
            unido = " ".join(n for n in norm if n)
            if len(dias_fila) >= 5:
                cols_dia, modo, encontrado = dias_fila, "autos", True
                continue
            if "UNIDAD" in norm and any(n.startswith("VEHICULO") for n in norm):
                cols_res = {}
                for i, n in enumerate(norm):
                    if n.startswith("VEHICULO"):
                        cols_res["vehiculos"] = i
                    elif n.startswith("INGRESO"):
                        cols_res["ingreso"] = i
                    elif n.startswith("GASTO"):
                        cols_res["gastos"] = i
                    elif n.startswith("UTILIDAD"):
                        cols_res["utilidad"] = i
                modo, encontrado = "resumen", True
                continue
            if "GASTO" in unido and ("UNIDAD" in unido or "DEL DIA" in unido) and "SUPERVIS" not in unido and not any(isinstance(v, (int, float)) and not isinstance(v, bool) for v in r):
                modo, encontrado = "gastos_dia", True
                continue
            if "GASTO" in unido and "SUPERVIS" in unido:
                modo, encontrado = "supervision", True
                continue
            if norm and norm[0].startswith("TOTAL DE VEHICULO"):
                numeros = [v for v in r[1:] if _es_numero_celda(v)]
                if numeros:
                    datos["totales"]["total_vehiculos"] = _numero_con_signo(numeros[0])
                continue
            if norm and norm[0] in ("INGRESO BRUTO", "GASTOS OPERATIVOS", "INGRESO SEMANAL"):
                numeros = [v for v in r[1:] if _es_numero_celda(v)]
                if numeros:
                    datos["totales"][norm[0].lower().replace(" ", "_")] = _numero_con_signo(numeros[0])
                continue
            unidad = str(r[0]).strip() if r and isinstance(r[0], str) else ""
            if modo in ("autos", "gastos_dia") and unidad and cols_dia:
                suc = sucursal_de_unidad_hoja(unidad, alias_extra)
                if not suc and unidad not in datos["sin_reconocer"]:
                    datos["sin_reconocer"].append(unidad)
                for i, wd in cols_dia.items():
                    if i < len(r) and _es_numero_celda(r[i]):
                        datos[modo].append({"unidad": unidad, "sucursal": suc, "dia": wd, "valor": _numero_con_signo(r[i])})
            elif modo == "supervision":
                textos = [str(v).strip() for v in r if isinstance(v, str) and str(v).strip()]
                numeros = [v for v in r if _es_numero_celda(v)]
                if any("TOTAL" in _sin_acentos(t) for t in textos):
                    if numeros:
                        datos["totales"]["supervision_declarado"] = importe_de_celda(numeros[-1])
                    modo = None
                    continue
                if not textos and numeros and datos["supervision"]:   # renglón suelto con el total (sin la palabra TOTAL)
                    datos["totales"]["supervision_declarado"] = importe_de_celda(numeros[-1])
                    modo = None
                    continue
                if textos and numeros:
                    concepto = max(textos, key=len)
                    por_dia = {wd: importe_de_celda(r[i]) for i, wd in cols_dia.items()
                               if i < len(r) and _es_numero_celda(r[i]) and importe_de_celda(r[i]) > 0}
                    if por_dia:   # gasto anotado día por día (lunes…domingo): uno por día, con su fecha
                        for wd, imp in sorted(por_dia.items()):
                            datos["supervision"].append({"concepto": concepto, "importe": imp, "fecha": None, "dia": wd})
                    elif importe_de_celda(numeros[-1]) > 0:
                        datos["supervision"].append({"concepto": concepto, "importe": importe_de_celda(numeros[-1]),
                                                     "fecha": fecha_en_texto(concepto)})
            elif modo == "resumen" and cols_res:
                if not unidad:
                    etiqueta = " ".join(str(v).strip() for v in r if isinstance(v, str) and str(v).strip())
                    if "ENTREGA" in _sin_acentos(etiqueta):   # «ENTREGA DE VICTOR A JESÚS»: lo que sigue es otro bloque
                        if datos["resumen"]:
                            grupo += 1
                        datos["grupos"][grupo] = etiqueta.strip()
                        por_etiqueta = grupo
                    continue
                vals = {k: (r[i] if i < len(r) else "") for k, i in cols_res.items()}
                firmar = _numero_con_signo
                suc = sucursal_de_unidad_hoja(unidad, alias_extra)
                if not suc and unidad not in datos["sin_reconocer"]:
                    datos["sin_reconocer"].append(unidad)
                num_fila = next((v for v in r[max(cols_res.values()) + 1:] if _es_numero_celda(v)), None)
                if (num_fila is not None and importe_de_celda(num_fila) == 1 and datos["resumen"]
                        and datos["resumen"][-1]["grupo"] == grupo and por_etiqueta != grupo):
                    grupo += 1
                datos["resumen"].append({"unidad": unidad, "sucursal": suc, "grupo": grupo,
                                         **{k: firmar(v) for k, v in vals.items()}})
    if not encontrado:
        return None
    for s_g in datos["supervision"]:
        if s_g.get("dia") is not None and datos["semana_ini"]:
            s_g["fecha"] = datos["semana_ini"] + timedelta(days=int(s_g["dia"]))
    # Revisión de sumas de la propia hoja
    sumas_autos, sumas_gastos = {}, {}
    for a in datos["autos"]:
        sumas_autos[a["unidad"].strip().upper()] = sumas_autos.get(a["unidad"].strip().upper(), 0) + a["valor"]
    for g in datos["gastos_dia"]:
        sumas_gastos[g["sucursal"] or g["unidad"]] = sumas_gastos.get(g["sucursal"] or g["unidad"], 0) + g["valor"]
    for r in datos["resumen"]:
        clave_a = next((k for k in sumas_autos if sucursal_de_unidad_hoja(k, alias_extra) == r["sucursal"] and r["sucursal"]), None)
        if clave_a is not None and "vehiculos" in r and abs(sumas_autos[clave_a] - r["vehiculos"]) > 0.5:
            datos["revision"].append(f"{r['unidad']}: los autos por día suman {sumas_autos[clave_a]:,.0f} pero el resumen semanal dice {r['vehiculos']:,.0f}.")
        if r["sucursal"] in sumas_gastos and "gastos" in r and abs(sumas_gastos[r["sucursal"]] - r["gastos"]) > 0.5:
            datos["revision"].append(f"{r['unidad']}: el gasto por día suma ${sumas_gastos[r['sucursal']]:,.2f} pero el resumen semanal dice ${r['gastos']:,.2f}.")
    suma_sup = sum(s["importe"] for s in datos["supervision"])
    if "supervision_declarado" in datos["totales"] and abs(suma_sup - datos["totales"]["supervision_declarado"]) > 0.5:
        datos["revision"].append(f"Gasto de supervisión: los renglones suman ${suma_sup:,.2f} pero el TOTAL de la hoja dice "
                                 f"${datos['totales']['supervision_declarado']:,.2f} (diferencia ${suma_sup - datos['totales']['supervision_declarado']:,.2f}).")
    grupos = sorted({r["grupo"] for r in datos["resumen"]})
    datos["entregas"] = []
    for g_n in grupos[1:]:
        filas_g = [r for r in datos["resumen"] if r["grupo"] == g_n]
        sucs_g = [r["sucursal"] for r in filas_g if r.get("sucursal")]
        nombre_g = datos["grupos"].get(g_n, "")
        de_g = a_g = None
        if nombre_g:   # «ENTREGA DE VICTOR A JESÚS»: el primero que se nombra entrega, el segundo recibe
            etq = _sin_acentos(nombre_g)
            pos = sorted((etq.find(_sin_acentos(k)), k) for k in SUPERVISORES_NOMBRE if _sin_acentos(k) in etq)
            if pos:
                de_g = pos[0][1]
                a_g = pos[1][1] if len(pos) > 1 else None
        if not de_g and sucs_g:   # bloque sin título: si todas sus unidades son de otro supervisor, es su entrega
            duenos = {next((k for k in SUPERVISORES_NOMBRE if suc in sucursales_de_supervisor(k)), None) for suc in sucs_g}
            if len(duenos) == 1 and None not in duenos:
                de_g = duenos.pop()
                nombre_g = nombre_g or f"Entrega de {SUPERVISORES_NOMBRE.get(de_g, de_g)} (bloque sin título)"
        if not (nombre_g or de_g):
            continue
        datos["grupos"][g_n] = nombre_g
        datos["entregas"].append({"bloque": nombre_g, "grupo": g_n, "de": de_g, "a": a_g, "sucursales": sucs_g,
                                  "unidades": len(sucs_g),
                                  **{k: round(sum(r.get(k, 0) for r in filas_g), 2) for k in ("vehiculos", "ingreso", "gastos", "utilidad")}})
    for r in datos["resumen"]:
        r["bloque"] = datos["grupos"].get(r["grupo"]) or ("Unidades propias" if r["grupo"] == (grupos[0] if grupos else 1) else f"Bloque {r['grupo']}")
    ent_grupos = set(datos["grupos"])
    if "ingreso_bruto" in datos["totales"] and datos["resumen"] and ent_grupos:
        propio = sum(r.get("ingreso", 0) for r in datos["resumen"] if r["grupo"] not in ent_grupos)
        if abs(propio - datos["totales"]["ingreso_bruto"]) <= 0.5:   # cuadra: la entrega va aparte, como debe ser
            datos["totales"]["_ingreso_cuadra_sin_entrega"] = True
    if "ingreso_bruto" in datos["totales"] and datos["resumen"] and not datos["totales"].get("_ingreso_cuadra_sin_entrega"):
        ing_todos = sum(r.get("ingreso", 0) for r in datos["resumen"])
        if abs(ing_todos - datos["totales"]["ingreso_bruto"]) > 0.5:
            ing_g1 = sum(r.get("ingreso", 0) for r in datos["resumen"] if r["grupo"] == grupos[0])
            extra = (" (solo suma el primer bloque de unidades)" if abs(ing_g1 - datos["totales"]["ingreso_bruto"]) <= 0.5 and len(grupos) > 1 else "")
            datos["revision"].append(f"INGRESO BRUTO de la hoja ${datos['totales']['ingreso_bruto']:,.2f}, pero el ingreso de todas las unidades "
                                     f"suma ${ing_todos:,.2f}{extra}.")
    if "gastos_operativos" in datos["totales"] and datos["resumen"] and ent_grupos:
        gas_propio = sum(r.get("gastos", 0) for r in datos["resumen"] if r["grupo"] not in ent_grupos)
        decl_sup = datos["totales"].get("supervision_declarado", suma_sup)
        if abs(gas_propio + decl_sup - datos["totales"]["gastos_operativos"]) <= 0.5:
            datos["totales"]["_gasto_cuadra_sin_entrega"] = True
    if "gastos_operativos" in datos["totales"] and datos["resumen"] and not datos["totales"].get("_gasto_cuadra_sin_entrega"):
        gas_todos = sum(r.get("gastos", 0) for r in datos["resumen"]) + suma_sup
        if abs(gas_todos - datos["totales"]["gastos_operativos"]) > 0.5:
            gas_g1 = sum(r.get("gastos", 0) for r in datos["resumen"] if r["grupo"] == grupos[0])
            decl = datos["totales"].get("supervision_declarado", suma_sup)
            extra = (" (solo suma el primer bloque de unidades y el TOTAL de supervisión)"
                     if len(grupos) > 1 and abs(gas_g1 + decl - datos["totales"]["gastos_operativos"]) <= 0.5 else "")
            datos["revision"].append(f"GASTOS OPERATIVOS de la hoja ${datos['totales']['gastos_operativos']:,.2f}, pero gastos de todas las unidades "
                                     f"+ supervisión suman ${gas_todos:,.2f}{extra}.")
    if "total_vehiculos" in datos["totales"] and datos["resumen"]:
        v_todos = sum(r.get("vehiculos", 0) for r in datos["resumen"])
        if abs(v_todos - datos["totales"]["total_vehiculos"]) > 0.5:
            datos["revision"].append(f"TOTAL DE VEHÍCULOS de la hoja {datos['totales']['total_vehiculos']:,.0f}, pero las unidades suman {v_todos:,.0f}.")
    for r in datos["resumen"]:
        if r.get("vehiculos") and r.get("ingreso") and abs(r["vehiculos"] - r["ingreso"]) < 0.5 and r["vehiculos"] > 500:
            datos["revision"].append(f"{r['unidad']}: vehículos e ingreso son el mismo número ({r['vehiculos']:,.0f}); "
                                     "parece que en «AUTOS» se anotó dinero, no autos.")
    return datos


def _huella_semana(d):
    return sorted((str(a.get("unidad", "")).strip().upper(), a.get("dia"), round(float(a.get("valor") or 0), 2)) for a in d.get("autos", []))


def _guardar_semana_hoja(clave, datos):
    """Guarda la semana leída. Devuelve "ok", "titulo_viejo" (se guardó pero el título parece de una semana pasada)
    o "conflicto" (la hoja trae números distintos con el título de una semana que ya se había guardado completa:
    casi seguro se capturó la semana nueva sin cambiar el título; NO se sobrescribe)."""
    if not datos or not datos.get("semana_ini"):
        return "ok"
    hoy = ahora_mx().date()
    viejo = datos["semana_fin"] < hoy - timedelta(days=7)
    todo = {}
    try:
        todo = json.loads(HOJAS_SUP_DATOS_FILE.read_text(encoding="utf-8")) if HOJAS_SUP_DATOS_FILE.exists() else {}
    except (OSError, ValueError):
        todo = {}
    lunes = datos["semana_ini"]
    previa = (todo.get(clave) or {}).get(str(lunes))
    if viejo and previa and _huella_semana(previa) != _huella_semana(datos):
        leida_previa = fecha_flexible(str(previa.get("leido_en", ""))[:10])
        if leida_previa and leida_previa > datos["semana_fin"]:
            return "conflicto"
    copia = dict(datos)
    copia["semana_ini"], copia["semana_fin"] = str(datos["semana_ini"]), str(datos["semana_fin"])
    copia["supervision"] = [dict(s, fecha=str(s["fecha"]) if s.get("fecha") else None) for s in datos["supervision"]]
    copia["leido_en"] = ahora_mx().strftime("%Y-%m-%d %H:%M:%S")
    todo.setdefault(clave, {})[str(lunes)] = copia
    _escribir_json_seguro(HOJAS_SUP_DATOS_FILE, todo)
    return "titulo_viejo" if viejo else "ok"


def semanas_hoja_supervisor(clave):
    try:
        todo = json.loads(HOJAS_SUP_DATOS_FILE.read_text(encoding="utf-8")) if HOJAS_SUP_DATOS_FILE.exists() else {}
    except (OSError, ValueError):
        return {}
    return dict(todo.get(clave) or {})


def _datos_app_semana(lunes, sucursales):
    """Lo que la app tiene de esa semana por (sucursal, día): reporte físico (vehículos, ingreso), gastos registrados
    (sin los de las hojas de Google) y lo registrado en la app (vehículos y cobros)."""
    domingo = lunes + timedelta(days=6)
    permit = set(sucursales)
    fis, gas, app_v, app_c = {}, {}, {}, {}
    for r in _leer_lista_json(FISICOS_FILE):
        if r.get("tipo_reporte") != "ingresos":
            continue
        dia, suc = fecha_flexible(r.get("Fecha")), r.get("Sitio / Unidad")
        if dia and suc in permit and lunes <= dia <= domingo:
            acc = fis.setdefault((suc, dia), {"vehiculos": 0, "ingreso": 0.0})
            acc["vehiculos"] += _entero_seguro(r.get("Total Boletos") or r.get("Boletos Cobrados"))
            acc["ingreso"] += _flotante_seguro(r.get("Ingreso Bruto"))
    for g in _leer_lista_json(GASTOS_FILE_RF):
        if g.get("origen") == "Hoja de Google":
            continue
        dia, suc = fecha_flexible(g.get("fecha")), g.get("sucursal")
        if dia and suc in permit and lunes <= dia <= domingo:
            gas[(suc, dia)] = gas.get((suc, dia), 0.0) + dinero(g.get("importe"))
    vehiculos = st.session_state.get("vehiculos") or cargar_bd()
    for reg in vehiculos:
        suc = reg.get("sucursal")
        if suc not in permit:
            continue
        dia = fecha_op_registro(reg)
        if dia and lunes <= dia <= domingo and reg.get("estado") != "Cancelado":
            app_v[(suc, dia)] = app_v.get((suc, dia), 0) + 1
        for p in reg.get("pagos", []) or []:
            if p.get("estado") != "Pagado":
                continue
            dia_p = fecha_op_pago(p)
            suc_p = p.get("sucursal") or suc
            if dia_p and lunes <= dia_p <= domingo:
                app_c[(suc_p, dia_p)] = app_c.get((suc_p, dia_p), 0.0) + dinero(p.get("importe"))
    return fis, gas, app_v, app_c


def _dif(a, b):
    if a is None or b is None:
        return None
    return round(float(a) - float(b), 2)


def _vista_cuadre_entrega(ent, receptor, hoja_receptor, lunes_txt, clave_ui=""):
    """La entrega que trae la hoja del receptor (p. ej. «ENTREGA DE VICTOR A JESÚS») debe ser igual a la tabla de la
    hoja de quien entrega, la misma semana: autos, ingreso, gastos y utilidad por unidad."""
    de = ent.get("de")
    n_rec = str(receptor).title()            # «Jesús», «Víctor»: como se llaman en las hojas
    n_de = str(de).title() if de else "quien entrega"
    lunes = fecha_de_celda(lunes_txt)
    st.markdown(f"#### 🤝 Entrega de {SUPERVISORES_NOMBRE.get(de, de or '¿?')} a {SUPERVISORES_NOMBRE.get(receptor, receptor)}")
    e1, e2, e3, e4 = st.columns(4)
    e1.metric(f"Autos (hoja de {n_rec})", f"{ent['vehiculos']:,.0f}")
    e2.metric("Ingreso", f"${ent['ingreso']:,.2f}")
    e3.metric("Gastos", f"${ent['gastos']:,.2f}")
    e4.metric("Utilidad", f"${ent['utilidad']:,.2f}")
    if not de:
        st.caption("No se pudo saber qué supervisor hace esta entrega: escribe en la hoja «ENTREGA DE (nombre) A (nombre)».")
        return
    hoja_de = semanas_hoja_supervisor(de).get(lunes_txt)
    if not hoja_de:
        otras = sorted(semanas_hoja_supervisor(de), reverse=True)
        st.info(f"⏳ Para cuadrar, falta la semana del {lunes:%d/%m/%Y} en la hoja de {SUPERVISORES_NOMBRE.get(de, de)}"
                + (f" (lo último que se leyó de su hoja es la semana del {fecha_de_celda(otras[0]):%d/%m/%Y})." if otras
                   else " (su hoja todavía no está conectada o no se ha leído).")
                + " En cuanto él capture esa semana, aquí sale el cuadre.")
        return
    rec = {r["sucursal"]: r for r in hoja_receptor.get("resumen", []) if r.get("sucursal") and r["grupo"] == ent.get("grupo")}
    ori = {r["sucursal"]: r for r in hoja_de.get("resumen", []) if r.get("sucursal")}
    filas = []
    for suc in sorted(set(rec) | set(ori)):
        a, b = rec.get(suc, {}), ori.get(suc, {})
        if not any(abs(x.get(k) or 0) > 0 for x in (a, b) for k in ("vehiculos", "ingreso", "gastos")):
            continue
        fila = {"Sucursal": suc}
        cuadra = True
        for k, nom in (("vehiculos", "Autos"), ("ingreso", "Ingreso"), ("gastos", "Gasto"), ("utilidad", "Utilidad")):
            va, vb = (a.get(k) if a else None), (b.get(k) if b else None)
            fila[f"{nom} {n_rec}"] = va
            fila[f"{nom} {n_de}"] = vb
            if va is None or vb is None or abs((va or 0) - (vb or 0)) > 0.5:
                cuadra = False
        fila["Cuadra"] = "✅" if cuadra else ("🔴 falta en hoja de " + (n_rec if not a else n_de) if not (a and b) else "🔴")
        filas.append(fila)
    if not filas:
        st.caption("Sin unidades con movimiento para cuadrar.")
        return
    df_c = pd.DataFrame(filas)
    tot = {"Sucursal": "TOTAL"}
    for c in df_c.columns[1:-1]:
        tot[c] = float(pd.to_numeric(df_c[c], errors="coerce").fillna(0).sum())
    no = int((df_c["Cuadra"] != "✅").sum())
    tot["Cuadra"] = "✅" if no == 0 else f"🔴 {no}"
    df_c = pd.concat([df_c, pd.DataFrame([tot])], ignore_index=True)
    if no == 0:
        st.success(f"✅ La entrega cuadra: lo que dice la hoja de {n_rec} es igual a la tabla de {n_de}.")
    else:
        st.error(f"🔴 La entrega NO cuadra en {no} unidad(es): la hoja de {n_rec} y la tabla de {n_de} tienen números distintos.")
    monedas = [c for c in df_c.columns if c.split()[0] in ("Ingreso", "Gasto", "Utilidad")]
    estilo = df_c.style.apply(lambda fila: ["background-color:#FDE2E1" if str(fila["Cuadra"]).startswith("🔴") else "" for _ in fila], axis=1)
    st.dataframe(estilo, use_container_width=True, hide_index=True,
                 column_config={c: st.column_config.NumberColumn(c, format="$%.2f") for c in monedas})


REVISIONES_HOJAS_FILE = DATA_DIR / "revisiones_hojas_supervisores.json"
_DIAS_CORTOS = ["LUN", "MAR", "MIÉ", "JUE", "VIE", "SÁB", "DOM"]


def _revisiones_hojas():
    try:
        datos = json.loads(REVISIONES_HOJAS_FILE.read_text(encoding="utf-8")) if REVISIONES_HOJAS_FILE.exists() else {}
        return datos if isinstance(datos, dict) else {}
    except (OSError, ValueError):
        return {}


def _guardar_revision_hoja(clave_rev, resultado, nota):
    with _candado_bd():
        todo = _revisiones_hojas()
        todo[clave_rev] = {"resultado": resultado, "nota": nota.strip(), "por": st.session_state.get("usuario_autenticado", ""),
                           "en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S")}
        _escribir_json_seguro(REVISIONES_HOJAS_FILE, todo)


def _mover_indice(clave_idx, delta, total):
    st.session_state[clave_idx] = (int(st.session_state.get(clave_idx, 0) or 0) + delta) % max(1, total)


def _rejilla_hoja(registros, titulo_valor):
    """Recuadro de la hoja tal como lo escribió el supervisor: una fila por unidad, lunes…domingo y total."""
    orden, datos = [], {}
    for a in registros:
        u = str(a.get("unidad", "")).strip()
        if u not in datos:
            orden.append(u)
            datos[u] = {"Unidad": u, **{d: None for d in _DIAS_CORTOS}}
        datos[u][_DIAS_CORTOS[int(a["dia"])]] = a["valor"]
    filas = [datos[u] for u in orden]
    for f in filas:
        f["TOTAL"] = sum(v for k, v in f.items() if k in _DIAS_CORTOS and v)
    df = pd.DataFrame(filas, columns=["Unidad"] + _DIAS_CORTOS + ["TOTAL"])
    if not df.empty:
        tot = {"Unidad": "TOTAL", **{c: float(pd.to_numeric(df[c], errors="coerce").fillna(0).sum()) for c in _DIAS_CORTOS + ["TOTAL"]}}
        df = pd.concat([df, pd.DataFrame([tot])], ignore_index=True)
    formato = "$%.0f" if titulo_valor == "dinero" else "%d"
    estilo = df.style.apply(lambda fila: ["font-weight:800;background-color:#EAF5EE" if fila["Unidad"] == "TOTAL" else "" for _ in fila], axis=1)
    st.dataframe(estilo, use_container_width=True, hide_index=True,
                 column_config={c: st.column_config.NumberColumn(c, format=formato) for c in _DIAS_CORTOS + ["TOTAL"]})


def vista_comprobar_hoja(clave, hoja, lunes_txt):
    """La hoja del supervisor abierta dentro de la app y, al lado, el reporte físico (con sus fotos) de cada unidad y día."""
    lunes = fecha_de_celda(lunes_txt)
    dias = [lunes + timedelta(days=i) for i in range(7)]
    nombre_sup = SUPERVISORES_NOMBRE.get(clave, clave)
    url_hoja = (config_hojas_supervisores().get(clave) or {}).get("url", "")
    id_h = id_hoja_google(url_hoja)
    t_hoja, t_comp = st.tabs(["📄 Hoja del supervisor", "🧾 Comprobar contra reportes físicos"])
    with t_hoja:
        st.caption(f"Así viene la hoja de {nombre_sup} · «{hoja.get('titulo_semana', '')}» · leída el {hoja.get('leido_en', '')}")
        if id_h:
            st.link_button("📄 Abrir la hoja original en Google Sheets", f"https://docs.google.com/spreadsheets/d/{id_h}/edit",
                           use_container_width=True)
        st.markdown("##### 🚗 AUTOS")
        _rejilla_hoja(hoja.get("autos", []), "autos")
        st.markdown("##### 💸 GASTO DEL DÍA POR UNIDAD")
        _rejilla_hoja(hoja.get("gastos_dia", []), "dinero")
        sup = hoja.get("supervision", [])
        st.markdown(f"##### 👔 GASTO DE SUPERVISIÓN · ${sum(s_['importe'] for s_ in sup):,.2f}")
        if sup:
            st.dataframe(pd.DataFrame([{"Concepto": s_["concepto"], "Fecha": s_.get("fecha") or "", "Importe": s_["importe"]} for s_ in sup]),
                         use_container_width=True, hide_index=True, column_config={"Importe": st.column_config.NumberColumn("Importe", format="$%.2f")})
        else:
            st.caption("Sin gastos de supervisión en esta semana.")
        st.markdown("##### 📋 RESUMEN DE LA SEMANA")
        res = pd.DataFrame([{"Unidad": r["unidad"].strip(), "Bloque": r.get("bloque", ""), "Vehículos": r.get("vehiculos"), "Ingreso": r.get("ingreso"),
                             "Gastos": r.get("gastos"), "Utilidad": r.get("utilidad")} for r in hoja.get("resumen", [])])
        if not res.empty:
            res = pd.concat([res, pd.DataFrame([{"Unidad": "TOTAL", "Bloque": "", **{c: float(pd.to_numeric(res[c], errors="coerce").fillna(0).sum())
                                                                                     for c in ("Vehículos", "Ingreso", "Gastos", "Utilidad")}}])], ignore_index=True)
            st.dataframe(res.style.apply(lambda fila: ["font-weight:800;background-color:#EAF5EE" if fila["Unidad"] == "TOTAL" else "" for _ in fila], axis=1),
                         use_container_width=True, hide_index=True,
                         column_config={"Vehículos": st.column_config.NumberColumn("Vehículos", format="%d"),
                                        **{c: st.column_config.NumberColumn(c, format="$%.2f") for c in ("Ingreso", "Gastos", "Utilidad")}})
        if id_h:
            with st.expander("🌐 Ver la hoja original de Google aquí mismo"):
                st.caption("Si sale la pantalla de Google para iniciar sesión, la hoja no está compartida por enlace: usa el botón «Abrir la hoja original».")
                url_vista = f"https://docs.google.com/spreadsheets/d/{id_h}/htmlview?rm=minimal"
                try:
                    st.iframe(url_vista, height=620)
                except Exception:
                    st.components.v1.iframe(url_vista, height=620, scrolling=True)
    with t_comp:
        sucursales = sorted({a["sucursal"] for a in hoja.get("autos", []) if a.get("sucursal")} |
                            {r["sucursal"] for r in hoja.get("resumen", []) if r.get("sucursal")})
        fis_reg = {}
        for r in _leer_lista_json(FISICOS_FILE):
            if r.get("tipo_reporte") != "ingresos":
                continue
            dia_r, suc_r = fecha_flexible(r.get("Fecha")), r.get("Sitio / Unidad")
            if dia_r and suc_r in sucursales and lunes <= dia_r <= dias[-1]:
                fis_reg.setdefault((suc_r, dia_r), []).append(r)
        _, gas, app_v, app_c = _datos_app_semana(lunes, sucursales)
        autos_h = {(a["sucursal"], int(a["dia"])): a["valor"] for a in hoja.get("autos", []) if a.get("sucursal")}
        gastos_h = {(g["sucursal"], int(g["dia"])): g["valor"] for g in hoja.get("gastos_dia", []) if g.get("sucursal")}
        pares = [(s_, i) for s_ in sucursales for i in range(7)
                 if (autos_h.get((s_, i)) or 0) > 0 or (gastos_h.get((s_, i)) or 0) > 0 or (s_, dias[i]) in fis_reg]
        if not pares:
            st.info("Esta semana la hoja no trae movimientos por día para comprobar.")
            return
        revs = _revisiones_hojas()
        clave_rev = lambda par: f"{clave}|{lunes_txt}|{par[0]}|{par[1]}"
        hechos = sum(1 for p_ in pares if clave_rev(p_) in revs)
        st.progress(hechos / len(pares), text=f"Revisados {hechos} de {len(pares)} días-unidad de la hoja de {nombre_sup}")
        clave_idx = f"comp_idx_{clave}_{lunes_txt}"
        if int(st.session_state.get(clave_idx, 0) or 0) >= len(pares):
            st.session_state[clave_idx] = 0
        marca = lambda p_: {"ok": "✅", "mal": "❌"}.get((revs.get(clave_rev(p_)) or {}).get("resultado"), "⬜")
        b1, b2 = st.columns(2)
        b1.button("⬅️ Anterior", key=f"comp_ant_{clave_idx}", use_container_width=True, on_click=_mover_indice, args=(clave_idx, -1, len(pares)))
        b2.button("Siguiente ➡️", key=f"comp_sig_{clave_idx}", use_container_width=True, on_click=_mover_indice, args=(clave_idx, 1, len(pares)))
        idx = st.selectbox("Unidad y día", list(range(len(pares))), key=clave_idx,
                           format_func=lambda k: f"{marca(pares[k])} {pares[k][0]} · {_DIAS_CORTOS[pares[k][1]]} {dias[pares[k][1]]:%d/%m}")
        suc, i_d = pares[idx]
        dia = dias[i_d]
        reportes = fis_reg.get((suc, dia), [])
        v_rep = sum(_entero_seguro(r.get("Total Boletos") or r.get("Boletos Cobrados")) for r in reportes)
        i_rep = sum(_flotante_seguro(r.get("Ingreso Bruto")) for r in reportes)
        a_h, g_h = autos_h.get((suc, i_d)), gastos_h.get((suc, i_d))
        g_reg = gas.get((suc, dia))
        st.markdown(f"#### {suc} · {NOMBRES_DIA[i_d].title()} {dia:%d/%m/%Y}")
        c_h, c_r = st.columns(2)
        with c_h:
            st.markdown(f"**📄 Hoja de {nombre_sup.split()[0]}**")
            st.metric("Autos", f"{a_h:,.0f}" if a_h is not None else "—")
            st.metric("Gasto del día", f"${g_h:,.2f}" if g_h is not None else "—")
        with c_r:
            st.markdown("**🧾 Reporte físico**")
            st.metric("Autos (boletos)", f"{v_rep:,}" if reportes else "—",
                      delta=(f"{v_rep - (a_h or 0):+,.0f} vs hoja" if reportes and a_h is not None and v_rep != a_h else None), delta_color="off")
            st.metric("Gasto registrado", f"${g_reg:,.2f}" if g_reg is not None else "—",
                      delta=(f"{(g_reg or 0) - (g_h or 0):+,.2f} vs hoja" if g_h is not None and abs((g_reg or 0) - g_h) > 0.5 else None), delta_color="off")
        if reportes:
            cuadra_autos = a_h is None or abs(v_rep - a_h) < 0.5
            (st.success if cuadra_autos else st.error)(
                ("✅ Autos: la hoja y el reporte físico coinciden." if cuadra_autos
                 else f"🔴 Autos: la hoja dice {a_h:,.0f} y el reporte físico {v_rep:,} (diferencia {v_rep - a_h:+,.0f})."))
            for r in reportes:
                st.markdown(f"**Reporte {r.get('ID', '')}** · Ingreso **${_flotante_seguro(r.get('Ingreso Bruto')):,.2f}** · "
                            f"Folios {r.get('Folio Inicial', '—')} → {r.get('Folio Final', '—')} · Boletos {r.get('Total Boletos', '—')} · "
                            f"Sin cobro {r.get('Sin Cobro', 0)} · Cancelados {r.get('Cancelados', 0)} · Perdidos {r.get('Perdidos', 0)}"
                            + (f" · Elaboró {r.get('Elaboró')}" if r.get("Elaboró") else ""))
                fotos_r = [(f"Foto {k}", _ruta_absoluta(p_)) for k, p_ in enumerate(r.get("fotos", []) or [], start=1)]
                visor_zoom_fotos([f_ for f_ in fotos_r if f_[1]], key=f"comp_{r.get('ID', '')}_{idx}", alto=460)
        else:
            st.warning(f"⚠️ No hay reporte físico de {suc} del {dia:%d/%m/%Y}.")
            st.button("📤 Subir el reporte que falta", key=f"comp_subir_{clave_idx}_{idx}", use_container_width=True,
                      on_click=_abrir_subir_con, args=({"sucursal": suc, "fecha": dia, "tipo": "Servicio"},))
        if app_v.get((suc, dia)) or app_c.get((suc, dia)):
            st.caption(f"📱 En la app: {app_v.get((suc, dia), 0)} vehículo(s) registrados · cobros ${app_c.get((suc, dia), 0.0):,.2f}")
        previa = revs.get(clave_rev((suc, i_d)))
        if previa:
            st.info(f"{'✅ Revisado: cuadra' if previa['resultado'] == 'ok' else '❌ Revisado: NO cuadra'} · {previa.get('por', '')} · {previa.get('en', '')}"
                    + (f" · Nota: {previa['nota']}" if previa.get("nota") else ""))
        nota = st.text_input("Nota de la revisión (opcional)", key=f"comp_nota_{clave_idx}_{idx}",
                             placeholder="Ej. faltan 2 boletos, falta la foto, el gasto no viene en la hoja…")
        r1, r2 = st.columns(2)
        if r1.button("✅ Cuadra", key=f"comp_ok_{clave_idx}_{idx}", use_container_width=True, type="primary"):
            _guardar_revision_hoja(clave_rev((suc, i_d)), "ok", nota)
            guardar_evento_auditoria("REVISIÓN HOJA SUPERVISOR", f"{nombre_sup} · {suc} · {dia:%d/%m/%Y} · CUADRA" + (f" · {nota.strip()}" if nota.strip() else ""))
            st.rerun()
        if r2.button("❌ No cuadra", key=f"comp_mal_{clave_idx}_{idx}", use_container_width=True):
            _guardar_revision_hoja(clave_rev((suc, i_d)), "mal", nota)
            guardar_evento_auditoria("REVISIÓN HOJA SUPERVISOR", f"{nombre_sup} · {suc} · {dia:%d/%m/%Y} · NO CUADRA" + (f" · {nota.strip()}" if nota.strip() else ""))
            st.rerun()
        malos = [p_ for p_ in pares if (revs.get(clave_rev(p_)) or {}).get("resultado") == "mal"]
        if malos:
            with st.expander(f"❌ Marcados como NO cuadra · {len(malos)}"):
                st.dataframe(pd.DataFrame([{"Unidad": p_[0], "Día": f"{_DIAS_CORTOS[p_[1]]} {dias[p_[1]]:%d/%m}",
                                            "Nota": revs[clave_rev(p_)].get("nota", ""), "Revisó": revs[clave_rev(p_)].get("por", "")} for p_ in malos]),
                             use_container_width=True, hide_index=True)


# ---------------------------------------------------------------------
# CUENTA DE SERVICIO DE GOOGLE: la app lee y LLENA las hojas de los supervisores sin hacerlas públicas.
# Secreto GOOGLE_SERVICE_ACCOUNT_JSON (el JSON de la llave). Cada hoja se comparte como Editor con el
# correo de esa cuenta (…@….iam.gserviceaccount.com).
# ---------------------------------------------------------------------
def _info_cuenta_servicio():
    valor = ""
    try:
        valor = st.secrets.get("GOOGLE_SERVICE_ACCOUNT_JSON", "")
    except Exception:
        valor = ""
    valor = valor or os.environ.get("GOOGLE_SERVICE_ACCOUNT_JSON", "")
    if not valor:
        return None
    try:
        info = dict(valor) if not isinstance(valor, str) else json.loads(valor)
        return info if info.get("client_email") and info.get("private_key") else None
    except (ValueError, TypeError):
        return None


def correo_cuenta_servicio():
    info = _info_cuenta_servicio()
    return (info or {}).get("client_email", "")


@st.cache_resource(show_spinner=False)
def _sesion_google():
    from google.oauth2 import service_account
    from google.auth.transport.requests import AuthorizedSession
    info = _info_cuenta_servicio()
    if not info:
        raise RuntimeError("Falta configurar GOOGLE_SERVICE_ACCOUNT_JSON en Render.")
    cred = service_account.Credentials.from_service_account_info(
        info, scopes=["https://www.googleapis.com/auth/spreadsheets", "https://www.googleapis.com/auth/drive.readonly"])
    return AuthorizedSession(cred)


def _google_api(metodo, url, **kw):
    try:
        resp = _sesion_google().request(metodo, url, timeout=30, **kw)
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError(f"No se pudo conectar con Google: {exc}")
    if resp.status_code in (403, 404):
        raise RuntimeError(f"Google no dejó entrar a la hoja: compártela como Editor con {correo_cuenta_servicio()}.")
    if resp.status_code >= 400:
        raise RuntimeError(f"Google respondió {resp.status_code}: {resp.text[:200]}")
    return resp


def sheets_valores(id_hoja):
    """{pestaña: renglones} con los valores tal cual (números como números)."""
    meta = _google_api("GET", f"https://sheets.googleapis.com/v4/spreadsheets/{id_hoja}",
                       params={"fields": "sheets.properties(title)"}).json()
    titulos = [s_["properties"]["title"] for s_ in meta.get("sheets", [])]
    if not titulos:
        return {}
    rangos = [f"'{t}'!A1:Z300" for t in titulos]
    datos = _google_api("GET", f"https://sheets.googleapis.com/v4/spreadsheets/{id_hoja}/values:batchGet",
                        params=[("ranges", r_) for r_ in rangos] + [("valueRenderOption", "UNFORMATTED_VALUE"),
                                                                     ("majorDimension", "ROWS")]).json()
    return {t: (vr.get("values") or []) for t, vr in zip(titulos, datos.get("valueRanges", []))}


def sheets_escribir(id_hoja, celdas):
    """celdas: [(pestaña, 'B3', valor), ...]"""
    if not celdas:
        return 0
    cuerpo = {"valueInputOption": "USER_ENTERED",
              "data": [{"range": f"'{t}'!{a1}", "values": [[v]]} for t, a1, v in celdas]}
    _google_api("POST", f"https://sheets.googleapis.com/v4/spreadsheets/{id_hoja}/values:batchUpdate", json=cuerpo)
    return len(celdas)


def _letra_columna(i):
    letras = ""
    i += 1
    while i:
        i, r = divmod(i - 1, 26)
        letras = chr(65 + r) + letras
    return letras


def ubicar_celdas_hoja(renglones, alias_extra=None):
    """Dónde va cada dato en la hoja semanal: fila de cada unidad en AUTOS y en GASTO DEL DÍA, columna de cada día."""
    texto = " ".join(str(v) for r in renglones for v in r if isinstance(v, str))
    semana = semana_de_titulo(texto)
    res = {"semana": semana, "autos": {}, "gastos_dia": {}}
    cols_dia, modo = {}, None
    for i_r, r in enumerate(renglones):
        norm = [_sin_acentos(v).strip() if isinstance(v, str) else "" for v in r]
        unido = " ".join(n for n in norm if n)
        dias_fila = {i: _DIAS_HOJA[n] for i, n in enumerate(norm) if n in _DIAS_HOJA}
        if len(dias_fila) >= 5:
            cols_dia, modo = {wd: i for i, wd in dias_fila.items()}, "autos"
            continue
        if "UNIDAD" in norm and any(n.startswith("VEHICULO") for n in norm):
            modo = None
            continue
        if "GASTO" in unido and "SUPERVIS" in unido:
            modo = None
            continue
        if "GASTO" in unido and ("UNIDAD" in unido or "DEL DIA" in unido) and not any(
                isinstance(v, (int, float)) and not isinstance(v, bool) for v in r):
            modo = "gastos_dia"
            continue
        if modo and cols_dia and r and isinstance(r[0], str) and r[0].strip():
            suc = sucursal_de_unidad_hoja(r[0], alias_extra)
            if suc and suc not in res[modo]:
                res[modo][suc] = {"fila": i_r, "cols": dict(cols_dia),
                                  "actual": {wd: (r[c] if c < len(r) else "") for wd, c in cols_dia.items()}}
    return res


def _autos_en_pesos(clave, suc):
    """Barranca y Clínica anotan pesos en «AUTOS»: se detecta en la última semana leída (vehículos = ingreso)."""
    for _, hoja in sorted(semanas_hoja_supervisor(clave).items(), reverse=True):
        r = next((x for x in hoja.get("resumen", []) if x.get("sucursal") == suc), None)
        if r and r.get("vehiculos") and abs((r.get("vehiculos") or 0) - (r.get("ingreso") or 0)) < 0.5 and r["vehiculos"] > 100:
            return True
        if r:
            return False
    return False


def supervisor_de_sucursal(suc):
    return next((k for k in SUPERVISORES_NOMBRE if suc in sucursales_de_supervisor(k)), None)


def plan_llenado_hoja(clave, fechas=None, sobrescribir=False):
    """Qué celdas de la hoja del supervisor se pueden llenar con los reportes físicos y gastos registrados.
    fechas: conjunto de fechas a llenar (None = todas las de la semana de cada pestaña)."""
    cfg = config_hojas_supervisores().get(clave) or {}
    id_hoja = id_hoja_google(cfg.get("url"))
    if not id_hoja:
        raise RuntimeError(f"{SUPERVISORES_NOMBRE.get(clave, clave)} no tiene su hoja conectada.")
    pestañas = sheets_valores(id_hoja)
    plan = []
    for tab, renglones in pestañas.items():
        ub = ubicar_celdas_hoja(renglones, cfg.get("alias"))
        if not ub["semana"] or not (ub["autos"] or ub["gastos_dia"]):
            continue
        lunes = ub["semana"][0]
        dias = [lunes + timedelta(days=i) for i in range(7)]
        if fechas and not any(d in fechas for d in dias):
            continue
        sucs = sorted(set(ub["autos"]) | set(ub["gastos_dia"]))
        sucs = [s_ for s_ in sucs if supervisor_de_sucursal(s_) in (clave, None)]   # solo sus unidades (no la entrega del otro)
        fis, gas, _, _ = _datos_app_semana(lunes, sucs)
        for suc in sucs:
            en_pesos = _autos_en_pesos(clave, suc)
            for wd, d in enumerate(dias):
                if fechas and d not in fechas:
                    continue
                for bloque, valor in (("autos", (fis.get((suc, d)) or {}).get("ingreso" if en_pesos else "vehiculos") if (suc, d) in fis else None),
                                      ("gastos_dia", gas.get((suc, d)))):
                    pos = ub[bloque].get(suc)
                    if pos is None or valor is None or wd not in pos["cols"]:
                        continue
                    actual = pos["actual"].get(wd, "")
                    vacia = actual in ("", None)
                    igual = (not vacia) and _es_numero_celda(actual) and abs(_numero_con_signo(actual) - float(valor)) < 0.01
                    accion = "igual" if igual else ("llenar" if vacia else ("sobrescribir" if sobrescribir else "diferente"))
                    plan.append({"pestaña": tab, "celda": f"{_letra_columna(pos['cols'][wd])}{pos['fila'] + 1}", "Sucursal": suc,
                                 "Día": f"{['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'][wd]} {d:%d/%m}", "fecha": d,
                                 "Dato": ("Autos ($)" if en_pesos else "Autos") if bloque == "autos" else "Gasto del día",
                                 "En la hoja": "" if vacia else actual, "Del reporte": round(float(valor), 2), "accion": accion})
    return id_hoja, plan


def llenar_hoja_supervisor(clave, fechas=None, sobrescribir=False):
    id_hoja, plan = plan_llenado_hoja(clave, fechas, sobrescribir)
    celdas = [(p_["pestaña"], p_["celda"], p_["Del reporte"]) for p_ in plan if p_["accion"] in ("llenar", "sobrescribir")]
    n = sheets_escribir(id_hoja, celdas)
    if n:
        guardar_evento_auditoria("HOJA DE SUPERVISOR LLENADA",
                                 f"{SUPERVISORES_NOMBRE.get(clave, clave)} · {n} celda(s) · " +
                                 ", ".join(sorted({f"{p_['Sucursal']} {p_['Día']}" for p_ in plan if p_['accion'] in ('llenar', 'sobrescribir')}))[:400])
    return n, [p_ for p_ in plan if p_["accion"] == "diferente"]


def llenar_hoja_desde_reporte(suc, fecha):
    """Tras guardar un reporte físico: pasa sus datos a la hoja de Google del supervisor (solo celdas vacías).
    Devuelve un texto corto para el aviso, o "" si no aplica."""
    clave = supervisor_de_sucursal(suc)
    if not clave or not _info_cuenta_servicio() or not (config_hojas_supervisores().get(clave) or {}).get("url"):
        return ""
    try:
        n, difs = llenar_hoja_supervisor(clave, {fecha})
    except Exception as exc:
        return f" ⚠️ No se pudo llenar la hoja de {SUPERVISORES_NOMBRE.get(clave, clave)}: {exc}"
    txt = f" ✍️ Hoja de {SUPERVISORES_NOMBRE.get(clave, clave)}: {n} dato(s) llenado(s)." if n else ""
    if difs:
        txt += f" ⚠️ {len(difs)} dato(s) ya tenían otro número en la hoja (no se cambiaron; revísalos en 🔍 Hoja vs reportes)."
    return txt


# ---------------------------------------------------------------------
# CARGA MASIVA: las fotos de los reportes que llegaron al grupo de WhatsApp, todas de una vez.
# La IA lee cada una (sucursal, fecha, folios, boletos, sueldos…) y se revisan en una sola tabla.
# ---------------------------------------------------------------------
MAX_FOTOS_MASIVA = 40


def guardar_reporte_ingresos_leido(suc, fecha, d, foto_bytes, usuario, origen="Carga masiva", validacion="Validado"):
    """Guarda un reporte de ingresos con los datos ya revisados (mismo esquema que «Subir reporte»)."""
    rid = f"REP_{uuid.uuid4().hex[:8]}"
    rutas = guardar_fotos_reporte([io.BytesIO(foto_bytes)], rid) if foto_bytes else []
    f_ini, f_fin = _entero_seguro(d.get("Folio inicial")), _entero_seguro(d.get("Folio final"))
    total = calcular_boletos_block100(f_ini, f_fin) if (f_ini or f_fin) else _entero_seguro(d.get("Total boletos"))
    canc, perd = _entero_seguro(d.get("Cancelados")), _entero_seguro(d.get("Perdidos"))
    cobrados = _entero_seguro(d.get("Pagados")) or max(0, total - canc)
    costo = _flotante_seguro(d.get("Costo"))
    bruto = cobrados * costo if (cobrados and costo) else _flotante_seguro(d.get("Ingreso (hoja)"))
    nomina, otros = _flotante_seguro(d.get("Nómina")), _flotante_seguro(d.get("Otros gastos"))
    reg = _fila_flujo(suc, fecha, bruto, cobrados, costo, f_ini, f_fin, total, str(d.get("Elaboró") or "") or usuario, usuario, rid)
    entregar = _flotante_seguro(d.get("A entregar"))
    reg.update({"Sin Cobro": max(0, total - cobrados - canc), "Cancelados": canc, "Perdidos": perd, "tipo_reporte": "ingresos",
                "fotos": rutas, "Nómina": nomina, "Otros gastos": otros, "origen": origen, "evento_num": 0, "eventos_dia": 1,
                "Recibe": str(d.get("Recibió") or ""), "validacion": validacion, "Timestamp": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"),
                **({"Efectivo entregado": entregar, "Diferencia efectivo": round(entregar - max(0.0, bruto - nomina - otros), 2)} if entregar else {}),
                **({"validado_por": usuario, "validado_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S")} if validacion == "Validado" else {})})
    actualizar_lista_json(FISICOS_FILE, lambda lista: [reg] + lista)
    nuevos_g = [{"id": uuid.uuid4().hex[:12].upper(), "fecha": str(fecha), "sucursal": suc, "categoria": cat_g,
                 "concepto": f"{cat_g} (reporte de ingresos)", "importe": float(monto_g), "registrado_por": usuario,
                 "registrado_en": ahora_mx().strftime("%Y-%m-%d %H:%M:%S"), "origen": "Reporte físico de ingresos", "reporte_fisico_id": rid}
                for cat_g, monto_g in (("Nómina", nomina), ("Otros", otros)) if monto_g > 0]
    if nuevos_g:
        actualizar_lista_json(GASTOS_FILE_RF, lambda lista: nuevos_g + lista)
    guardar_evento_auditoria("REPORTE FISICO DE INGRESOS", f"{suc} · {fecha:%d/%m/%Y} · ${bruto:,.2f} · {rid} · {origen}")
    return rid, bruto


def vista_carga_masiva(sucursales_permitidas, es_contador):
    st.caption("Sube de una vez las fotos de los Reportes de Flujo que llegaron al grupo (puedes elegir varias de la galería). "
               f"La IA lee cada una y detecta la sucursal y la fecha. Revisa la tabla y guarda. Máximo {MAX_FOTOS_MASIVA} fotos por carga.")
    if not ia_disponible():
        st.error("La lectura con IA no está activada: falta ANTHROPIC_API_KEY en Render.")
        return
    n_m = int(st.session_state.get("masiva_nonce", 0))
    fotos = list(st.file_uploader("Fotos de los reportes", type=["jpg", "jpeg", "png", "webp"], accept_multiple_files=True,
                                  key=f"masiva_fotos_{n_m}") or [])[:MAX_FOTOS_MASIVA]
    if not fotos:
        return
    huellas = [hashlib.md5(f.getvalue()).hexdigest()[:12] for f in fotos]
    leidas = st.session_state.setdefault(f"masiva_leidas_{n_m}", {})   # huella -> lectura
    faltan = [i for i, h in enumerate(huellas) if h not in leidas]
    if faltan and st.button(f"🤖 Leer {len(faltan)} foto(s) con IA", type="primary", use_container_width=True, key=f"masiva_leer_{n_m}"):
        barra = st.progress(0.0, text="Leyendo reportes…")
        for k, i in enumerate(faltan, start=1):
            try:
                leidas[huellas[i]] = ia_leer_reporte([fotos[i]], True)
            except RuntimeError as exc:
                leidas[huellas[i]] = {"_error": str(exc)}
            barra.progress(k / len(faltan), text=f"Leídos {k} de {len(faltan)}")
        st.rerun()
    if not any(h in leidas for h in huellas):
        return
    existentes = {(r.get("Sitio / Unidad"), r.get("Fecha")) for r in _leer_lista_json(FISICOS_FILE) if r.get("tipo_reporte") == "ingresos"}
    filas = []
    for i, (f, h) in enumerate(zip(fotos, huellas), start=1):
        lec = leidas.get(h)
        if lec is None:
            continue
        suc = sucursal_de_unidad_hoja(lec.get("sitio", "")) if lec.get("sitio") else None
        fecha = fecha_de_celda(lec.get("fecha"), None)
        sueldos = sum(_flotante_seguro(p_.get("sueldo")) for p_ in lec.get("personal", []) or [])
        otros = sum(_flotante_seguro(g_.get("importe")) for g_ in lec.get("gastos", []) or [])
        if not (sueldos or otros) and _flotante_seguro(lec.get("total_nomina_gastos")):
            otros = _flotante_seguro(lec.get("total_nomina_gastos"))
        revisar = []
        if lec.get("_error"):
            revisar.append("No se pudo leer: " + lec["_error"][:80])
        if not suc:
            revisar.append(f"Sucursal no reconocida («{lec.get('sitio', '')}»)")
        elif suc not in sucursales_permitidas:
            revisar.append("Sucursal fuera de tus unidades")
        if not fecha:
            revisar.append("Sin fecha")
        if suc and fecha and (suc, fecha.strftime("%d/%m/%Y")) in existentes:
            revisar.append("Ya hay reporte de ese día")
        if str(lec.get("dudas") or "").strip():
            revisar.append("IA: " + str(lec["dudas"])[:100])
        filas.append({"Guardar": not revisar or revisar == [], "Foto": i, "Sucursal": suc if suc in sucursales_permitidas else None,
                      "Fecha": fecha, "Costo": _flotante_seguro(lec.get("costo_unitario")),
                      "Folio inicial": _entero_seguro(lec.get("folio_inicial")), "Folio final": _entero_seguro(lec.get("folio_final")),
                      "Pagados": _entero_seguro(lec.get("boletos_pagados") or lec.get("total_entregados")),
                      "Cancelados": _entero_seguro(lec.get("boletos_cancelados")), "Perdidos": _entero_seguro(lec.get("boletos_perdidos")),
                      "Nómina": sueldos, "Otros gastos": otros, "Ingreso (hoja)": _flotante_seguro(lec.get("ingreso_bruto")),
                      "A entregar": _flotante_seguro(lec.get("cantidad_entregar")), "Elaboró": str(lec.get("elaboro") or ""),
                      "Recibió": str(lec.get("recibio") or ""), "Revisar": " · ".join(revisar)})
    st.markdown(f"**{len(filas)} reporte(s) leído(s).** Corrige lo que haga falta (sucursal, fecha, números) y deja marcada la casilla «Guardar».")
    tabla = st.data_editor(
        pd.DataFrame(filas), use_container_width=True, hide_index=True, key=f"masiva_tabla_{n_m}_{len(filas)}",
        disabled=["Foto", "Ingreso (hoja)", "Revisar"],
        column_config={"Guardar": st.column_config.CheckboxColumn("Guardar"),
                       "Sucursal": st.column_config.SelectboxColumn("Sucursal", options=list(sucursales_permitidas)),
                       "Fecha": st.column_config.DateColumn("Fecha", format="DD/MM/YYYY"),
                       **{c: st.column_config.NumberColumn(c, format="$%.2f") for c in ("Costo", "Nómina", "Otros gastos", "Ingreso (hoja)", "A entregar")}})
    with st.expander("🖼️ Ver las fotos (el número es la columna «Foto»)"):
        cols_f = st.columns(3)
        for i, f in enumerate(fotos, start=1):
            cols_f[(i - 1) % 3].image(f, caption=f"Foto {i}", use_container_width=True)
    reemplazar = es_contador and st.checkbox("Reemplazar si ya existe reporte de esa sucursal y día (solo Contador)", key=f"masiva_reempl_{n_m}")
    if st.button("💾 Guardar los reportes marcados", type="primary", use_container_width=True, key=f"masiva_guardar_{n_m}"):
        reportes_act = _leer_lista_json(FISICOS_FILE)
        guardados, saltados, fechas_por_sup = [], [], {}
        for fila in tabla.to_dict("records"):
            if not fila.get("Guardar"):
                continue
            suc, fecha = fila.get("Sucursal"), fecha_de_celda(fila.get("Fecha"), None)
            if not suc or not fecha:
                saltados.append(f"Foto {fila['Foto']}: falta sucursal o fecha")
                continue
            previo = next((r for r in reportes_act if r.get("tipo_reporte") == "ingresos" and r.get("Sitio / Unidad") == suc
                           and r.get("Fecha") == fecha.strftime("%d/%m/%Y")), None)
            if previo and not reemplazar:
                saltados.append(f"Foto {fila['Foto']}: ya existe el reporte de {suc} del {fecha:%d/%m/%Y}")
                continue
            if previo:
                borrar_reporte_fisico(previo.get("ID"))
            rid, bruto = guardar_reporte_ingresos_leido(suc, fecha, fila, fotos[int(fila["Foto"]) - 1].getvalue(),
                                                        st.session_state.usuario_autenticado)
            guardados.append(f"{suc} {fecha:%d/%m} (${bruto:,.0f})")
            sup_k = supervisor_de_sucursal(suc)
            if sup_k:
                fechas_por_sup.setdefault(sup_k, set()).add(fecha)
        extra = ""
        for sup_k, fechas_k in fechas_por_sup.items():
            if _info_cuenta_servicio() and (config_hojas_supervisores().get(sup_k) or {}).get("url"):
                try:
                    n_c, difs_c = llenar_hoja_supervisor(sup_k, fechas_k)
                    extra += f" ✍️ Hoja de {SUPERVISORES_NOMBRE.get(sup_k, sup_k)}: {n_c} dato(s)" + (f", {len(difs_c)} con otro número" if difs_c else "") + "."
                except Exception as exc:
                    extra += f" ⚠️ Hoja de {SUPERVISORES_NOMBRE.get(sup_k, sup_k)}: {exc}"
        st.session_state["masiva_nonce"] = n_m + 1
        st.session_state["rf_aviso_guardado"] = (f"✅ {len(guardados)} reporte(s) guardado(s): " + ", ".join(guardados[:12])
                                                 + ("…" if len(guardados) > 12 else "") + "." + extra
                                                 + (f" ⚠️ No se guardaron {len(saltados)}: " + "; ".join(saltados[:6]) if saltados else ""))
        st.rerun()


def vista_conciliacion_hojas(es_contador, clave_propia):
    claves = list(SUPERVISORES_NOMBRE) if es_contador else [clave_propia]
    con_datos = {c: semanas_hoja_supervisor(c) for c in claves}
    con_datos = {c: v for c, v in con_datos.items() if v}
    if not con_datos:
        st.info("Aún no hay hojas de supervisores leídas. Conéctalas en **💸 Gastos por semana › 🔗 Hojas de Google de los supervisores**.")
        return
    c1, c2 = st.columns(2)
    clave = c1.selectbox("Supervisor", list(con_datos), format_func=lambda c: SUPERVISORES_NOMBRE.get(c, c), key="conc_sup")
    if clave not in con_datos:
        clave = next(iter(con_datos))
    semanas = sorted(con_datos[clave], reverse=True)
    rango_txt = lambda s_: f"{fecha_de_celda(s_):%d/%m/%Y} al {fecha_de_celda(s_) + timedelta(days=6):%d/%m/%Y}"
    dia_sel = c2.date_input("Semana a revisar (toca para abrir el calendario)", value=fecha_de_celda(semanas[0]),
                            format="DD/MM/YYYY", key=f"conc_dia_{clave}",
                            help="Elige cualquier día: se revisa la semana de lunes a domingo que lo contiene.")
    lunes_sel = dia_sel - timedelta(days=dia_sel.weekday())
    st.caption("📅 Semanas con hoja de " + SUPERVISORES_NOMBRE.get(clave, clave) + ": " + " · ".join(rango_txt(s_) for s_ in semanas))
    lunes_txt = str(lunes_sel)
    if lunes_txt not in con_datos[clave]:
        st.warning(f"No hay hoja de {SUPERVISORES_NOMBRE.get(clave, clave)} para la semana del {rango_txt(lunes_txt)}. "
                   "Elige en el calendario un día de alguna de las semanas de arriba.")
        return
    hoja = con_datos[clave][lunes_txt]
    lunes = fecha_de_celda(lunes_txt)
    if _info_cuenta_servicio():
        with st.expander("✍️ Llenar la hoja de Google con los reportes físicos de esta semana"):
            st.caption("Pasa a la hoja del supervisor los autos y el gasto del día de cada reporte físico. Solo llena celdas vacías; "
                       "si una celda ya tiene otro número, la marca para revisarla (no la cambia).")
            if st.button("👀 Ver qué se va a llenar", key=f"llenar_ver_{clave}_{lunes_txt}"):
                try:
                    with st.spinner("Revisando la hoja…"):
                        _, plan_v = plan_llenado_hoja(clave, {lunes + timedelta(days=i_) for i_ in range(7)})
                    st.session_state[f"plan_llenado_{clave}_{lunes_txt}"] = plan_v
                except RuntimeError as exc:
                    st.error(str(exc))
            plan_v = st.session_state.get(f"plan_llenado_{clave}_{lunes_txt}")
            if plan_v is not None:
                if not plan_v:
                    st.info("No hay reportes físicos de esta semana que pasar a la hoja.")
                else:
                    df_pl = pd.DataFrame(plan_v)
                    df_pl["Qué pasa"] = df_pl["accion"].map({"llenar": "✍️ Se llena", "igual": "✅ Ya coincide", "diferente": "⚠️ Hoja tiene otro número"})
                    st.dataframe(df_pl[["Sucursal", "Día", "Dato", "En la hoja", "Del reporte", "Qué pasa", "celda"]],
                                 use_container_width=True, hide_index=True)
                    n_llenar = int((df_pl["accion"] == "llenar").sum())
                    if n_llenar and st.button(f"✍️ Llenar {n_llenar} celda(s) en la hoja", type="primary", key=f"llenar_ok_{clave}_{lunes_txt}"):
                        try:
                            n_ok, _ = llenar_hoja_supervisor(clave, {lunes + timedelta(days=i_) for i_ in range(7)})
                            st.session_state.pop(f"plan_llenado_{clave}_{lunes_txt}", None)
                            st.success(f"✅ Se llenaron {n_ok} celda(s) en la hoja. Toca 🔄 Leer ahora para ver los números actualizados.")
                        except RuntimeError as exc:
                            st.error(str(exc))
    modo_v = st.radio("Ver", ["📊 Diferencias de la semana", "📄 Hoja abierta + reportes físicos"], horizontal=True, key="conc_modo",
                      label_visibility="collapsed")
    if modo_v.startswith("📄"):
        vista_comprobar_hoja(clave, hoja, lunes_txt)
        return
    st.caption(f"Hoja leída el {hoja.get('leido_en', '')} · «{hoja.get('titulo_semana', '')}»")
    if hoja.get("sin_reconocer"):
        st.warning("Unidades de la hoja que no se reconocieron como sucursal: " + ", ".join(hoja["sin_reconocer"]))
    if hoja.get("revision"):
        with st.expander(f"🧮 Revisión de sumas de la hoja · {len(hoja['revision'])} aviso(s)", expanded=True):
            for aviso in hoja["revision"]:
                st.markdown(f"- ⚠️ {aviso}")
    sucursales = sorted({r["sucursal"] for r in hoja.get("resumen", []) if r.get("sucursal")} |
                        {a["sucursal"] for a in hoja.get("autos", []) if a.get("sucursal")})
    fis, gas, app_v, app_c = _datos_app_semana(lunes, sucursales)
    dias = [lunes + timedelta(days=i) for i in range(7)]
    autos_h = {(a["sucursal"], a["dia"]): a["valor"] for a in hoja.get("autos", []) if a.get("sucursal")}
    gastos_h = {(g["sucursal"], g["dia"]): g["valor"] for g in hoja.get("gastos_dia", []) if g.get("sucursal")}
    resumen_h = {r["sucursal"]: r for r in hoja.get("resumen", []) if r.get("sucursal")}
    filas = []
    for suc in sucursales:
        rh = resumen_h.get(suc, {})
        v_fis = sum(fis.get((suc, d), {}).get("vehiculos", 0) for d in dias)
        i_fis = sum(fis.get((suc, d), {}).get("ingreso", 0.0) for d in dias)
        filas.append({
            "Sucursal": suc, "Bloque": rh.get("bloque", ""),
            "Autos hoja": rh.get("vehiculos", sum(autos_h.get((suc, i), 0) for i in range(7))),
            "Autos reporte físico": v_fis, "Autos app": sum(app_v.get((suc, d), 0) for d in dias),
            "Ingreso hoja": rh.get("ingreso"), "Ingreso reporte físico": i_fis, "Cobros app": sum(app_c.get((suc, d), 0.0) for d in dias),
            "Gasto hoja": rh.get("gastos", sum(gastos_h.get((suc, i), 0) for i in range(7))),
            "Gasto registrado": sum(gas.get((suc, d), 0.0) for d in dias),
            "Días sin reporte físico": sum(1 for i, d in enumerate(dias) if autos_h.get((suc, i), 0) > 0 and (suc, d) not in fis),
        })
    df = pd.DataFrame(filas)
    if df.empty:
        st.warning("La hoja de esa semana no trae unidades reconocidas.")
        return
    df["Dif. autos"] = df["Autos hoja"] - df["Autos reporte físico"]
    df["Dif. ingreso"] = df["Ingreso hoja"].fillna(0) - df["Ingreso reporte físico"]
    df["Dif. gasto"] = df["Gasto hoja"] - df["Gasto registrado"]
    sup_total = float(sum(s_["importe"] for s_ in hoja.get("supervision", [])))
    ing_hoja, ing_rep = float(df["Ingreso hoja"].fillna(0).sum()), float(df["Ingreso reporte físico"].sum())
    gas_hoja, gas_reg = float(df["Gasto hoja"].fillna(0).sum()), float(df["Gasto registrado"].sum())
    util_hoja = ing_hoja - gas_hoja - sup_total
    util_rep = ing_rep - gas_reg - sup_total
    k1, k2, k3 = st.columns(3)
    k1.metric("Ingreso según hoja", f"${ing_hoja:,.2f}")
    k2.metric("Ingreso reportes físicos", f"${ing_rep:,.2f}", delta=f"{ing_rep - ing_hoja:+,.2f}")
    k3.metric("Gasto unidades (hoja)", f"${gas_hoja:,.2f}")
    k4, k5, k6 = st.columns(3)
    k4.metric("Gasto de supervisión", f"${sup_total:,.2f}")
    k5.metric("Utilidad según hoja", f"${util_hoja:,.2f}", help="Ingreso − gasto de unidades − gasto de supervisión, con los números de la hoja.")
    k6.metric("Utilidad según reportes físicos", f"${util_rep:,.2f}", delta=f"{util_rep - util_hoja:+,.2f}",
              help="Ingreso de los reportes físicos − gastos registrados − gasto de supervisión.")
    no_cuadran = df[(df["Dif. autos"].abs() > 0) | (df["Dif. ingreso"].abs() > 0.5) | (df["Dif. gasto"].abs() > 0.5)]
    if no_cuadran.empty:
        st.success("✅ Todas las sucursales cuadran entre la hoja del supervisor y los reportes físicos.")
    else:
        st.error(f"🔴 {len(no_cuadran)} sucursal(es) no cuadran entre la hoja y los reportes físicos/gastos registrados.")
    st.markdown("#### Semana por sucursal")
    tot_sem = {"Sucursal": "TOTAL", "Bloque": ""}
    for c in df.columns:
        if c not in ("Sucursal", "Bloque"):
            tot_sem[c] = float(pd.to_numeric(df[c], errors="coerce").fillna(0).sum())
    df = pd.concat([df, pd.DataFrame([tot_sem])], ignore_index=True)
    estilo = df.style.map(lambda v: "background-color:#FDE2E1;color:#9B1C1C;font-weight:700" if isinstance(v, (int, float)) and abs(v) > 0.5 else "",
                          subset=["Dif. autos", "Dif. ingreso", "Dif. gasto", "Días sin reporte físico"])
    estilo = estilo.apply(lambda fila: ["font-weight:800;background-color:#EAF5EE" if fila["Sucursal"] == "TOTAL" else "" for _ in fila], axis=1)
    st.dataframe(estilo, use_container_width=True, hide_index=True, column_config={
        **{c: st.column_config.NumberColumn(c, format="$%.2f") for c in ("Ingreso hoja", "Ingreso reporte físico", "Cobros app",
                                                                       "Gasto hoja", "Gasto registrado", "Dif. ingreso", "Dif. gasto")},
        **{c: st.column_config.NumberColumn(c, format="%d") for c in ("Autos hoja", "Autos reporte físico", "Autos app", "Dif. autos",
                                                                    "Días sin reporte físico")}})
    df = df[df["Sucursal"] != "TOTAL"].reset_index(drop=True)
    sucs_entrega = set()
    # 1) Entregas que RECIBE este supervisor (vienen en su hoja) contra la hoja de quien las entrega
    for n_e, ent in enumerate(hoja.get("entregas", [])):
        sucs_entrega |= set(ent.get("sucursales") or [])
        _vista_cuadre_entrega(ent, receptor=clave, hoja_receptor=hoja, lunes_txt=lunes_txt, clave_ui=f"r{n_e}")
    # 2) Entregas que HIZO este supervisor y que aparecen en la hoja de otro
    for otra in SUPERVISORES_NOMBRE:
        if otra == clave:
            continue
        hoja_o = semanas_hoja_supervisor(otra).get(lunes_txt)
        for n_e, ent in enumerate((hoja_o or {}).get("entregas", [])):
            if ent.get("de") == clave:
                sucs_entrega |= set(ent.get("sucursales") or [])
                _vista_cuadre_entrega(ent, receptor=otra, hoja_receptor=hoja_o, lunes_txt=lunes_txt, clave_ui=f"h{otra}{n_e}")
    if es_contador:   # otras sucursales que aparecen en las dos hojas (fuera de las entregas)
        cruces = []
        for otra in SUPERVISORES_NOMBRE:
            if otra == clave:
                continue
            hoja_o = semanas_hoja_supervisor(otra).get(lunes_txt)
            if not hoja_o:
                continue
            res_o = {r["sucursal"]: r for r in hoja_o.get("resumen", []) if r.get("sucursal")}
            for suc, r1 in resumen_h.items():
                r2 = res_o.get(suc)
                if not r2 or suc in sucs_entrega:
                    continue
                difs = {k: (r1.get(k, 0), r2.get(k, 0)) for k in ("vehiculos", "ingreso", "gastos") if abs((r1.get(k) or 0) - (r2.get(k) or 0)) > 0.5}
                if difs:
                    cruces.append({"Sucursal": suc, **{f"{k.capitalize()} {SUPERVISORES_NOMBRE.get(clave, clave).split()[0]}": v[0] for k, v in difs.items()},
                                   **{f"{k.capitalize()} {SUPERVISORES_NOMBRE.get(otra, otra).split()[0]}": v[1] for k, v in difs.items()}})
        if cruces:
            st.warning(f"⚠️ {len(cruces)} sucursal(es) aparecen en las dos hojas con números distintos:")
            st.dataframe(pd.DataFrame(cruces), use_container_width=True, hide_index=True)
    st.markdown("#### Día por día")
    suc_d = st.selectbox("Sucursal", list(df["Sucursal"]), key="conc_suc")
    filas_d = []
    for i, d in enumerate(dias):
        filas_d.append({"Día": f"{NOMBRES_DIA[i][:3]} {d:%d/%m}", "Autos hoja": autos_h.get((suc_d, i)),
                        "Autos reporte físico": fis.get((suc_d, d), {}).get("vehiculos"), "Autos app": app_v.get((suc_d, d)),
                        "Ingreso reporte físico": fis.get((suc_d, d), {}).get("ingreso"), "Cobros app": app_c.get((suc_d, d)),
                        "Gasto hoja": gastos_h.get((suc_d, i)), "Gasto registrado": gas.get((suc_d, d))})
    df_d = pd.DataFrame(filas_d)
    for c in df_d.columns[1:]:
        df_d[c] = pd.to_numeric(df_d[c], errors="coerce")
    tot_d = {"Día": "TOTAL"}
    tot_d.update({c: float(df_d[c].fillna(0).sum()) for c in df_d.columns[1:]})
    df_d = pd.concat([df_d, pd.DataFrame([tot_d])], ignore_index=True)
    estilo_d = df_d.style.apply(lambda fila: ["font-weight:800;background-color:#EAF5EE" if fila["Día"] == "TOTAL" else "" for _ in fila], axis=1)
    st.dataframe(estilo_d, use_container_width=True, hide_index=True, column_config={
        **{c: st.column_config.NumberColumn(c, format="$%.2f") for c in ("Ingreso reporte físico", "Cobros app", "Gasto hoja", "Gasto registrado")},
        **{c: st.column_config.NumberColumn(c, format="%d") for c in ("Autos hoja", "Autos reporte físico", "Autos app")}})
    st.caption("La hoja trae autos y gastos por día; el ingreso de la hoja es semanal (por eso el día a día compara ingreso contra el reporte físico y la app).")
    sup = hoja.get("supervision", [])
    if sup:
        st.markdown(f"#### 👔 Gasto de supervisión · ${sum(s['importe'] for s in sup):,.2f}")
        st.dataframe(pd.DataFrame([{"Concepto": s["concepto"], "Importe": s["importe"], "Fecha": s.get("fecha") or ""} for s in sup]),
                     use_container_width=True, hide_index=True,
                     column_config={"Importe": st.column_config.NumberColumn("Importe", format="$%.2f")})
    buffer = io.BytesIO()
    with pd.ExcelWriter(buffer, engine="xlsxwriter") as xw:
        df.to_excel(xw, sheet_name="Semana por sucursal", index=False)
        filas_todas = []
        for suc in df["Sucursal"]:
            for i, d in enumerate(dias):
                filas_todas.append({"Sucursal": suc, "Fecha": d.strftime("%d/%m/%Y"), "Día": NOMBRES_DIA[i],
                                    "Autos hoja": autos_h.get((suc, i)), "Autos reporte físico": fis.get((suc, d), {}).get("vehiculos"),
                                    "Autos app": app_v.get((suc, d)), "Ingreso reporte físico": fis.get((suc, d), {}).get("ingreso"),
                                    "Cobros app": app_c.get((suc, d)), "Gasto hoja": gastos_h.get((suc, i)), "Gasto registrado": gas.get((suc, d))})
        pd.DataFrame(filas_todas).to_excel(xw, sheet_name="Día por día", index=False)
        pd.DataFrame(sup or [{"concepto": "", "importe": 0}]).to_excel(xw, sheet_name="Gasto supervisión", index=False)
        pd.DataFrame({"Revisión de la hoja": hoja.get("revision") or ["Sin avisos"]}).to_excel(xw, sheet_name="Revisión", index=False)
    st.download_button("⬇️ Descargar conciliación (Excel)", buffer.getvalue(),
                       file_name=f"Conciliacion_{SUPERVISORES_NOMBRE.get(clave, clave).replace(' ', '_')}_{lunes:%Y%m%d}.xlsx",
                       mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", use_container_width=True, key="conc_xls")


